package com.slayerplus;

import static org.junit.Assert.*;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.ui.overlay.OverlayPosition;
import org.junit.Test;

public class SlayerPreparationReminderTest {
  @Test
  public void runeConsumptionStopsSchedulingRefreshesAfterSetup() {
    assertFalse(SlayerPlusPlugin.shouldRefreshProgress(-1, true));
    assertTrue(SlayerPlusPlugin.shouldRefreshProgress(-1, false));
    assertTrue(SlayerPlusPlugin.shouldRefreshProgress(VarPlayerID.SLAYER_COUNT, true));
    assertTrue(SlayerPlusPlugin.shouldRefreshProgress(VarPlayerID.SLAYER_COUNT, false));
  }

  @Test
  public void fulfilledTaskDoesNotRecheckDuringCombatOrWorldHop() {
    for (int remaining = 100; remaining > 0; remaining--) {
      assertFalse(
          SlayerPlusPlugin.shouldRefreshPreparation(
              true, "task", "task", remaining + 1, remaining));
    }
    assertFalse(SlayerPlusPlugin.shouldRefreshPreparation(true, "task", "task", 75, 75));
    assertFalse(SlayerPlusPlugin.shouldRefreshPreparation(true, "task", "task", -1, 75));
  }

  @Test
  public void pendingAndNewTaskRequirementsAreCheckedAgain() {
    assertTrue(SlayerPlusPlugin.shouldRefreshPreparation(false, "task", "task", 75, 75));
    assertTrue(SlayerPlusPlugin.shouldRefreshPreparation(true, "old task", "new task", 75, 60));
    assertTrue(SlayerPlusPlugin.shouldRefreshPreparation(true, "same task", "same task", 1, 150));
    assertTrue(SlayerPlusPlugin.shouldRefreshPreparation(true, "", "task", 75, 75));
    assertTrue(SlayerPlusPlugin.shouldRefreshPreparation(true, "task|melee", "task|magic", 75, 75));
  }

  @Test
  public void cachedRowsSurviveRenderingAndEquivalentUpdates() {
    SlayerTaskReadinessOverlay overlay = new SlayerTaskReadinessOverlay(new SlayerPlusPlugin());
    overlay.update(plan(false, false, false));
    assertEquals(OverlayPosition.TOP_RIGHT, overlay.getPosition());
    assertTrue(overlay.isMovable());
    assertFalse(overlay.isResizable());
    assertEquals(240, overlay.getPanelComponent().getPreferredSize().width);
    assertFalse(overlay.isClearChildren());
    int count = overlay.getPanelComponent().getChildren().size();
    assertEquals(6, count); // Title, spellbook, spell, three rune rows; no explanatory footer.
    Object firstRow = overlay.getPanelComponent().getChildren().get(0);
    Graphics2D graphics = new BufferedImage(500, 500, BufferedImage.TYPE_INT_ARGB).createGraphics();
    try {
      assertNotNull(overlay.render(graphics));
      assertNotNull(overlay.render(graphics));
      assertEquals(count, overlay.getPanelComponent().getChildren().size());
      overlay.update(plan(false, false, false));
      assertSame(firstRow, overlay.getPanelComponent().getChildren().get(0));
    } finally {
      graphics.dispose();
    }
  }

  @Test
  public void panelHidesWhenReadyAndReturnsForAnotherIncompleteSetup() {
    SlayerTaskReadinessOverlay overlay = new SlayerTaskReadinessOverlay(new SlayerPlusPlugin());
    overlay.update(plan(false, true, false));
    assertFalse(overlay.getPanelComponent().getChildren().isEmpty());
    overlay.update(plan(false, false, true));
    assertFalse(overlay.getPanelComponent().getChildren().isEmpty());
    overlay.update(plan(true, true, true));
    assertTrue(overlay.getPanelComponent().getChildren().isEmpty());
    assertNull(overlay.render(null));
    overlay.update(plan(false, false, false));
    assertFalse(overlay.getPanelComponent().getChildren().isEmpty());
    overlay.update(PreparationCatalog.PreparationPlan.none());
    assertNull(overlay.render(null));
    assertTrue(overlay.getPanelComponent().getChildren().isEmpty());
  }

  @Test
  public void requiredSupportingItemIsVisibleInsteadOfBeingAHiddenBlocker() {
    PreparationCatalog.PreparationPlan plan =
        new PreparationCatalog.PreparationPlan(
            true,
            false,
            "Setup",
            "Bring Book of the dead.",
            "",
            "",
            Collections.emptyList(),
            MethodRules.Spellbook.ARCEUUS,
            true,
            true,
            99,
            Collections.emptyList(),
            "Resurrect Greater Ghost",
            0,
            true,
            "Book of the dead",
            false);
    SlayerTaskReadinessOverlay overlay = new SlayerTaskReadinessOverlay(new SlayerPlusPlugin());
    overlay.update(plan);
    assertEquals(4, overlay.getPanelComponent().getChildren().size());
    assertFalse(plan.isRequiredItemReady());
  }

  @Test
  public void arceuusReminderListsEachActualSpellEvenWithNoRunes() {
    TaskStrategy strategy =
        SlayerTaskStrategyCatalog.resolve(
            "Araxxor",
            Preference.Cannon.NEVER,
            Preference.Burst.NEVER,
            Preference.CombatStyle.AUTOMATIC,
            "Morytania Spider Cave",
            false);
    PreparationCatalog.PreparationPlan plan =
        PreparationCatalog.resolve(
            "Araxxor", "Morytania Spider Cave", strategy, null, null, null, Collections.emptyMap());
    assertTrue(plan.getSpellName().contains("Resurrect Greater Ghost"));
    assertTrue(plan.getSpellName().contains("Death Charge"));
    SlayerTaskReadinessOverlay overlay = new SlayerTaskReadinessOverlay(new SlayerPlusPlugin());
    overlay.update(plan);
    int spellCount = plan.getSpellName().split("\\s*\\+\\s*").length;
    assertEquals(
        2
            + spellCount
            + (plan.getRequiredItemName().isEmpty() ? 0 : 1)
            + (plan.isLevelReady() ? 0 : 1)
            + plan.getRuneStatuses().size(),
        overlay.getPanelComponent().getChildren().size());
  }

  private static PreparationCatalog.PreparationPlan plan(
      boolean ready, boolean bookReady, boolean runesReady) {
    return new PreparationCatalog.PreparationPlan(
        true,
        ready,
        "Setup",
        ready ? "Ready" : "Check spellbook and rune pouch.",
        "Load Water, Blood and Death runes",
        "",
        Collections.emptyList(),
        MethodRules.Spellbook.ANCIENT,
        bookReady,
        true,
        99,
        Arrays.asList(
            new PreparationCatalog.RuneStatus("Water", 6, runesReady ? 600 : 0),
            new PreparationCatalog.RuneStatus("Blood", 2, runesReady ? 200 : 0),
            new PreparationCatalog.RuneStatus("Death", 4, runesReady ? 400 : 0)),
        "Ice Barrage",
        runesReady ? 100 : 0,
        runesReady);
  }
}

package com.slayerplus;

import static org.junit.Assert.*;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class PoweredMagicTest {
  @Test
  public void actualBarrowsCatalogFollowsRecommendedWeapon() {
    TaskStrategy strategy =
        SlayerTaskStrategyCatalog.resolve(
            "Barrows Brothers",
            Preference.Cannon.NEVER,
            Preference.Burst.NEVER,
            Preference.CombatStyle.AUTOMATIC,
            "Barrows",
            false);
    assertNotNull(strategy);
    assertFalse(
        PreparationCatalog.resolve(
                "Barrows Brothers",
                "Barrows",
                strategy,
                null,
                null,
                null,
                Collections.emptyMap(),
                ItemID.TUMEKENS_SHADOW)
            .isActive());
    assertTrue(
        PreparationCatalog.resolve(
                "Barrows Brothers",
                "Barrows",
                strategy,
                null,
                null,
                null,
                Collections.emptyMap(),
                ItemID.SLAYER_STAFF)
            .isActive());
  }

  @Test
  public void sharedRuleUsesSelectedWeaponForEveryTask() {
    TaskStrategy strategy = strategy();
    for (String task : Arrays.asList("Barrows Brothers", "Fire giants", "Blue dragons")) {
      for (int weapon :
          new int[] {
            ItemID.TUMEKENS_SHADOW,
            ItemID.TOTS_CHARGED,
            ItemID.SANGUINESTI_STAFF,
            ItemID.WARPED_SCEPTRE,
            ItemID.EYE_OF_AYAK,
            ItemID.WILD_CAVE_SCEPTRE_CHARGED,
            ItemID.WILD_CAVE_ACCURSED_CHARGED,
            ItemID.RAT_BONE_STAFF
          }) {
        MethodRules rules = SlayerMethodRuleCatalog.resolve(task, "", strategy, weapon);
        assertTrue(task, rules.getPouchRunes().isEmpty());
        assertFalse(task, rules.requiresRunePouch());
        assertFalse(
            task,
            PreparationCatalog.resolve(
                    task, "", strategy, null, null, null, Collections.emptyMap(), weapon)
                .isActive());
      }
      MethodRules normal = SlayerMethodRuleCatalog.resolve(task, "", strategy, ItemID.SLAYER_STAFF);
      assertEquals(task, MethodRules.Spellbook.STANDARD, normal.getSpellbook());
      assertFalse(task, normal.getPouchRunes().isEmpty());
    }
  }

  @Test
  public void explicitCombatPackagesAreRemovedButUtilityAndFreezesStay() {
    for (String spell : Arrays.asList("Fire Surge", "Water Wave / Fire Wave", "Magic Dart")) {
      MethodRules rules =
          spell(MethodRules.Spellbook.STANDARD, spell).withoutStandardCombatSpell().build();
      assertEquals(MethodRules.Spellbook.NONE, rules.getSpellbook());
      assertTrue(rules.getPouchRunes().isEmpty());
      assertFalse(rules.requiresRunePouch());
    }
    for (String utility : Arrays.asList("Crumble Undead", "High Level Alchemy")) {
      MethodRules rules =
          spell(MethodRules.Spellbook.STANDARD, utility).withoutStandardCombatSpell().build();
      assertEquals(MethodRules.Spellbook.STANDARD, rules.getSpellbook());
      assertFalse(rules.getPouchRunes().isEmpty());
    }
    for (MethodRules.Spellbook book :
        Arrays.asList(MethodRules.Spellbook.ANCIENT, MethodRules.Spellbook.ARCEUUS)) {
      MethodRules rules = spell(book, "Encounter spell").withoutStandardCombatSpell().build();
      assertEquals(book, rules.getSpellbook());
      assertTrue(rules.requiresRunePouch());
    }
    MethodRules thralls =
        SlayerMethodRuleCatalog.resolve("Zulrah", "", strategy(), ItemID.TUMEKENS_SHADOW);
    assertEquals(MethodRules.Spellbook.ARCEUUS, thralls.getSpellbook());
    assertTrue(thralls.usesThralls());
    MethodRules alchemy =
        SlayerMethodRuleCatalog.resolve("Bloodveld", "", strategy(), ItemID.TUMEKENS_SHADOW);
    assertEquals(MethodRules.Spellbook.STANDARD, alchemy.getSpellbook());
    assertTrue(
        alchemy.getPouchRunes().stream().anyMatch(rune -> rune.getItemId() == ItemID.NATURERUNE));
    assertFalse(
        alchemy.getPouchRunes().stream().anyMatch(rune -> rune.getItemId() == ItemID.WRATHRUNE));
  }

  @Test
  public void inventoryAndReminderAgreeAndWeaponSlotIsNotAmmoSlot() {
    SlayerLoadoutAnalyzer analyzer = new SlayerLoadoutAnalyzer(null);
    List<KitItem> equipment =
        Arrays.asList(
            null,
            null,
            null,
            new KitItem("Shadow in wrong slot", ItemID.TUMEKENS_SHADOW, 1, KitItem.Status.BANK),
            new KitItem("Slayer staff", ItemID.SLAYER_STAFF, 1, KitItem.Status.BANK));
    assertEquals(ItemID.SLAYER_STAFF, PoweredMagic.weaponId(equipment));
    assertEquals(-1, PoweredMagic.weaponId(Collections.emptyList()));
    assertTrue(hasPouch(inventory(analyzer, equipment)));
    equipment.set(4, new KitItem("Shadow", ItemID.TUMEKENS_SHADOW, 1, KitItem.Status.BANK));
    assertFalse(hasPouch(inventory(analyzer, equipment)));
  }

  private static TaskStrategy strategy() {
    return TaskStrategy.builder(TaskStrategy.CombatStyle.MAGIC, "Use Air spells")
        .runePouch(true)
        .reviewed("2026-09-02")
        .build();
  }

  private static MethodRules.Builder spell(MethodRules.Spellbook book, String name) {
    return MethodRules.builder()
        .spell(book, name)
        .runePouch(true)
        .pouchRune(ItemID.AIRRUNE, "Air", 100);
  }

  private static List<KitItem> inventory(SlayerLoadoutAnalyzer analyzer, List<KitItem> equipment) {
    return analyzer.buildInventoryLayout(
        "Barrows Brothers",
        strategy(),
        "",
        "",
        SlayerLoadoutAnalyzer.CombatStyle.MAGIC,
        Collections.emptyList(),
        false,
        8,
        Collections.emptyList(),
        true,
        equipment);
  }

  private static boolean hasPouch(List<KitItem> items) {
    return items.stream().anyMatch(item -> item.getDisplayName().equals("Rune pouch"));
  }
}

package com.slayerplus;

import static org.junit.Assert.assertEquals;

import java.util.Arrays;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class SlayerWaterbirthRouteRegressionTest {
  private static final List<WorldPoint> ROUTE =
      Arrays.asList(
          new WorldPoint(2620, 3684, 0),
          new WorldPoint(2543, 3741, 0),
          new WorldPoint(2546, 10144, 0),
          new WorldPoint(1807, 4405, 3),
          new WorldPoint(1823, 4404, 2));

  @Test
  public void holdsAtMainlandDockUntilBoatTransition() {
    assertEquals(
        ROUTE.get(0), SlayerPlusPlugin.nextUnreachedStage(new WorldPoint(2621, 3683, 0), ROUTE));
  }

  @Test
  public void doesNotSkipShortcutOnWaterbirthArrival() {
    assertEquals(
        ROUTE.get(1), SlayerPlusPlugin.nextUnreachedStage(new WorldPoint(2546, 3755, 0), ROUTE));
  }

  @Test
  public void routesFromShortcutToCaveEntrance() {
    assertEquals(
        ROUTE.get(1), SlayerPlusPlugin.nextUnreachedStage(new WorldPoint(2547, 3744, 0), ROUTE));
  }

  @Test
  public void holdsAtCaveEntranceUntilDungeonTransition() {
    assertEquals(
        ROUTE.get(1), SlayerPlusPlugin.nextUnreachedStage(new WorldPoint(2543, 3741, 0), ROUTE));
  }

  @Test
  public void holdsAtDungeonLadderUntilTransition() {
    assertEquals(
        ROUTE.get(2), SlayerPlusPlugin.nextUnreachedStage(new WorldPoint(2546, 10144, 0), ROUTE));
  }

  @Test
  public void doesNotRestartRouteAfterDungeonLadderTransition() {
    assertEquals(
        ROUTE.get(3), SlayerPlusPlugin.nextUnreachedStage(new WorldPoint(1799, 4406, 3), ROUTE));
  }

  @Test
  public void usesRecordedPlaneForNextDungeonStage() {
    assertEquals(
        ROUTE.get(4), SlayerPlusPlugin.nextUnreachedStage(new WorldPoint(1815, 4405, 2), ROUTE));
  }

  @Test
  public void maxCapeWaterbirthRouteHighlightsHome() {
    assertEquals(true, SlayerPlusPlugin.usesPohTravelItem("Max cape"));
    assertEquals(true, SlayerPlusPlugin.usesPohTravelItem("Construction cape"));
    assertEquals(false, SlayerPlusPlugin.usesPohTravelItem("Games necklace(8)"));
    assertEquals(
        "home",
        SlayerPlusPlugin.pohTravelDestination(
            "Waterbirth Island Dungeon", "Max cape", "rellekka"));
    assertEquals(
        "rellekka",
        SlayerPlusPlugin.pohTravelDestination(
            "Waterbirth Island Dungeon", "Fremennik sea boots 4", "rellekka"));
    assertEquals(
        "home",
        SlayerPlusPlugin.pohTravelDestination(
            "Ancient Guthixian Temple", "Max cape", "tears of guthix"));
  }
}

package com.slayerplus;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.JLabel;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class SlayerRegressionTest {

  @Test
  public void exactAssignmentChatRestoresTaskBeforeVarpsSettle() {
    final SlayerTaskChatUpdate assignment =
        SlayerTaskChatUpdate.parse("You're assigned to kill ankou; only 57 more to go.");
    assertNotNull(assignment);
    assertEquals("Ankou", assignment.getTaskName());
    assertEquals(57, assignment.getRemaining());
    assertEquals(57, SlayerPlusPlugin.firstPositive(0, -1, 57));
  }

  @Test
  public void exactStatusChatRestoresStreakAndPoints() {
    final SlayerTaskChatUpdate status =
        SlayerTaskChatUpdate.parse(
            "You\u2019ve completed 766 tasks in a row and currently have a total of 289 points.");
    assertNotNull(status);
    assertEquals(766, status.getStreak());
    assertEquals(289, status.getPoints());
    assertEquals(766, SlayerPlusPlugin.preferLiveOrProfileValue(0, 766, -1));
    assertEquals(289, SlayerPlusPlugin.preferLiveOrProfileValue(0, 0, 289));
  }

  @Test
  public void versionedSidebarIconIsPackagedWithThePlugin() {
    assertNotNull(SlayerPlusPlugin.class.getResource("slayerplus_sidebar_v2.png"));
  }

  @Test
  public void turaelPointBoostingUsesNineEasyTasksThenTheSelectedBonusMaster() {
    assertPointBoostDecision(0, 1, 1, false);
    assertPointBoostDecision(8, 9, 1, false);
    assertPointBoostDecision(9, 10, 8, true);
    assertPointBoostDecision(49, 50, 8, true);
    assertPointBoostDecision(99, 100, 8, true);
    assertPointBoostDecision(249, 250, 8, true);
    assertPointBoostDecision(999, 1000, 8, true);

    final BoostCoordinator.Decision duradel =
        BoostCoordinator.nextAssignment(759, Preference.BonusMaster.DURADEL);
    assertTrue(duradel.isBonusTask());
    assertEquals(760, duradel.getCompletionNumber());
    assertEquals(5, duradel.getMasterId());
    assertEquals("Bonus task 760", duradel.getProgressText());

    final BoostCoordinator.Decision afterBonus =
        BoostCoordinator.nextAssignment(760, Preference.BonusMaster.DURADEL);
    assertFalse(afterBonus.isBonusTask());
    assertEquals(1, afterBonus.getMasterId());
    assertEquals("Turael/Aya task 1 of 9", afterBonus.getProgressText());
  }

  @Test
  public void turaelWorkflowRecommendationCarriesItsCompactTripMarker() {
    final SlayerPlusConfig boostConfig =
        new SlayerPlusConfig() {
          @Override
          public Preference.Workflow slayerWorkflow() {
            return Preference.Workflow.TURAEL_POINT_BOOST;
          }
        };
    final SlayerRecommendationEngine engine = new SlayerRecommendationEngine(null, boostConfig);
    final Recommendation recommendation =
        engine.recommend("Bats", BoostCoordinator.TURAEL_AYA_MASTER_ID, "Not restricted");

    assertEquals("Silvarea limestone mine", recommendation.getLocation());
    assertTrue(recommendation.getStrategy().hasTag(TaskStrategy.MethodTag.TURAEL_POINT_BOOST));
    assertEquals(
        2,
        SlayerMethodRuleCatalog.resolve(
                "Bats", recommendation.getLocation(), recommendation.getStrategy())
            .resolveFoodSlots(
                recommendation.getStrategy(), recommendation.getStrategy().getFood()));
  }

  @Test
  public void turaelTravelKitKeepsSeveralTeleportsWithoutDuplicatingWornGear() {
    KitPlan plan =
        new KitPlan(
            "Ready",
            "Turael boost",
            Collections.singletonList(new KitItem("Max cape", 100, 1, KitItem.Status.EQUIPPED)),
            Collections.singletonList(
                new KitItem("Emergency food", 200, 1, KitItem.Status.BANK)
                    .withInventoryGroup(MethodRules.InventoryGroup.FOOD)),
            Collections.emptyList());

    /* Worn travel gear is not copied into the pack. */
    assertTrue(plan == SlayerPlusPlugin.appendMasterReturnTeleportForTest(plan, 100, "Max cape"));

    for (int id = 301; id <= 304; id++) {
      plan = SlayerPlusPlugin.appendMasterReturnTeleportForTest(plan, id, "Travel item " + id);
    }
    assertEquals(5, plan.getInventoryItems().size());
    assertEquals(
        4,
        plan.getInventoryItems().stream()
            .filter(item -> item.getDisplayName().startsWith("Travel item"))
            .count());
    assertEquals(
        1,
        plan.getInventoryItems().stream()
            .filter(item -> item.getInventoryGroup() == MethodRules.InventoryGroup.FOOD)
            .count());
  }

  @Test
  public void turaelHazardTasksKeepTheirNonNegotiableSupplies() {
    assertTuraelRequiredItem("Cave bugs", "Safe light source");
    assertTuraelRequiredItem("Cave slimes", "Safe light source");
    assertTuraelRequiredItem("Cave slimes", "Poison protection");
    assertTuraelRequiredItem("Cave crawlers", "Poison protection");
    assertTuraelRequiredItem("Lizards", "Ice coolers");
    assertTuraelRequiredItem("Lizards", "Desert heat protection");
    assertTuraelRequiredItem("Skeletons", "Rope");
  }

  @Test
  public void turaelNoCannonLocationsCannotInheritABroadCannonStrategy() {
    for (final String task :
        Arrays.asList(
            "Banshees",
            "Cave bugs",
            "Cave crawlers",
            "Cave slimes",
            "Crawling hands",
            "Dwarves",
            "Ghosts")) {
      final TuraelBoost.Entry entry = TuraelBoost.find(task);
      assertNotNull(task, entry);
      assertFalse(task, entry.supportsCannon());
      final TaskStrategy cannonStrategy =
          TaskStrategy.builder(TaskStrategy.CombatStyle.RANGED, "Cannon regression")
              .tags(TaskStrategy.MethodTag.CANNON, TaskStrategy.MethodTag.TURAEL_POINT_BOOST)
              .reviewed("2026-08-18")
              .build();
      final MethodRules rules =
          SlayerMethodRuleCatalog.resolve(task, entry.getLocation(), cannonStrategy);
      assertEquals(task, 0, rules.getCannonballQuantity());
    }
  }

  private static void assertTuraelRequiredItem(final String task, final String displayName) {
    final TuraelBoost.Entry entry = TuraelBoost.find(task);
    final TaskStrategy strategy =
        SlayerTaskStrategyCatalog.resolve(
                task,
                Preference.Cannon.ALLOW,
                Preference.Burst.NEVER,
                Preference.CombatStyle.AUTOMATIC,
                entry.getLocation(),
                false)
            .withAdditionalTags(TaskStrategy.MethodTag.TURAEL_POINT_BOOST);
    final MethodRules rules = SlayerMethodRuleCatalog.resolve(task, entry.getLocation(), strategy);
    assertTrue(
        task + " -> " + displayName,
        rules.getRequiredItems().stream()
            .anyMatch(item -> item.getDisplayName().equals(displayName)));
  }

  private static void assertPointBoostDecision(
      final int completedStreak,
      final int completionNumber,
      final int masterId,
      final boolean bonusTask) {
    final BoostCoordinator.Decision decision =
        BoostCoordinator.nextAssignment(completedStreak, Preference.BonusMaster.KONAR);
    assertEquals(completionNumber, decision.getCompletionNumber());
    assertEquals(masterId, decision.getMasterId());
    assertEquals(bonusTask, decision.isBonusTask());
  }

  @Test
  public void skeletalWyvernsUseProtectedProgressiveGearAndReviewedSupplies() {
    final TaskStrategy melee =
        SlayerTaskStrategyCatalog.resolve(
            "Skeletal wyverns",
            Preference.Cannon.NEVER,
            Preference.Burst.NEVER,
            Preference.CombatStyle.AUTOMATIC,
            "Asgarnian Ice Dungeon",
            false);
    assertEquals(TaskStrategy.CombatStyle.MELEE, melee.getStyle());
    assertEquals("dragon hunter lance", melee.getWeaponPriorities().get(0));
    assertTrue(melee.getWeaponPriorities().contains("abyssal whip"));
    assertFalse(melee.getWeaponPriorities().contains("osmumten s fang"));

    final List<String> meleeShields =
        SlayerEquipmentAuditCatalog.priorities(
            "Skeletal wyverns", melee, EquipmentInventorySlot.SHIELD, "Dragon hunter lance");
    assertEquals("ancient wyvern shield", meleeShields.get(0));
    assertTrue(meleeShields.contains("elemental shield"));
    assertFalse(meleeShields.contains("anti dragon shield"));

    final MethodRules meleeRules =
        SlayerMethodRuleCatalog.resolve("Skeletal wyverns", "Asgarnian Ice Dungeon", melee);
    assertEquals(4, meleeRules.resolveRestoreSlots(melee));
    assertEquals(8, meleeRules.resolveFoodSlots(melee, melee.getFood()));
    assertTrue(meleeRules.includesStyleBoost());
    assertTrue(
        meleeRules.getRequiredItems().stream()
            .anyMatch(
                item ->
                    item.getDisplayName().equals("Special attack weapon")
                        && item.getSlotCount() == 1));
    assertEquals(MethodRules.Spellbook.STANDARD, meleeRules.getSpellbook());
    assertEquals("High Level Alchemy", meleeRules.getPrimarySpell());
    assertTrue(meleeRules.requiresRunePouch());
    assertFalse(
        meleeRules.getRequiredItems().stream()
            .anyMatch(item -> item.getDisplayName().toLowerCase().contains("antifire")));

    final TaskStrategy ranged =
        SlayerTaskStrategyCatalog.resolve(
            "Skeletal wyverns",
            Preference.Cannon.NEVER,
            Preference.Burst.NEVER,
            Preference.CombatStyle.PREFER_RANGED,
            "Asgarnian Ice Dungeon",
            false);
    assertEquals(TaskStrategy.CombatStyle.RANGED, ranged.getStyle());
    assertTrue(ranged.getMethod().contains("dragonstone bolts"));
    assertEquals(
        "dragonfire ward",
        SlayerEquipmentAuditCatalog.priorities(
                "Skeletal wyverns", ranged, EquipmentInventorySlot.SHIELD, "Dragon hunter crossbow")
            .get(0));
    final MethodRules rangedRules =
        SlayerMethodRuleCatalog.resolve("Skeletal wyverns", "Asgarnian Ice Dungeon", ranged);
    assertEquals(2, rangedRules.resolveRestoreSlots(ranged));
    assertEquals(6, rangedRules.resolveFoodSlots(ranged, ranged.getFood()));
    assertTrue(rangedRules.includesStyleBoost());
    assertFalse(
        rangedRules.getRequiredItems().stream()
            .anyMatch(item -> item.getDisplayName().equals("Special attack weapon")));

    final TaskStrategy magic =
        SlayerTaskStrategyCatalog.resolve(
            "Skeletal wyverns",
            Preference.Cannon.NEVER,
            Preference.Burst.NEVER,
            Preference.CombatStyle.PREFER_MAGIC,
