                    item.isEquipmentSwitch()
                        && item.getSwitchStyle() == KitItem.SwitchStyle.RANGED));
    assertTrue(
        PreparationCatalog.resolve(
                "Barrows Brothers",
                "Barrows",
                strategy,
                null,
                null,
                null,
                Collections.emptyMap(),
                ItemID.SMOKE_BATTLESTAFF)
            .isActive());
