    assertEquals(1, count(items, ItemID.BLACK_DRAGONHIDE_BODY));
    assertEquals(0, count(items, ItemID.RUNE_ARROW));
    assertEquals(0, count(inventory(ItemID.TUMEKENS_SHADOW, pool), ItemID.BLACK_DRAGONHIDE_BODY));
