  @Test
  public void finisherQuantitiesUpdateWithoutRerankingEquipmentOrTravel() {
    KitItem travel =
        new KitItem("Slayer ring", ItemID.SLAYER_BAG_OF_SALT, 1, KitItem.Status.INVENTORY)
            .withInventoryGroup(MethodRules.InventoryGroup.TRAVEL);
    KitItem salt =
        new KitItem("Bag of salt", ItemID.SLAYER_BAG_OF_SALT, 25, KitItem.Status.BANK)
            .withInventoryGroup(MethodRules.InventoryGroup.UTILITY);
    KitItem fungicide =
        new KitItem("Fungicide", -1, 3, KitItem.Status.MISSING)
            .withInventoryGroup(MethodRules.InventoryGroup.UTILITY);
    KitPlan plan =
        new KitPlan(
            "owned",
            "task",
            Collections.emptyList(),
            Arrays.asList(travel, salt, fungicide),
            Collections.emptyList());
    assertSame(plan, plan.withRemainingFinishers(25));
    KitPlan updated = plan.withRemainingFinishers(20);
    assertSame(travel, updated.getInventoryItems().get(0));
    assertEquals(20, updated.getInventoryItems().get(1).getQuantity());
    assertEquals(2, updated.getInventoryItems().get(2).getQuantity());
    assertEquals(KitItem.Status.MISSING, updated.getInventoryItems().get(2).getStatus());
    assertEquals(
        MethodRules.InventoryGroup.UTILITY, updated.getInventoryItems().get(1).getInventoryGroup());
  }

  @Test
  public void repeatedSidebarUpdatesDoNotRebuildDropdownModels() throws Exception {
    SwingUtilities.invokeAndWait(
        () -> {
          SlayerPlusPanel panel = new SlayerPlusPanel();
          try {
            panel.configureOwnedSlayerHelmets(Collections.singletonList("Slayer helmet"));
            panel.configureTaskVariants("Gargoyles", TaskVariant.STANDARD_TASK);
            JComboBox<?> helmets = comboContaining(panel, "Slayer helmet");
            JComboBox<?> variants =
                comboContaining(
                    panel, VariantCatalog.getOptionLabel("Gargoyles", TaskVariant.STANDARD_TASK));
            assertNotNull(helmets);
            assertNotNull(variants);
            AtomicInteger events = new AtomicInteger();
            ListDataListener listener =
                new ListDataListener() {
                  public void intervalAdded(ListDataEvent event) {
                    events.incrementAndGet();
                  }

                  public void intervalRemoved(ListDataEvent event) {
                    events.incrementAndGet();
                  }

                  public void contentsChanged(ListDataEvent event) {
                    events.incrementAndGet();
                  }
                };
            helmets.getModel().addListDataListener(listener);
            variants.getModel().addListDataListener(listener);
            for (int i = 0; i < 50; i++) {
              panel.configureOwnedSlayerHelmets(Collections.singletonList("Slayer helmet"));
              panel.configureTaskVariants("Gargoyles", TaskVariant.STANDARD_TASK);
            }
            assertEquals(0, events.get());
            panel.configureOwnedSlayerHelmets(Arrays.asList("Slayer helmet", "Slayer helmet (i)"));
            assertTrue(events.get() > 0);
            assertEquals(4, helmets.getItemCount());
            panel.configureTaskVariants("Rockslugs", TaskVariant.STANDARD_TASK);
            assertEquals(
                VariantCatalog.getAvailableVariants("Rockslugs").size(), variants.getItemCount());
          } finally {
            panel.disposeResources();
          }
        });
  }

  private static JComboBox<?> comboContaining(Component component, String item) {
    if (component instanceof JComboBox) {
      JComboBox<?> combo = (JComboBox<?>) component;
      for (int i = 0; i < combo.getItemCount(); i++) {
        if (item.equals(combo.getItemAt(i))) {
          return combo;
        }
      }
    }
    if (component instanceof Container) {
      for (Component child : ((Container) component).getComponents()) {
        JComboBox<?> found = comboContaining(child, item);
        if (found != null) {
          return found;
        }
      }
    }
    return null;
  }
}

package com.slayerplus;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

public final class SlayerMethodRuleCoverage {
  private SlayerMethodRuleCoverage() {}

  public static boolean validateCurrentCatalog() {
    final List<String> failures = new ArrayList<>();
    final Set<String> validated = new LinkedHashSet<>();
    for (final String assignment : SlayerTaskStrategyCatalog.getCurrentTaskNames()) {
      if (!SlayerTaskStrategyCatalog.hasExplicitStrategy(assignment)) {
        failures.add(assignment + ": no individually reviewed strategy");
        continue;
      }
      for (final Preference.Cannon cannon : Preference.Cannon.values()) {
        for (final Preference.Burst burst : Preference.Burst.values()) {
          for (final Preference.CombatStyle combat : Preference.CombatStyle.values()) {
            validateSelection(assignment, cannon, burst, combat, validated, failures);
          }
        }
      }
    }
    if (!failures.isEmpty()) {
      throw new IllegalStateException("Incomplete Slayer method-rule coverage: " + failures);
    }
    return true;
  }

  private static void validateSelection(
      final String assignment,
      final Preference.Cannon cannon,
      final Preference.Burst burst,
      final Preference.CombatStyle combat,
      final Set<String> validated,
      final List<String> failures) {
    try {
      final TaskStrategy strategy =
          SlayerTaskStrategyCatalog.resolve(
              assignment, cannon, burst, combat, "Not restricted", false);
      if (strategy == null || !strategy.isReviewed()) {
        failures.add(assignment + ": preference resolved to an unreviewed method");
        return;
      }
      final MethodRules rules =
          SlayerMethodRuleCatalog.resolve(assignment, "Not restricted", strategy);
      if (SlayerMethodRuleCatalog.selectedMethodRequiresStandardSpellbook(strategy)
          && rules.getSpellbook() != MethodRules.Spellbook.STANDARD) {
        failures.add(
            assignment
                + ": explicit Standard-spell method did not resolve to the Standard spellbook");
        return;
      }
      if (rules.getSpellbook() != MethodRules.Spellbook.NONE
          && rules.getSpellbook() != MethodRules.Spellbook.STRATEGY_DEFINED
          && (rules.getPrimarySpell() == null || rules.getPrimarySpell().trim().isEmpty())) {
        failures.add(assignment + ": concrete spellbook method has no primary spell");
        return;
      }
      if (validated.add(rules.getCoverageKey())) {
        rules.validateFor(assignment, strategy);
      }
    } catch (RuntimeException ex) {
      failures.add(assignment + ": " + safeMessage(ex));
    }
  }

  private static String safeMessage(final RuntimeException ex) {
    return ex == null || ex.getMessage() == null ? "validation failed" : ex.getMessage();
  }
}

