  private static SlayerLoadoutAnalyzer.OwnedItem owned(
      int id, String name, EquipmentInventorySlot slot) {
    return new SlayerLoadoutAnalyzer.OwnedItem(
        id,
        name,
        100,
        KitItem.Status.BANK,
        slot == null ? -1 : slot.getSlotIdx(),
        null,
        Collections.emptySet());
