public class SlayerOptionalPinsTest {
  @Test
  public void menuNeedsSlayerTagOrShiftAndAlwaysNeedsBankItem() {
    int bank = InterfaceID.Bankmain.ITEMS;
    assertTrue(SlayerOptionalPins.allowsMenu("slayerplus current", bank, ItemID.SHARK, false));
    assertFalse(SlayerOptionalPins.allowsMenu("Other tag", bank, ItemID.SHARK, false));
    assertFalse(SlayerOptionalPins.allowsMenu(null, bank, ItemID.SHARK, false));
    assertTrue(SlayerOptionalPins.allowsMenu("Other tag", bank, ItemID.SHARK, true));
    assertTrue(SlayerOptionalPins.allowsMenu(null, bank, ItemID.SHARK, true));
    assertFalse(SlayerOptionalPins.allowsMenu(BankTagLayout.TAG_NAME, -1, ItemID.SHARK, true));
    assertFalse(SlayerOptionalPins.allowsMenu(BankTagLayout.TAG_NAME, bank, -1, true));
    assertFalse(
        SlayerOptionalPins.allowsMenu(
            BankTagLayout.TAG_NAME, InterfaceID.Bankmain.ITEMS_CONTAINER, ItemID.SHARK, false));
    assertFalse(
        SlayerOptionalPins.allowsMenu(
            null, InterfaceID.Bankmain.ITEMS_CONTAINER, ItemID.SHARK, true));
    assertFalse(
        SlayerOptionalPins.allowsMenu(
            BankTagLayout.TAG_NAME, InterfaceID.Bankmain.TABS, ItemID.SHARK, true));
  }

  @Test
  public void triggerAddsOneEntryAndDoesNotReenterForItsOwnOption() {
    assertTrue(SlayerOptionalPins.isMenuTrigger("Examine", true));
    assertTrue(SlayerOptionalPins.isMenuTrigger("Examine", false));
    assertFalse(SlayerOptionalPins.isMenuTrigger("Withdraw-All-but-1", true));
    assertTrue(SlayerOptionalPins.isMenuTrigger("Withdraw-All-but-1", false));
    for (String option :
        Arrays.asList(
            "Withdraw-1",
            "Withdraw-All",
            "Cancel",
            "Pin to SlayerPlus optional row",
            "Unpin from SlayerPlus optional row",
            null)) {
      assertFalse(SlayerOptionalPins.isMenuTrigger(option, false));
    }
  }

  @Test
  public void pinsRoundTripInOrderAndRejectInvalidIds() {
    Set<Integer> pins =
        SlayerOptionalPins.read(
            ItemID.SHARK + ",bad,-1,0," + ItemID.SHARK + "," + ItemID.BH_RUNE_POUCH);
    assertEquals(Arrays.asList(ItemID.SHARK, ItemID.BH_RUNE_POUCH), new ArrayList<>(pins));
    assertEquals(pins, SlayerOptionalPins.read(SlayerPlusPlugin.serializeItemIds(pins)));
    assertTrue(SlayerOptionalPins.read(null).isEmpty());
    assertEquals(8, SlayerOptionalPins.read("1,2,3,4,5,6,7,8,9").size());
  }

  @Test
  public void pinsLeadOptionalRowWithoutChangingRequiredLoadout() {
    KitItem shark = item(ItemID.SHARK);
    KitItem pouch = item(ItemID.BH_RUNE_POUCH);
    KitPlan original =
        new KitPlan(
            "owned",
            "task",
            Collections.singletonList(shark),
            Collections.singletonList(pouch),
            Arrays.asList(pouch, shark));
    KitPlan result = SlayerOptionalPins.prepend(original, Collections.singletonList(shark));
    assertEquals(Arrays.asList(shark, pouch), result.getOptionalItems());
    assertEquals(original.getEquipmentItems(), result.getEquipmentItems());
    assertEquals(original.getInventoryItems(), result.getInventoryItems());
    assertEquals(Arrays.asList(pouch, shark), original.getOptionalItems());
    assertSame(original, SlayerOptionalPins.prepend(original, Collections.emptyList()));
    assertNull(SlayerOptionalPins.prepend(null, Collections.singletonList(shark)));
  }

  @Test
  public void pinnedEquipmentKeepsBothOptionalAndEquipmentPositions() {
    Layout layout = new Layout(BankTagLayout.TAG_NAME);
    Set<Integer> tags = new LinkedHashSet<>();
    Set<Integer> pins = Collections.singleton(ItemID.SHARK);
    assertTrue(BankTagLayout.placeEquipmentItemId(layout, tags, ItemID.SHARK, 0, pins));
    assertTrue(BankTagLayout.placeEquipmentItemId(layout, tags, ItemID.SHARK, 17, pins));
    assertEquals(ItemID.SHARK, layout.getLayout()[0]);
    assertEquals(ItemID.SHARK, layout.getLayout()[17]);
    assertEquals(1, tags.size());
    assertFalse(
        BankTagLayout.placeEquipmentItemId(layout, tags, ItemID.SHARK, 18, Collections.emptySet()));
    assertFalse(BankTagLayout.placeEquipmentItemId(layout, tags, -1, 18, pins));
  }

  private static KitItem item(int id) {
    return new KitItem("Item", id, 1, KitItem.Status.BANK);
  }
}

package com.slayerplus;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Lightweight integrity checks for the reviewed task catalog. This can be called by unit tests or a
 * development-only startup assertion without depending on RuneLite APIs.
 */
public final class SlayerTaskStrategyValidator {
  private SlayerTaskStrategyValidator() {}

  public static List<String> validate() {
    final List<String> errors = new ArrayList<>();

    for (final TaskResearch.Entry entry : TaskResearch.getEntries()) {
      if (entry.getLocations().isEmpty()) {
        errors.add(entry.getTaskName() + ": no reviewed location");
        continue;
      }

      final TaskStrategy automatic =
          SlayerTaskStrategyCatalog.resolve(
              entry.getTaskName(),
              Preference.Cannon.ALLOW,
              Preference.Burst.ALLOW,
              Preference.CombatStyle.AUTOMATIC,
              entry.getLocations().get(0),
              false);

      validateConcreteStrategy(entry.getTaskName() + " automatic", automatic, errors);

      if (entry.isWildernessReviewed()) {
        final TaskStrategy wilderness =
            SlayerTaskStrategyCatalog.resolve(
                entry.getTaskName(),
                Preference.Cannon.ALLOW,
                Preference.Burst.NEVER,
                Preference.CombatStyle.AUTOMATIC,
                "Wilderness Slayer Cave",
                true);

        validateConcreteStrategy(entry.getTaskName() + " Wilderness", wilderness, errors);
        if (wilderness.getCostPolicy() != TaskStrategy.CostPolicy.LOW_RISK) {
          errors.add(entry.getTaskName() + ": reviewed Wilderness profile is not LOW_RISK");
        }
      }
    }

    validateAutomaticPreferenceOnlyGuardrail(errors);
    validateDisabledPreferenceGuardrails(errors);
    validateExpectedFallbacks(errors);
    validateTzKalZukProfiles(errors);
    return Collections.unmodifiableList(errors);
  }

  public static void validateOrThrow() {
    final List<String> errors = validate();
    if (!errors.isEmpty()) {
      throw new IllegalStateException("SlayerPlus strategy validation failed: " + errors);
    }
  }

  private static void validateConcreteStrategy(
      final String label, final TaskStrategy strategy, final List<String> errors) {
    if (strategy == null) {
      errors.add(label + ": null strategy");
      return;
    }
    if (!strategy.isReviewed()) {
      errors.add(label + ": strategy is not marked reviewed");
    }
    if (strategy.getWeaponPriorities().isEmpty()) {
      errors.add(label + ": no weapon priorities");
    }
    if (strategy.hasTag(TaskStrategy.MethodTag.BARRAGE) && !strategy.needsRunePouch()) {
      errors.add(label + ": burst/barrage profile lacks rune pouch");
    }
    if (strategy.isBoss() && !strategy.hasTag(TaskStrategy.MethodTag.BOSS)) {
      // Older unreviewed helpers may not carry structured tags, but every
      // reviewed boss profile should once bosses enter the research gate.
      errors.add(label + ": boss flag lacks BOSS method tag");
    }
    if ((strategy.getDamageProfile() == TaskStrategy.DamageProfile.ZERO_WHILE_PROTECTED
            || strategy.getDamageProfile() == TaskStrategy.DamageProfile.ZERO_WHILE_SAFESPOTTING)
        && strategy.getRecommendedFoodSlots(200) != 0) {
      errors.add(label + ": zero-damage profile still reserves food");
    }
  }

  private static void validateAutomaticPreferenceOnlyGuardrail(final List<String> errors) {
    /*
     * Global research invariant: a style that is authored only as a viable
     * player-preference alternative must never become Automatic just because
     * the NPC has an elemental/style weakness.  Automatic is reserved for the
     * researched practical/meta method.
     */
    for (final String assignment : SlayerTaskStrategyCatalog.getCurrentTaskNames()) {
      final TaskResearch.Entry research = TaskResearch.find(assignment);
      final String location =
          research == null || research.getLocations().isEmpty()
              ? "Not restricted"
              : research.getLocations().get(0);

      for (final Preference.Cannon cannon : Preference.Cannon.values()) {
        for (final Preference.Burst burst : Preference.Burst.values()) {
          final TaskStrategy automatic =
              SlayerTaskStrategyCatalog.resolve(
                  assignment, cannon, burst, Preference.CombatStyle.AUTOMATIC, location, false);

          if (automatic != null
              && automatic.hasTag(TaskStrategy.MethodTag.PREFERENCE_ONLY_ALTERNATIVE)) {
            errors.add(
                assignment
                    + ": Automatic selected a preference-only alternative for "
                    + cannon
                    + "/"
                    + burst);
          }
        }
      }
    }
  }

  private static void validateDisabledPreferenceGuardrails(final List<String> errors) {
    /*
     * Global preference invariant: NEVER means never. Location capability or
     * a Fast-XP default may not reintroduce a cannon/barrage method after the
     * player disabled it. This audits the full current catalog rather than a
     * handful of representative tasks.
     */
    for (final String assignment : SlayerTaskStrategyCatalog.getCurrentTaskNames()) {
      final TaskResearch.Entry research = TaskResearch.find(assignment);
      final String location =
          research == null || research.getLocations().isEmpty()
              ? "Not restricted"
              : research.getLocations().get(0);

      for (final Preference.Burst burst : Preference.Burst.values()) {
        for (final Preference.CombatStyle combat : Preference.CombatStyle.values()) {
          final TaskStrategy strategy =
              SlayerTaskStrategyCatalog.resolve(
                  assignment, Preference.Cannon.NEVER, burst, combat, location, false);
          if (strategy != null && strategy.hasTag(TaskStrategy.MethodTag.CANNON)) {
            errors.add(assignment + ": Cannon.NEVER leaked a cannon method");
          }
        }
      }

      for (final Preference.Cannon cannon : Preference.Cannon.values()) {
        for (final Preference.CombatStyle combat : Preference.CombatStyle.values()) {
          final TaskStrategy strategy =
              SlayerTaskStrategyCatalog.resolve(
                  assignment, cannon, Preference.Burst.NEVER, combat, location, false);
          if (strategy != null && strategy.hasTag(TaskStrategy.MethodTag.BARRAGE)) {
            errors.add(assignment + ": Burst.NEVER leaked a burst/barrage method");
          }
        }
      }
    }
  }

  private static void validateTzKalZukProfiles(final List<String> errors) {
    final TaskStrategy strategy = resolveZuk();
    validateZukStrategy("Automatic", strategy, errors);
    validateZukInventory("Automatic", strategy, 2, 7, 9, 2, 1, errors);
  }

  private static TaskStrategy resolveZuk() {
    return SlayerTaskStrategyCatalog.resolve(
        "TzKal-Zuk",
        Preference.Cannon.NEVER,
        Preference.Burst.ALLOW,
        Preference.CombatStyle.AUTOMATIC,
        "Inferno",
        false);
  }

  private static void validateZukStrategy(
      final String profile, final TaskStrategy strategy, final List<String> errors) {
    if (strategy == null) {
      errors.add("TzKal-Zuk " + profile + ": null strategy");
      return;
    }

    if (strategy.getStyle() != TaskStrategy.CombatStyle.RANGED) {
      errors.add("TzKal-Zuk " + profile + ": must remain Ranged");
    }

    if (!strategy.isBoss() || !strategy.needsRunePouch()) {
      errors.add("TzKal-Zuk " + profile + ": full-Inferno boss/rune-pouch requirements were lost");
    }

    final List<String> weapons = strategy.getWeaponPriorities();
    if (weapons.isEmpty()
        || !"twisted bow".equals(normalize(weapons.get(0)))
        || !containsNormalized(weapons, "bow of faerdhinen")
        || !containsNormalized(weapons, "zaryte crossbow")
        || !containsNormalized(weapons, "armadyl crossbow")
        || !containsNormalized(weapons, "dragon crossbow")
        || !containsNormalized(weapons, "rune crossbow")) {
      errors.add("TzKal-Zuk " + profile + ": reviewed main-weapon progression changed");
    }

    if (containsNormalized(weapons, "toxic blowpipe")
        || !containsNormalized(strategy.getOptionalItemPriorities(), "toxic blowpipe")) {
      errors.add(
          "TzKal-Zuk "
              + profile
              + ": Toxic blowpipe must be a secondary switch, not the main weapon");
    }
  }

  private static void validateZukInventory(
      final String profile,
      final TaskStrategy strategy,
      final int prayerRegen,
      final int saradominBrews,
      final int restores,
      final int bastions,
      final int staminas,
      final List<String> errors) {
    if (strategy == null) {
      return;
    }

    final MethodRules rules = SlayerMethodRuleCatalog.resolve("TzKal-Zuk", "Inferno", strategy);

    if (rules.getSpellbook() != MethodRules.Spellbook.ANCIENT
        || !normalize(rules.getPrimarySpell()).contains("blood barrage")
        || !normalize(rules.getPrimarySpell()).contains("ice barrage")
        || !rules.requiresRunePouch()
        || rules.getPouchRunes().size() != 4) {
      errors.add("TzKal-Zuk " + profile + ": Blood/Ice Barrage four-rune package is incomplete");
    }

    final java.util.Set<String> runeNames = new java.util.LinkedHashSet<>();
    for (final MethodRules.RuneRequirement rune : rules.getPouchRunes()) {
      runeNames.add(normalize(rune.getName()));
    }
    if (!runeNames.contains("soul")
        || !runeNames.contains("blood")
        || !runeNames.contains("death")
        || !runeNames.contains("water")
        || runeNames.contains("fire")) {
      errors.add(
          "TzKal-Zuk "
              + profile
              + ": Inferno rune pouch must be Soul/Blood/Death/Water, never Fire");
    }

    assertRequiredSlots(rules, profile, "Toxic blowpipe", 1, errors);
    assertRequiredSlots(rules, profile, "Ancient Magicks weapon", 1, errors);
    assertRequiredSlots(rules, profile, "Mage body switch", 1, errors);
    assertRequiredSlots(rules, profile, "Mage leg switch", 1, errors);
    assertRequiredSlots(rules, profile, "Magic off-hand switch", 1, errors);
    assertRequiredSlots(rules, profile, "Magic damage switch", 1, errors);
    assertRequiredSlots(rules, profile, "Prayer regeneration potion", prayerRegen, errors);
    assertRequiredSlots(rules, profile, "Saradomin brew", saradominBrews, errors);
    assertRequiredSlots(rules, profile, "Super restore", restores, errors);
    assertRequiredSlots(rules, profile, "Bastion potion", bastions, errors);
    assertRequiredSlots(rules, profile, PotionPolicy.EXTENDED_STAMINA_DISPLAY, staminas, errors);
    assertRequiredSlots(rules, profile, "Armadyl brew", 0, errors);

    int authoredInventorySlots = rules.requiresRunePouch() ? 1 : 0;
    for (final MethodRules.RequiredItem item : rules.getRequiredItems()) {
      authoredInventorySlots += item.getSlotCount();
    }
    if (authoredInventorySlots != 28) {
      errors.add(
          "TzKal-Zuk "
              + profile
              + ": final Inferno inventory must author exactly 28 slots, found "
              + authoredInventorySlots);
    }
  }

  private static void assertRequiredSlots(
      final MethodRules rules,
      final String profile,
      final String displayName,
      final int expected,
      final List<String> errors) {
    int actual = 0;
    for (final MethodRules.RequiredItem item : rules.getRequiredItems()) {
      if (normalize(item.getDisplayName()).equals(normalize(displayName))) {
        actual += item.getSlotCount();
      }
    }

    if (actual != expected) {
      errors.add(
          "TzKal-Zuk "
              + profile
              + ": "
              + displayName
              + " expected "
              + expected
              + " slots but found "
              + actual);
    }
  }

  private static boolean containsNormalized(final List<String> values, final String expected) {
    final String target = normalize(expected);
    for (final String value : values) {
      if (normalize(value).equals(target)) {
        return true;
      }
    }
    return false;
  }

  private static String normalize(final String value) {
    return value == null
        ? ""
        : value
            .toLowerCase(java.util.Locale.ENGLISH)
            .replace('\u2019', '\'')
            .replaceAll("[^a-z0-9]+", " ")
            .trim()
            .replaceFirst("^the\\s+", "");
  }

  private static void validateExpectedFallbacks(final List<String> errors) {
    final TaskStrategy dustNoBurst =
        SlayerTaskStrategyCatalog.resolve(
            "Dust devils",
            Preference.Cannon.ALLOW,
            Preference.Burst.NEVER,
            Preference.CombatStyle.AUTOMATIC,
            "Catacombs of Kourend",
            false);
    if (dustNoBurst.hasTag(TaskStrategy.MethodTag.BARRAGE)) {
      errors.add("Dust devils: Burst.NEVER returned a barrage profile");
    }

    final TaskStrategy krakenMeleePreference =
        SlayerTaskStrategyCatalog.resolve(
            "Cave kraken",
            Preference.Cannon.ALLOW,
            Preference.Burst.ALLOW,
            Preference.CombatStyle.PREFER_MELEE,
            "Kraken Cove",
            false);
    if (krakenMeleePreference.getStyle() != TaskStrategy.CombatStyle.MAGIC) {
      errors.add("Cave kraken: unsafe melee preference did not fall back to Magic");
    }

    final TaskStrategy abyssalTower =
        SlayerTaskStrategyCatalog.resolve(
            "Abyssal demons",
            Preference.Cannon.ALLOW,
            Preference.Burst.PREFER,
            Preference.CombatStyle.AUTOMATIC,
            "Slayer Tower",
            false);
    if (abyssalTower.hasTag(TaskStrategy.MethodTag.BARRAGE)) {
      errors.add("Abyssal demons: Slayer Tower returned a multi-target barrage profile");
    }

    final TaskStrategy kalphiteNoCannon =
        SlayerTaskStrategyCatalog.resolve(
            "Kalphites",
            Preference.Cannon.NEVER,
            Preference.Burst.ALLOW,
            Preference.CombatStyle.AUTOMATIC,
            "Kalphite Slayer Cave",
            false);
    if (kalphiteNoCannon.hasTag(TaskStrategy.MethodTag.CANNON)) {
      errors.add("Kalphites: Cannon.NEVER returned a cannon profile");
    }

    final TaskStrategy smokeNoCannon =
        SlayerTaskStrategyCatalog.resolve(
            "Smoke devils",
            Preference.Cannon.NEVER,
            Preference.Burst.ALLOW,
            Preference.CombatStyle.AUTOMATIC,
            "Smoke Devil Dungeon",
            false);
    if (smokeNoCannon.hasTag(TaskStrategy.MethodTag.CANNON)
        || !smokeNoCannon.hasTag(TaskStrategy.MethodTag.BARRAGE)) {
      errors.add(
          "Smoke devils: Cannon.NEVER did not preserve the reviewed no-cannon barrage fallback");
    }

    final TaskStrategy regularHellhound =
        SlayerTaskStrategyCatalog.resolve(
            "Hellhounds",
            Preference.Cannon.ALLOW,
            Preference.Burst.ALLOW,
            Preference.CombatStyle.AUTOMATIC,
            "Catacombs of Kourend",
            false);
    if (regularHellhound.getStyle() != TaskStrategy.CombatStyle.RANGED
        || !regularHellhound.hasTag(TaskStrategy.MethodTag.VENATOR)
        || regularHellhound.getWeaponPriorities().isEmpty()
        || !regularHellhound.getWeaponPriorities().get(0).equals("venator bow")
        || regularHellhound.getDamageProfile() != TaskStrategy.DamageProfile.ZERO_WHILE_PROTECTED
        || regularHellhound.getRecommendedFoodSlots(200) != 0) {
      errors.add(
          "Hellhounds: Catacombs Automatic must use the reviewed Venator multi-target profile with"
              + " zero food while protected");
    }

    final TaskStrategy cannonHellhound =
        SlayerTaskStrategyCatalog.resolve(
            "Hellhounds",
            Preference.Cannon.ALLOW,
            Preference.Burst.ALLOW,
            Preference.CombatStyle.AUTOMATIC,
