    if (cerberusAutomatic.getStyle() != TaskStrategy.CombatStyle.MELEE
        || cerberusAutomatic.hasTag(TaskStrategy.MethodTag.PREFERENCE_ONLY_ALTERNATIVE)) {
      errors.add(
          "Cerberus: Automatic must remain the researched melee meta; Water Magic is"
              + " preference-only");
    }

    final TaskStrategy gryphonAutomatic =
        SlayerTaskStrategyCatalog.resolve(
            "Gryphons",
            Preference.Cannon.ALLOW,
            Preference.Burst.ALLOW,
            Preference.CombatStyle.AUTOMATIC,
