            Preference.Burst.ALLOW,
            Preference.CombatStyle.PREFER_MAGIC,
            "Great Conch",
            false);
    if (gryphonAutomatic.getStyle() != TaskStrategy.CombatStyle.MELEE
        || gryphonMagicPreference.getStyle() != TaskStrategy.CombatStyle.MAGIC
        || !gryphonMagicPreference.hasTag(TaskStrategy.MethodTag.PREFERENCE_ONLY_ALTERNATIVE)) {
