package com.slayerplus;

import net.runelite.client.config.*;

@ConfigGroup(SlayerPlusConfig.GROUP)
public interface SlayerPlusConfig extends Config {
  String GROUP = "slayerplus";

  @ConfigSection(
      name = "Slayer workflow",
      description = "Controls normal Slayer sessions or guided Turael point boosting.",
      position = 0)
  String WORKFLOW_SECTION = "workflow";

  @ConfigSection(
      name = "Recommendation preferences",
      description = "Controls how SlayerPlus ranks valid task locations.",
      position = 1)
  String RECOMMENDATION_SECTION = "recommendation";

  @ConfigSection(
      name = "Loadout scanning",
      description = "Controls equipment, inventory, and bank recommendations.",
      position = 2)
  String LOADOUT_SECTION = "loadout";

  @ConfigItem(
      keyName = "slayerWorkflow",
      name = "Slayer workflow",
      description =
          "Normal Slayer follows the assigning master. Turael point boosting uses nine Turael or"
              + " Aya tasks followed by each tenth task from the selected bonus master.",
      position = 0,
      section = WORKFLOW_SECTION)
  default Preference.Workflow slayerWorkflow() {
    return Preference.Workflow.NORMAL;
  }

  @ConfigItem(
      keyName = "pointBoostBonusMaster",
      name = "Bonus-task master",
      description = "The Slayer master used for every tenth point-boosting task.",
      position = 1,
      section = WORKFLOW_SECTION)
  default Preference.BonusMaster pointBoostBonusMaster() {
    return Preference.BonusMaster.KONAR;
  }

  @ConfigItem(
      keyName = "combatStylePreference",
      name = "Combat style",
      description =
          "Automatic uses the best individually researched method. A preferred style is used only"
              + " when the task has a verified viable setup for it.",
      position = 0,
      section = RECOMMENDATION_SECTION)
  default Preference.CombatStyle combatStylePreference() {
    return Preference.CombatStyle.AUTOMATIC;
  }

  @ConfigItem(
      keyName = "cannonPreference",
      name = "Cannon",
      description = "Prefer, allow, or avoid cannon locations.",
      position = 1,
      section = RECOMMENDATION_SECTION)
  default Preference.Cannon cannonPreference() {
    return Preference.Cannon.ALLOW;
  }

  @ConfigItem(
      keyName = "burstPreference",
      name = "Burst / barrage",
      description = "Prefer, allow, or avoid burst and barrage methods.",
      position = 2,
      section = RECOMMENDATION_SECTION)
  default Preference.Burst burstPreference() {
    return Preference.Burst.ALLOW;
  }

  @ConfigItem(
      keyName = "shardPreference",
      name = "Shard preference",
      description =
          "Prefer valid task locations that drop ancient shards, crystal shards, both, or neither."
              + " Assigned-area and Wilderness restrictions always take priority.",
      position = 3,
      section = RECOMMENDATION_SECTION)
  default Preference.Shard shardPreference() {
    return Preference.Shard.NO_PREFERENCE;
  }

  @ConfigItem(
      keyName = "showLoadoutRecommendations",
      name = "Show loadout recommendations",
      description = "Scan worn, inventory, and cached bank items for the current task.",
      position = 0,
      section = LOADOUT_SECTION)
  default boolean showLoadoutRecommendations() {
    return true;
  }
}

package com.slayerplus;

import static com.slayerplus.SlayerText.matchesAny;

import java.io.*;
import java.util.*;
import net.runelite.api.*;

public final class SlayerRecommendationEngine {
  private static final int KRYSTILIA = 7;
  private static final int KONAR_MASTER_ID = 8;
  private static final Map<String, List<LocationOption>> TASK_LOCATIONS = createTaskLocations();
  private final Client client;
  private final SlayerPlusConfig config;
  private final Map<String, List<LocationOption>> taskLocations;

  public SlayerRecommendationEngine(Client client, SlayerPlusConfig config) {
    this.client = client;
    this.config = config;
    this.taskLocations = TASK_LOCATIONS;
  }

  static Set<String> catalogLocationsForValidation(String assignment) {
    List<LocationOption> options = TASK_LOCATIONS.get(normalize(assignment));
    if (options == null || options.isEmpty()) {
      return Collections.emptySet();
    }
    Set<String> locations = new LinkedHashSet<>();
    for (LocationOption option : options) {
      if (option != null && option.location != null && !option.location.trim().isEmpty()) {
        locations.add(option.location.trim());
      }
    }
    return Collections.unmodifiableSet(locations);
  }

  public Recommendation recommend(String assignment, int masterId, String assignedLocation) {
    String normalizedTask = normalize(assignment);
    if (normalizedTask.isEmpty()) {
      return genericRecommendation("Unknown task", masterId);
    }
    if (masterId == KONAR_MASTER_ID || isAssignedArea(assignedLocation)) {
      return assignedAreaRecommendation(normalizedTask, assignedLocation, masterId);
    }
    if (masterId == KRYSTILIA) {
      return wildernessRecommendation(assignment);
    }
    if (masterId == BoostCoordinator.TURAEL_AYA_MASTER_ID
        && config != null
        && config.slayerWorkflow() == Preference.Workflow.TURAEL_POINT_BOOST) {
      Recommendation boost = turaelBoostRecommendation(assignment);
      if (boost != null) {
        return boost;
      }
    }
    List<LocationOption> options = taskLocations.get(normalizedTask);
    if (options == null || options.isEmpty()) {
      return genericRecommendation(assignment, masterId);
    }
    LocationOption selected = null;
    int selectedScore = Integer.MIN_VALUE;
    LocationOption lockedUpgrade = null;
    int lockedScore = Integer.MIN_VALUE;
    for (LocationOption option : options) {
      if (option.wilderness) {
        continue;
      }
      int score = scoreOption(option, normalizedTask, masterId);
      if (isUnlocked(option)) {
        if (selected == null || score > selectedScore) {
          selected = option;
          selectedScore = score;
        }
      } else if (lockedUpgrade == null || score > lockedScore) {
        lockedUpgrade = option;
        lockedScore = score;
      }
    }
    if (selected == null) {
      return lockedRecommendation(assignment, lockedUpgrade);
    }
    TaskStrategy strategy = strategyFor(normalizedTask, selected.location, false);
    return new Recommendation(
        selected.location,
        strategy.getMethod(),
        selected.travel,
        formatCannon(selected.cannonSupport),
        formatRequirements(selected, lockedUpgrade),
        "Non-Wilderness recommendation",
        strategy);
  }

  private Recommendation turaelBoostRecommendation(String assignment) {
    TuraelBoost.Entry entry = TuraelBoost.find(assignment);
    if (entry == null) {
      return null;
    }
    TaskStrategy strategy =
        strategyFor(assignment, entry.getLocation(), false)
            .withAdditionalTags(TaskStrategy.MethodTag.TURAEL_POINT_BOOST);
    return new Recommendation(
        entry.getLocation(),
        strategy.getMethod(),
        entry.getTravel(),
        entry.getCannon(),
        entry.getRequirements(),
        "Turael/Aya point-boost route",
        strategy);
  }

  private Recommendation assignedAreaRecommendation(
      String normalizedTask, String assignedLocation, int masterId) {
    String area =
        isAssignedArea(assignedLocation) ? assignedLocation.trim() : "Assigned Slayer area";
    if (masterId != KRYSTILIA && isWilderness(area)) {
      return new Recommendation(
          "No non-Wilderness match",
          "Check the assignment with your Slayer master",
          "Do not route into the Wilderness",
          "Not recommended",
          "Assigned-area data needs verification",
          "Wilderness blocked unless Krystilia assigned it");
    }
    TaskStrategy strategy = strategyFor(normalizedTask, area, masterId == KRYSTILIA);
    return new Recommendation(
        area,
        strategy.getMethod(),
        travelForArea(area),
        formatCannon(cannonForArea(area)),
        "Use the monster inside the assigned area",
        masterId == KONAR_MASTER_ID ? "Konar — assigned area required" : "Assigned area required",
        strategy);
  }

  private Recommendation wildernessRecommendation(String assignment) {
    String normalized = normalize(assignment);
    String location;
    if (SlayerLoadoutData.list("wilderness_slayer_cave_tasks").contains(normalized)) {
      location = "Wilderness Slayer Cave";
    } else if (normalized.equals("bloodveld") || normalized.equals("bloodvelds")) {
      location = "Wilderness God Wars Dungeon";
    } else {
      location = "Nearest matching Wilderness spawn";
    }
    TaskStrategy strategy = strategyFor(assignment, location, true);
    return new Recommendation(
        location,
        strategy.getMethod(),
        "Start from Ferox Enclave and use the safest route",
        formatCannon(CannonSupport.OPTIONAL),
        "Krystilia assignment active",
        "Wilderness — protect-item planning required",
        strategy);
  }

  private Recommendation genericRecommendation(String assignment, int masterId) {
    TaskStrategy strategy =
        strategyFor(assignment, "Standard Slayer location", masterId == KRYSTILIA);
    return new Recommendation(
        "Standard Slayer location",
        strategy.getMethod(),
        "Use the nearest unlocked standard task location",
        "Check location rules",
        "Task-specific equipment profile active",
        masterId == KRYSTILIA ? "Krystilia Wilderness task" : "Wilderness locations excluded",
        strategy);
  }

  private Recommendation lockedRecommendation(String assignment, LocationOption lockedOption) {
    if (lockedOption == null) {
      return genericRecommendation(assignment, 0);
    }
    TaskStrategy strategy = strategyFor(assignment, lockedOption.location, false);
    return new Recommendation(
        "Location locked",
        strategy.getMethod(),
        lockedOption.travel,
        formatCannon(lockedOption.cannonSupport),
        requirementName(lockedOption) + " required",
        "Wilderness locations excluded",
        strategy);
  }

  private boolean isUnlocked(LocationOption option) {
    return (option.quest == null || option.quest.getState(client) == QuestState.FINISHED)
        && (option.skill == null || client.getRealSkillLevel(option.skill) >= option.skillLevel);
  }

  private String formatRequirements(LocationOption selected, LocationOption lockedUpgrade) {
    String selectedRequirement;
    if (selected.skill != null) {
      selectedRequirement = selected.skillLevel + " " + selected.skill.getName() + " — met";
    } else {
      selectedRequirement = selected.quest == null ? "None" : selected.questName + " — completed";
    }
    if (lockedUpgrade == null || lockedUpgrade == selected) {
      return selectedRequirement;
    }
    return selectedRequirement
        + "; "
        + requirementName(lockedUpgrade)
        + " unlocks "
        + lockedUpgrade.location;
  }

  private static String requirementName(LocationOption option) {
    if (option == null) {
      return "Location requirement";
    }
    if (option.skill != null) {
      return option.skillLevel + " " + option.skill.getName();
    }
    return option.questName == null || option.questName.trim().isEmpty()
        ? "Location requirement"
        : option.questName;
  }

  private int scoreOption(LocationOption option, String normalizedTask, int masterId) {
    int speed = speedRating(option);
    int score = speedRating(option) * 5;
    boolean cannonAvailable =
        option.cannonSupport == CannonSupport.RECOMMENDED
            || option.cannonSupport == CannonSupport.OPTIONAL;
    boolean cannonUnlocked = Quest.DWARF_CANNON.getState(client) == QuestState.FINISHED;
    switch (cannonPreference()) {
      case PREFER:
        if (cannonAvailable && cannonUnlocked) {
          score += option.cannonSupport == CannonSupport.RECOMMENDED ? 70 : 38;
        } else {
          score -= 18;
        }
        break;
      case NEVER:
        if (option.cannonSupport == CannonSupport.RECOMMENDED) {
          score -= 130;
        } else if (option.cannonSupport == CannonSupport.OPTIONAL) {
          score += 6;
        } else {
          score += 18;
        }
        break;
      case ALLOW:
      default:
        if (cannonAvailable && cannonUnlocked) {
          score += 12;
        }
        break;
    }
    boolean burstAvailable = supportsBurst(option);
    switch (burstPreference()) {
      case PREFER:
        score += burstAvailable ? 72 : -16;
        break;
      case NEVER:
        score += burstAvailable ? -130 : 18;
        break;
      case ALLOW:
      default:
        if (burstAvailable) {
          score += 12;
        }
        break;
    }
    score += travelScore(option.travel);
    score += shardPreferenceBonusForTest(shardPreference(), normalizedTask, option.location);
    return score;
  }

  private int speedRating(LocationOption option) {
    String text = normalize(option.location + " " + option.method);
    int rating = 42;
    if (text.contains("burst") || text.contains("barrage")) {
      rating += 42;
    }
    if (text.contains("cannon")) {
      rating += 32;
    }
    if (text.contains("multi combat") || text.contains("clustered") || text.contains("stacked")) {
      rating += 14;
    }
    if (text.contains("single combat")) {
      rating -= 14;
    }
    return clampRating(rating);
  }

  private int travelScore(String route) {
    String normalized = normalize(route);
    boolean directTeleport =
        matchesAny(normalized, SlayerLoadoutData.list("direct_teleport_fragments"));
    return directTeleport ? 45 : 8;
  }

  private static boolean supportsBurst(LocationOption option) {
    String method = normalize(option.method);
    return method.contains("burst") || method.contains("barrage");
  }

  private static int clampRating(int value) {
    return Math.max(0, Math.min(100, value));
  }

  private Preference.CombatStyle combatStylePreference() {
    return config == null || config.combatStylePreference() == null
        ? Preference.CombatStyle.AUTOMATIC
        : config.combatStylePreference();
  }

  private Preference.Cannon cannonPreference() {
    return config == null || config.cannonPreference() == null
        ? Preference.Cannon.ALLOW
        : config.cannonPreference();
  }

  private Preference.Burst burstPreference() {
    return config == null || config.burstPreference() == null
        ? Preference.Burst.ALLOW
        : config.burstPreference();
  }

  private Preference.Shard shardPreference() {
    return config == null || config.shardPreference() == null
        ? Preference.Shard.NO_PREFERENCE
        : config.shardPreference();
  }

  static int shardPreferenceBonusForTest(
      Preference.Shard preference, String assignment, String location) {
    if (preference == null || preference == Preference.Shard.NO_PREFERENCE) {
      return 0;
    }
    String task = normalize(assignment);
    String area = normalize(location);
    boolean ancientShardArea =
        !task.equals("ghost")
            && !task.equals("ghosts")
            && (area.contains("catacombs of kourend") || area.contains("giants den"));
    boolean crystalShardArea = area.contains("iorwerth dungeon");
    switch (preference) {
      case ANCIENT_SHARD:
        return ancientShardArea ? 1000 : 0;
      case CRYSTAL_SHARD:
        return crystalShardArea ? 1000 : 0;
      case ANCIENT_AND_CRYSTAL_SHARD:
        return ancientShardArea || crystalShardArea ? 1000 : 0;
      case NO_PREFERENCE:
      default:
        return 0;
    }
  }

  private String formatCannon(CannonSupport support) {
    if (support == CannonSupport.NOT_ALLOWED) {
      return "Not allowed";
    }
    if (support == CannonSupport.UNKNOWN) {
      return cannonPreference() == Preference.Cannon.NEVER
          ? "Disabled by preference"
          : "Check assigned-area rules";
    }
    if (cannonPreference() == Preference.Cannon.NEVER) {
      return "Disabled by preference";
    }
    if (Quest.DWARF_CANNON.getState(client) != QuestState.FINISHED) {
      return "Locked — complete Dwarf Cannon";
    }
    if (cannonPreference() == Preference.Cannon.PREFER) {
      return support == CannonSupport.RECOMMENDED
          ? "Preferred and recommended"
          : "Preferred where practical";
    }
    return support == CannonSupport.RECOMMENDED ? "Recommended" : "Optional";
  }

  private TaskStrategy strategyFor(String assignment, String location, boolean wilderness) {
    return SlayerTaskStrategyCatalog.resolve(
        assignment,
        cannonPreference(),
        burstPreference(),
        combatStylePreference(),
        location,
        wilderness);
  }

  private static String travelForArea(String area) {
    String normalized = normalize(area);
    if (normalized.contains("catacombs of kourend")) {
      return "Xeric's talisman to Xeric's Heart";
    }
    if (normalized.contains("slayer tower")) {
      return "Slayer ring to Slayer Tower";
    }
    if (normalized.contains("fremennik slayer dungeon")) {
      return "Slayer ring to Fremennik Slayer Dungeon";
    }
    if (normalized.contains("stronghold slayer cave")) {
      return "Slayer ring to Stronghold Slayer Cave";
    }
    if (normalized.contains("karuulm")) {
      return "Rada's blessing to Mount Karuulm";
    }
    if (normalized.contains("lighthouse")) {
      return "Games necklace to Barbarian Outpost, then run north";
    }
    if (normalized.contains("lunar isle")) {
      return "Lunar Isle teleport";
    }
    if (normalized.contains("meiyerditch")) {
      return "Drakan's medallion to Darkmeyer, then enter the laboratories";
    }
    if (normalized.contains("mos le harmless")) {
      return "Trouble Brewing minigame teleport, then run east";
    }
    if (normalized.contains("wilderness god wars")) {
      return "Cemetery teleport or Wilderness obelisk, then enter the Wilderness God Wars Dungeon";
    }
    if (normalized.contains("god wars")) {
      return "Trollheim teleport, then enter God Wars Dungeon";
    }
    if (normalized.contains("brimhaven dungeon")) {
      return "House teleport to Brimhaven, then run south";
    }
    if (normalized.contains("taverley dungeon")) {
      return "Falador teleport, then run northwest";
    }
    return "Use the nearest unlocked teleport to the assigned area";
  }

  private static CannonSupport cannonForArea(String area) {
    String normalized = normalize(area);
    if (matchesAny(normalized, SlayerLoadoutData.list("cannon_restricted_locations"))) {
      return CannonSupport.NOT_ALLOWED;
    }
    if (normalized.contains("lighthouse")
        || normalized.contains("meiyerditch")
        || normalized.contains("stronghold slayer cave")
        || normalized.contains("iorwerth dungeon")
        || normalized.contains("lunar isle")
        || normalized.contains("kalphite slayer cave")
        || normalized.contains("death plateau")
        || normalized.contains("smoke devil dungeon")) {
      return CannonSupport.RECOMMENDED;
    }
    return CannonSupport.UNKNOWN;
  }

  private static boolean isAssignedArea(String area) {
    if (area == null) {
      return false;
    }
    String normalized = normalize(area);
    return !normalized.isEmpty()
        && !normalized.equals("not restricted")
        && !normalized.equals("assigned area")
        && !normalized.equals("unknown")
        && !normalized.equals("-");
  }

  private static boolean isWilderness(String value) {
    String normalized = normalize(value);
    return normalized.contains("wilderness")
        || normalized.contains("revenant caves")
        || normalized.contains("forinthry");
  }

  private static Map<String, List<LocationOption>> createTaskLocations() {
    Map<String, List<LocationOption>> groups = new LinkedHashMap<>();
    for (String[] fields :
        ResourceTable.rowsWithEscapedDelimiters("slayer-task-locations.tsv", 9)) {
      if (!fields[0].equals("O")) {
        throw new IllegalStateException("Invalid task-location row type: " + fields[0]);
      }
      String aliasKey = fields[1];
      String requirementType = fields[6];
      Quest quest = requirementType.equals("QUEST") ? Quest.valueOf(fields[7]) : null;
      Skill skill = requirementType.equals("SKILL") ? Skill.valueOf(fields[7]) : null;
      int skillLevel = skill == null || fields[8].isEmpty() ? 0 : Integer.parseInt(fields[8]);
      groups
          .computeIfAbsent(aliasKey, unused -> new ArrayList<>())
          .add(
              new LocationOption(
                  fields[2],
                  fields[3],
                  fields[4],
                  CannonSupport.valueOf(fields[5]),
                  quest,
                  quest == null ? "" : fields[8],
                  skill,
                  skillLevel,
                  false));
    }
    Map<String, List<LocationOption>> result = new HashMap<>();
    for (Map.Entry<String, List<LocationOption>> group : groups.entrySet()) {
      List<LocationOption> options =
          Collections.unmodifiableList(new ArrayList<>(group.getValue()));
      for (String alias : group.getKey().split("\\|", -1)) {
        if (result.put(normalize(alias), options) != null) {
          throw new IllegalStateException("Duplicate task-location alias " + alias);
        }
      }
    }
    if (result.isEmpty()) {
      throw new IllegalStateException("Task-location resource is empty");
    }
    return Collections.unmodifiableMap(result);
  }

  private static String normalize(String value) {
    return SlayerText.normalize(value);
  }

  private enum CannonSupport {
    RECOMMENDED,
    OPTIONAL,
    NOT_ALLOWED,
    UNKNOWN
  }

  private static final class LocationOption {
    private final String location;
    private final String method;
    private final String travel;
    private final CannonSupport cannonSupport;
    private final Quest quest;
    private final String questName;
    private final Skill skill;
    private final int skillLevel;
    private final boolean wilderness;

    private LocationOption(
        String location,
        String method,
        String travel,
        CannonSupport cannonSupport,
        Quest quest,
        String questName,
        Skill skill,
        int skillLevel,
        boolean wilderness) {
      this.location = location;
      this.method = method;
      this.travel = travel;
      this.cannonSupport = cannonSupport;
      this.quest = quest;
      this.questName = questName;
      this.skill = skill;
      this.skillLevel = Math.max(0, skillLevel);
      this.wilderness = wilderness;
    }
  }
}

package com.slayerplus;

import static com.slayerplus.SlayerText.matchesAny;

import java.util.*;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.banktags.*;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.util.Text;

@RequiredArgsConstructor
public final class BankTagLayout {
  public static final String TAG_NAME = "SlayerPlus Current";
  private static final int BANK_COLUMNS = 8;
  private static final int OPTIONAL_LIMIT = 8;
  private static final int INVENTORY_LIMIT = 28;
  private static final int RUNE_POUCH_INVENTORY_SLOT = 27;
  private static final int TRAVEL_SLOT_WITH_RUNE_POUCH = 26;
  private static final int TRAVEL_SLOT_WITHOUT_RUNE_POUCH = 27;
  private static final int PREPARATION_REFERENCE_START_ROW = 8;
  private static final int PREPARATION_REFERENCE_START_COLUMN = 0;
  private static final int PREPARATION_REFERENCE_COLUMNS = 4;
  private static final int LIGHTBEARER_SWAP_POSITION = position(7, 2);
  private static final int EXTRA_QUIVER_AMMO_POSITION = position(2, 2);
  private static final int[] EQUIPMENT_POSITIONS = {
    position(2, 1),
    position(3, 0),
    position(3, 1),
    position(3, 2),
    position(4, 0),
    position(4, 1),
    position(4, 2),
    position(5, 1),
    position(6, 0),
    position(6, 1),
    position(6, 2),
    EXTRA_QUIVER_AMMO_POSITION
  };
  private final Client client;
  private final TagManager tagManager;
  private final LayoutManager layoutManager;
  private final BankTagsService bankTagsService;
  private final ConfigManager configs;
  private int[] lastSavedLayout = new int[0];
  private Set<Integer> lastSavedTaggedItemIds = Collections.emptySet();

  public Result createOrUpdate(
      KitPlan plan,
      List<Integer> preparationItemIds,
      boolean analyzerSourceZeroIsTravel,
      int extraQuiverAmmoItemId,
      Set<Integer> pinnedIds) {
    if (plan == null || !plan.hasConcreteItems()) {
      return Result.failure(
          "No concrete recommended items are available yet. Open your bank once, then refresh the"
              + " task.");
    }
    Layout layout = new Layout(TAG_NAME);
    Set<Integer> tags = new LinkedHashSet<>();
    int layoutSlots = 0;
    int optionalIndex = 0;
    List<KitItem> equipment = plan.getEquipmentItems();
    int braceletAlternative =
        equipment.size() > 8 ? braceletAlternativeId(equipment.get(8).getItemId()) : -1;
    for (KitItem item : plan.getOptionalItems()) {
      if (optionalIndex >= OPTIONAL_LIMIT) {
        break;
      }
      if (!showOptionalItem(item, equipment, braceletAlternative, pinnedIds)) {
        continue;
      }
      if (place(layout, tags, item, optionalIndex)) {
        layoutSlots++;
        optionalIndex++;
      }
    }
    int resolvedDizanaVariantId = resolveOwnedDizanaVariantId(plan);
    int recommendedExtraQuiverAmmoItemId =
        equipment.size() > 11 && concrete(equipment.get(11)) ? equipment.get(11).getItemId() : -1;
    if (normalizeName(plan.getLayoutTitle()).contains("tzkal zuk")) {
      recommendedExtraQuiverAmmoItemId =
          QuiverAmmo.preferBetterInfernoArrow(
              recommendedExtraQuiverAmmoItemId, extraQuiverAmmoItemId);
    }
    boolean hasUsableDizanaForLayout =
        resolvedDizanaVariantId > 0 || planContainsUsableDizanaCape(plan);
    for (int index = 0; index < equipment.size() && index < EQUIPMENT_POSITIONS.length; index++) {
      if (index == 1 && resolvedDizanaVariantId > 0) {
        if (placeEquipmentItemId(
            layout, tags, resolvedDizanaVariantId, EQUIPMENT_POSITIONS[index], pinnedIds)) {
          layoutSlots++;
        }
        continue;
      }
      if (index == 11) {
        if (hasUsableDizanaForLayout
            && recommendedExtraQuiverAmmoItemId > 0
            && placeInventoryItemId(
                layout, tags, recommendedExtraQuiverAmmoItemId, EQUIPMENT_POSITIONS[index])) {
          layoutSlots++;
        }
        continue;
      }
      if (placeEquipmentItemId(
          layout, tags, equipment.get(index).getItemId(), EQUIPMENT_POSITIONS[index], pinnedIds)) {
        layoutSlots++;
      }
    }
    if (equipment.size() > 8
        && placeBraceletAlternative(layout, tags, equipment.get(8).getItemId(), pinnedIds)) {
      layoutSlots++;
    }
    KitItem lightbearer = findLightbearer(plan);
    if (place(layout, tags, lightbearer, LIGHTBEARER_SWAP_POSITION)) {
      layoutSlots++;
    }
    List<KitItem> inventoryItems = plan.getInventoryItems();
    List<Candidate> inventoryCandidates = new ArrayList<>();
    for (int sourceIndex = 0; sourceIndex < inventoryItems.size(); sourceIndex++) {
      KitItem item = inventoryItems.get(sourceIndex);
      if (!concrete(item) || isLightbearer(item) || duplicatesConcreteEquipment(item, equipment)) {
        continue;
      }
      inventoryCandidates.add(new Candidate(item, sourceIndex));
    }
    for (InventoryPlacement placement :
        planInventoryCandidates(
            inventoryCandidates,
            -1,
            analyzerSourceZeroIsTravel,
            normalizeName(plan.getLayoutTitle()).contains("tormented demons"))) {
      int slotIndex = placement.getSlotIndex();
      int row = 2 + slotIndex / 4;
      int column = 4 + slotIndex % 4;
      if (placeInventory(layout, tags, placement.getItem(), position(row, column))) {
        layoutSlots++;
      }
    }
    int preparationIndex = 0;
    Set<Integer> preparationReferenceIds = new LinkedHashSet<>();
    if (preparationItemIds != null) {
      for (int preparationItemId : preparationItemIds) {
        if (preparationIndex >= OPTIONAL_LIMIT) {
          break;
        }
        int referenceId = preparationItemId;
        if (referenceId <= 0
            || (planContainsItemId(plan, referenceId) && !isRuneReferenceId(referenceId))
            || !preparationReferenceIds.add(referenceId)) {
          continue;
        }
        int row =
            PREPARATION_REFERENCE_START_ROW + preparationIndex / PREPARATION_REFERENCE_COLUMNS;
        int column =
            PREPARATION_REFERENCE_START_COLUMN + preparationIndex % PREPARATION_REFERENCE_COLUMNS;
        if (placeInventoryItemId(layout, tags, preparationItemId, position(row, column))) {
          layoutSlots++;
          preparationIndex++;
        }
      }
    }
    if (tags.isEmpty()) {
      return Result.failure(
          "The recommendation contains only unresolved item names. Open your bank once so"
              + " SlayerPlus can select exact item IDs.");
    }
    tagManager.removeTag(TAG_NAME);
    for (int itemId : tags) {
      tagManager.addTag(itemId, TAG_NAME, false);
    }
    layoutManager.saveLayout(layout);
    lastSavedLayout = Arrays.copyOf(layout.getLayout(), layout.getLayout().length);
    lastSavedTaggedItemIds = new LinkedHashSet<>(tags);
    int iconItemId = chooseIcon(plan, tags);
    ensurePersistentTagTab(iconItemId);
    boolean bankOpen = client != null && client.getItemContainer(InventoryID.BANK) != null;
    if (bankOpen) {
      bankTagsService.openBankTag(
          TAG_NAME,
          BankTagsService.OPTION_ALLOW_MODIFICATIONS
              | BankTagsService.OPTION_ITEMS_NOT_IN_LAYOUT_AT_BOTTOM);
    }
    int unresolved = plan.getUnresolvedItemCount();
    String omitted =
        unresolved > 0
            ? " "
                + unresolved
                + " unresolved recommendation"
                + (unresolved == 1 ? " was" : "s were")
                + " omitted."
            : "";
    return Result.success(
        bankOpen
            ? "Opened the real SlayerPlus Current bank-tag layout with "
                + layoutSlots
                + " arranged slots."
                + omitted
            : "Created the SlayerPlus Current bank-tag layout with "
                + layoutSlots
                + " arranged slots. Open the bank to view it."
                + omitted);
  }

  public boolean reopenLastSavedLayoutIfUnchanged() {
    if (lastSavedLayout.length == 0 || lastSavedTaggedItemIds.isEmpty()) {
      return false;
    }
    Layout persistedLayout = layoutManager.loadLayout(TAG_NAME);
    List<Integer> persistedItems = tagManager.getItemsForTag(TAG_NAME);
    if (persistedLayout == null
        || !samePersistedStateForTest(
            lastSavedLayout,
            persistedLayout.getLayout(),
            lastSavedTaggedItemIds,
            persistedItems == null
                ? Collections.emptySet()
                : new LinkedHashSet<>(persistedItems))) {
      return false;
    }
    if (client != null && client.getItemContainer(InventoryID.BANK) != null) {
      bankTagsService.openBankTag(
          TAG_NAME,
          BankTagsService.OPTION_ALLOW_MODIFICATIONS
              | BankTagsService.OPTION_ITEMS_NOT_IN_LAYOUT_AT_BOTTOM);
    }
    return true;
  }

  public void closeIfActive() {
    if (bankTagsService != null && TAG_NAME.equals(bankTagsService.getActiveTag())) {
      bankTagsService.closeBankTag();
    }
  }

  static boolean samePersistedStateForTest(
      int[] expectedLayout,
      int[] actualLayout,
      Set<Integer> expectedItems,
      Set<Integer> actualItems) {
    return Arrays.equals(expectedLayout, actualLayout)
        && expectedItems != null
        && expectedItems.equals(actualItems);
  }

  private void ensurePersistentTagTab(int iconItemId) {
    String standardizedTag = Text.standardize(TAG_NAME);
    String configuredTabs =
        configs.getConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG);
    List<String> tabs = new ArrayList<>(Text.fromCSV(configuredTabs == null ? "" : configuredTabs));
    boolean found = false;
    for (String tab : tabs) {
      if (standardizedTag.equals(Text.standardize(tab))) {
        found = true;
        break;
      }
    }
    if (!found) {
      tabs.add(standardizedTag);
      configs.setConfiguration(
          BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tabs));
    }
    if (iconItemId > 0) {
      configs.setConfiguration(
          BankTagsPlugin.CONFIG_GROUP,
          BankTagsPlugin.TAG_ICON_PREFIX + standardizedTag,
          Integer.toString(iconItemId));
    }
  }

  private static int chooseIcon(KitPlan plan, Set<Integer> fallback) {
    List<KitItem> equipment = plan.getEquipmentItems();
    if (!equipment.isEmpty() && concrete(equipment.get(0))) {
      return equipment.get(0).getItemId();
    }
    if (equipment.size() > 4 && concrete(equipment.get(4))) {
      return equipment.get(4).getItemId();
    }
    return fallback.iterator().next();
  }

  private int resolveOwnedDizanaVariantId(KitPlan plan) {
    List<KitItem> equipment = plan == null ? Collections.emptyList() : plan.getEquipmentItems();
    int cape =
        equipment.size() > 1 && concrete(equipment.get(1)) ? equipment.get(1).getItemId() : -1;
    if (!shouldResolveOwnedDizanaVariantForPlan(cape)) {
      return -1;
    }
    if (isUsableDizanaVariantId(cape) && isExactItemLive(cape)) {
      return cape;
    }
    int resolved =
        bestDizanaVariantInContainer(
            client == null ? null : client.getItemContainer(InventoryID.WORN));
    if (resolved > 0) {
      return resolved;
    }
    resolved =
        bestDizanaVariantInContainer(
            client == null ? null : client.getItemContainer(InventoryID.INV));
    if (resolved > 0) {
      return resolved;
    }
    resolved =
        bestDizanaVariantInContainer(
            client == null ? null : client.getItemContainer(InventoryID.BANK));
    if (resolved > 0) {
      return resolved;
    }
    return isUsableDizanaVariantId(cape) ? cape : -1;
  }

  private boolean isExactItemLive(int itemId) {
    if (itemId <= 0 || client == null) {
      return false;
    }
    return containerHasExactItem(client.getItemContainer(InventoryID.WORN), itemId)
        || containerHasExactItem(client.getItemContainer(InventoryID.INV), itemId)
        || containerHasExactItem(client.getItemContainer(InventoryID.BANK), itemId);
  }

  private static boolean containerHasExactItem(ItemContainer container, int itemId) {
    if (container == null || itemId <= 0) {
      return false;
    }
    for (Item item : container.getItems()) {
      if (item != null && item.getId() == itemId && item.getQuantity() > 0) {
        return true;
      }
    }
    return false;
  }

  private static int bestDizanaVariantInContainer(ItemContainer container) {
    if (container == null) {
      return -1;
    }
    int bestId = -1;
    int bestScore = -1;
    for (Item item : container.getItems()) {
      if (item == null || item.getQuantity() <= 0) {
        continue;
      }
      int itemId = item.getId();
      if (itemId <= 0) {
        continue;
      }
      int score = dizanaVariantScore(itemId);
      if (score > bestScore) {
        bestScore = score;
        bestId = itemId;
      }
    }
    return bestScore > 0 ? bestId : -1;
  }

  private static boolean isUsableDizanaVariantId(int raw) {
    return raw > 0 && dizanaVariantScore(raw) > 0;
  }

  static boolean shouldResolveOwnedDizanaVariantForPlan(int cape) {
    return isUsableDizanaVariantId(cape);
  }

  private static boolean isRuneReferenceId(int itemId) {
    switch (itemId) {
      case ItemID.AIRRUNE:
      case ItemID.WATERRUNE:
      case ItemID.EARTHRUNE:
      case ItemID.FIRERUNE:
      case ItemID.MINDRUNE:
      case ItemID.CHAOSRUNE:
      case ItemID.DEATHRUNE:
      case ItemID.BLOODRUNE:
      case ItemID.COSMICRUNE:
      case ItemID.SOULRUNE:
      case ItemID.LAWRUNE:
      case ItemID.WRATHRUNE:
      case ItemID.MISTRUNE:
      case ItemID.DUSTRUNE:
      case ItemID.SMOKERUNE:
      case ItemID.MUDRUNE:
      case ItemID.STEAMRUNE:
      case ItemID.LAVARUNE:
      case ItemID.AETHERRUNE:
        return true;
      default:
        return false;
    }
  }

  private static int dizanaVariantScore(int itemId) {
    switch (itemId) {
      case ItemID.SKILLCAPE_MAX_DIZANAS:
      case ItemID.SKILLCAPE_MAX_DIZANAS_TROUVER:
        return 400;
      case ItemID.DIZANAS_QUIVER_INFINITE:
      case ItemID.DIZANAS_QUIVER_INFINITE_TROUVER:
        return 300;
      case ItemID.DIZANAS_QUIVER_CHARGED:
      case ItemID.DIZANAS_QUIVER_CHARGED_TROUVER:
        return 200;
      case ItemID.DIZANAS_QUIVER_UNCHARGED:
      case ItemID.DIZANAS_QUIVER_UNCHARGED_TROUVER:
        return 100;
      default:
        return -1;
    }
  }

  private static boolean planContainsUsableDizanaCape(KitPlan plan) {
    if (plan == null) {
      return false;
    }
    for (KitItem item : plan.getEquipmentItems()) {
      if (item == null || item.getDisplayName() == null) {
        continue;
      }
      if (item.hasItemId() && isUsableDizanaVariantId(item.getItemId())) {
        return true;
      }
      String name = normalizeName(item.getDisplayName());
      if (name.contains("dizana")
          && (name.contains("quiver") || name.contains("max cape"))
          && !name.contains("max hood")
          && !name.contains("broken")
          && !name.contains("mangled")) {
        return true;
      }
    }
    return false;
  }

  private static boolean planContainsItemId(KitPlan plan, int raw) {
    int itemId = raw;
    if (itemId <= 0) {
      return false;
    }
    return containsItemId(plan.getEquipmentItems(), itemId)
        || containsItemId(plan.getInventoryItems(), itemId)
        || containsItemId(plan.getOptionalItems(), itemId);
  }

  private static boolean containsItemId(List<KitItem> items, int itemId) {
    for (KitItem item : items) {
      if (concrete(item) && item.getItemId() == itemId) {
        return true;
      }
    }
    return false;
  }

  private static boolean duplicatesConcreteEquipment(
      KitItem optionalItem, List<KitItem> equipment) {
    return concrete(optionalItem) && containsItemId(equipment, optionalItem.getItemId());
  }

  private static KitItem findLightbearer(KitPlan plan) {
    KitItem item = findLightbearer(plan.getEquipmentItems());
    if (item != null) {
      return item;
    }
    item = findLightbearer(plan.getInventoryItems());
    if (item != null) {
      return item;
    }
    return findLightbearer(plan.getOptionalItems());
  }

  private static KitItem findLightbearer(List<KitItem> items) {
    if (items == null) {
      return null;
    }
    for (KitItem item : items) {
      if (isLightbearer(item) && concrete(item)) {
        return item;
      }
    }
    return null;
  }

  private static boolean isLightbearer(KitItem item) {
    if (item == null || item.getDisplayName() == null) {
      return false;
    }
    return normalizeName(item.getDisplayName()).contains("lightbearer");
  }

  static List<InventoryPlacement> planInventoryForBankTag(
      List<KitItem> source, int reservedSlotIndex, boolean sourceSlotZeroIsTravel) {
    return planInventoryForBankTag(source, reservedSlotIndex, sourceSlotZeroIsTravel, false);
  }

  static List<InventoryPlacement> planInventoryForBankTag(
      List<KitItem> source,
      int reservedSlotIndex,
      boolean sourceSlotZeroIsTravel,
      boolean rowSwitches) {
    if (source == null || source.isEmpty()) {
      return Collections.emptyList();
    }
    List<Candidate> candidates = new ArrayList<>();
    for (int index = 0; index < source.size(); index++) {
      KitItem item = source.get(index);
      if (concrete(item) && !isLightbearer(item)) {
        candidates.add(new Candidate(item, index));
      }
    }
    return planInventoryCandidates(
        candidates, reservedSlotIndex, sourceSlotZeroIsTravel, rowSwitches);
  }

  private static List<InventoryPlacement> planInventoryCandidates(
      List<Candidate> source,
      int requestedReservedSlotIndex,
      boolean sourceSlotZeroIsTravel,
      boolean rowSwitches) {
    if (source == null || source.isEmpty()) {
      return Collections.emptyList();
    }
    List<Candidate> remaining = new ArrayList<>(source);
    List<InventoryPlacement> result = new ArrayList<>(source.size());
    boolean[] occupied = new boolean[INVENTORY_LIMIT];
    Candidate runePouch = firstRunePouch(remaining);
    int reservedSlotIndex = requestedReservedSlotIndex;
    if (runePouch != null && reservedSlotIndex == INVENTORY_LIMIT - 1) {
      reservedSlotIndex = 0;
    }
    if (reservedSlotIndex >= 0 && reservedSlotIndex < INVENTORY_LIMIT) {
      occupied[reservedSlotIndex] = true;
    }
    if (runePouch != null) {
      int runePouchSlot = RUNE_POUCH_INVENTORY_SLOT;
      occupied[runePouchSlot] = true;
      result.add(new InventoryPlacement(runePouch.item, runePouchSlot));
      remaining.remove(runePouch);
    }
    if (sourceSlotZeroIsTravel) {
      Candidate authoredTravel = findSourceIndex(remaining, 0);
      if (authoredTravel != null) {
        int preferred =
            runePouch == null ? TRAVEL_SLOT_WITHOUT_RUNE_POUCH : TRAVEL_SLOT_WITH_RUNE_POUCH;
        int slot = !occupied[preferred] ? preferred : lastFreeSlot(occupied);
        if (slot >= 0) {
          occupied[slot] = true;
          result.add(new InventoryPlacement(authoredTravel.item, slot));
          remaining.remove(authoredTravel);
        }
      }
    }
    placeEquipmentSwitchGroups(remaining, occupied, result, rowSwitches);
    List<Candidate> tops = new ArrayList<>();
    List<Candidate> legs = new ArrayList<>();
    for (Candidate candidate : remaining) {
      if (!candidate.item.isEquipmentSwitch() && isArmorTop(candidate.item)) {
        tops.add(candidate);
      } else if (!candidate.item.isEquipmentSwitch() && isArmorLegs(candidate.item)) {
        legs.add(candidate);
      }
    }
    for (Candidate top : tops) {
      Candidate legsItem = takeMatchingLegs(top, legs);
      if (legsItem == null) {
        continue;
      }
      int topSlot = firstFreeVerticalPair(occupied);
      if (topSlot < 0) {
        break;
      }
      int legsSlot = topSlot + 4;
      occupied[topSlot] = true;
      occupied[legsSlot] = true;
      result.add(new InventoryPlacement(top.item, topSlot));
      result.add(new InventoryPlacement(legsItem.item, legsSlot));
      remaining.remove(top);
      remaining.remove(legsItem);
    }
    placeCannonBlock(remaining, occupied, result);
    placeBottomUtilities(remaining, occupied, result);
    remaining.sort(
        (left, right) -> {
          int leftGroup = bankInventoryVisualGroup(left.item);
          int rightGroup = bankInventoryVisualGroup(right.item);
          if (leftGroup != rightGroup) {
            return Integer.compare(leftGroup, rightGroup);
          }
          if (leftGroup == 0) {
            return 0;
          }
          int family =
              bankInventoryVisualFamily(left.item).compareTo(bankInventoryVisualFamily(right.item));
          if (family != 0) {
            return family;
          }
          return normalizeName(left.item.getDisplayName())
              .compareTo(normalizeName(right.item.getDisplayName()));
        });
    for (Candidate candidate : remaining) {
      int slot = firstFreeSlot(occupied);
      if (slot < 0) {
        break;
      }
      occupied[slot] = true;
      result.add(new InventoryPlacement(candidate.item, slot));
    }
    return result;
  }

  private static void placeCannonBlock(
      List<Candidate> remaining, boolean[] occupied, List<InventoryPlacement> result) {
    List<Candidate> parts = new ArrayList<>();
    for (Candidate candidate : remaining) {
      if (cannonPartOrder(candidate.item) >= 0) {
        parts.add(candidate);
      }
    }
    if (parts.size() < 4) {
      return;
    }
    parts.sort(
        (left, right) -> Integer.compare(cannonPartOrder(left.item), cannonPartOrder(right.item)));
    int blockStart = firstFreeTwoByTwoBlock(occupied);
    if (blockStart < 0) {
      return;
    }
    int[] positions = {blockStart, blockStart + 1, blockStart + 4, blockStart + 5};
    for (int index = 0; index < 4; index++) {
      Candidate part = parts.get(index);
      int slot = positions[index];
      occupied[slot] = true;
      result.add(new InventoryPlacement(part.item, slot));
      remaining.remove(part);
    }
  }

  private static int cannonPartOrder(KitItem item) {
    String name = normalizeName(item == null ? "" : item.getDisplayName());
    if (name.contains("cannon base")) {
      return 0;
    }
    if (name.contains("cannon stand")) {
      return 1;
    }
    if (name.contains("cannon barrels")) {
      return 2;
    }
    if (name.contains("cannon furnace")) {
      return 3;
    }
    return -1;
  }

  private static int firstFreeTwoByTwoBlock(boolean[] occupied) {
    int[] topRows = {0, 2, 4};
    for (int row : topRows) {
      for (int column = 0; column < 3; column++) {
        int start = row * 4 + column;
        if (!occupied[start]
            && !occupied[start + 1]
            && !occupied[start + 4]
            && !occupied[start + 5]) {
          return start;
        }
      }
    }
    return -1;
  }

  private static void placeBottomUtilities(
      List<Candidate> remaining, boolean[] occupied, List<InventoryPlacement> result) {
    List<Candidate> utilities = new ArrayList<>();
    for (Candidate candidate : remaining) {
      if (isBottomUtility(candidate.item)) {
        utilities.add(candidate);
      }
    }
    if (utilities.isEmpty()) {
      return;
    }
    List<Integer> slots = bottomAlignedFreeSlots(occupied, utilities.size());
    for (int index = 0; index < utilities.size() && index < slots.size(); index++) {
      Candidate utility = utilities.get(index);
      int slot = slots.get(index);
      occupied[slot] = true;
      result.add(new InventoryPlacement(utility.item, slot));
      remaining.remove(utility);
    }
  }

  private static List<Integer> bottomAlignedFreeSlots(boolean[] occupied, int requestedCount) {
    List<Integer> result = new ArrayList<>();
    int remaining = requestedCount;
    for (int row = 6; row >= 0 && remaining > 0; row--) {
      List<Integer> free = new ArrayList<>();
      for (int column = 0; column < 4; column++) {
        int slot = row * 4 + column;
        if (!occupied[slot]) {
          free.add(slot);
        }
      }
      int take = Math.min(remaining, free.size());
      int first = free.size() - take;
      for (int index = first; index < free.size(); index++) {
        result.add(free.get(index));
      }
      remaining -= take;
    }
    return result;
  }

  private static boolean isBottomUtility(KitItem item) {
    if (item == null || item.isEquipmentSwitch()) {
      return false;
    }
    if (item.getInventoryGroup() == MethodRules.InventoryGroup.UTILITY) {
      return !isRunePouch(item);
    }
    String name = normalizeName(item.getDisplayName());
    return matchesAny(name, SlayerLoadoutData.list("bank_utility_names"));
  }

  private static void placeEquipmentSwitchGroups(
      List<Candidate> remaining,
      boolean[] occupied,
      List<InventoryPlacement> result,
      boolean rowSwitches) {
    List<SwitchGroup> groups = new ArrayList<>();
    for (Candidate candidate : remaining) {
      if (!candidate.item.isEquipmentSwitch()) {
        continue;
      }
      SwitchGroup matching = null;
      for (SwitchGroup group : groups) {
        if (group.style == candidate.item.getSwitchStyle()) {
          matching = group;
          break;
        }
      }
      if (matching == null) {
        matching = new SwitchGroup(candidate.item.getSwitchStyle());
        groups.add(matching);
      }
      matching.items.add(candidate);
    }
    groups.sort((left, right) -> Integer.compare(right.items.size(), left.items.size()));
    if (rowSwitches) {
      for (SwitchGroup group : groups) {
        for (Candidate candidate : group.items) {
          int slot = firstFreeSlot(occupied);
          if (slot < 0) {
            return;
          }
          occupied[slot] = true;
          result.add(new InventoryPlacement(candidate.item, slot));
          remaining.remove(candidate);
        }
      }
      return;
    }
    List<Integer> verticalColumns = new ArrayList<>();
    int[] topRows = {0, 2, 4};
    for (int topRow : topRows) {
      for (int column = 0; column < 4; column++) {
        int topSlot = topRow * 4 + column;
        if (!occupied[topSlot] && !occupied[topSlot + 4]) {
          verticalColumns.add(topSlot);
        }
      }
    }
    int columnIndex = 0;
    for (SwitchGroup group : groups) {
      List<Candidate> ordered = orderSwitchGroup(group.items);
      int itemIndex = 0;
      while (itemIndex < ordered.size() && columnIndex < verticalColumns.size()) {
        int topSlot = verticalColumns.get(columnIndex++);
        Candidate upper = ordered.get(itemIndex++);
        occupied[topSlot] = true;
        result.add(new InventoryPlacement(upper.item, topSlot));
        remaining.remove(upper);
        if (itemIndex < ordered.size()) {
          int lowerSlot = topSlot + 4;
          Candidate lower = ordered.get(itemIndex++);
          occupied[lowerSlot] = true;
          result.add(new InventoryPlacement(lower.item, lowerSlot));
          remaining.remove(lower);
        }
      }
    }
  }

  private static List<Candidate> orderSwitchGroup(List<Candidate> source) {
    List<Candidate> remaining = new ArrayList<>(source);
    List<Candidate> ordered = new ArrayList<>(source.size());
    List<Candidate> tops = new ArrayList<>();
    List<Candidate> legs = new ArrayList<>();
    for (Candidate candidate : source) {
      if (isArmorTop(candidate.item)) {
        tops.add(candidate);
      } else if (isArmorLegs(candidate.item)) {
        legs.add(candidate);
      }
    }
    for (Candidate top : tops) {
      Candidate legsItem = takeMatchingLegs(top, legs);
      if (legsItem != null) {
        ordered.add(top);
        ordered.add(legsItem);
        remaining.remove(top);
        remaining.remove(legsItem);
      }
    }
    ordered.addAll(remaining);
    return ordered;
  }

  private static Candidate firstRunePouch(List<Candidate> candidates) {
    for (Candidate candidate : candidates) {
      if (isRunePouch(candidate.item)) {
        return candidate;
      }
    }
    return null;
  }

  private static Candidate findSourceIndex(List<Candidate> candidates, int sourceIndex) {
    for (Candidate candidate : candidates) {
      if (candidate.sourceIndex == sourceIndex) {
        return candidate;
      }
    }
    return null;
  }

  private static Candidate takeMatchingLegs(Candidate top, List<Candidate> availableLegs) {
    if (availableLegs.isEmpty()) {
      return null;
    }
    String topFamily = armorSetFamily(top.item);
    for (int index = 0; index < availableLegs.size(); index++) {
      Candidate candidate = availableLegs.get(index);
      if (!topFamily.isEmpty() && topFamily.equals(armorSetFamily(candidate.item))) {
        availableLegs.remove(index);
        return candidate;
      }
    }
    return availableLegs.remove(0);
  }

  private static int firstFreeVerticalPair(boolean[] occupied) {
    int[] topRows = {0, 2, 4};
    for (int topRow : topRows) {
      for (int column = 0; column < 4; column++) {
        int topSlot = topRow * 4 + column;
        int legsSlot = topSlot + 4;
        if (!occupied[topSlot] && !occupied[legsSlot]) {
          return topSlot;
        }
      }
    }
    return -1;
  }

  private static int firstFreeSlot(boolean[] occupied) {
    for (int slot = 0; slot < occupied.length; slot++) {
      if (!occupied[slot]) {
        return slot;
      }
    }
    return -1;
  }

  private static int lastFreeSlot(boolean[] occupied) {
    for (int slot = occupied.length - 1; slot >= 0; slot--) {
      if (!occupied[slot]) {
        return slot;
      }
    }
    return -1;
  }

  private static boolean isRunePouch(KitItem item) {
    return normalizeName(item == null ? "" : item.getDisplayName()).contains("rune pouch");
  }

  private static boolean isArmorTop(KitItem item) {
    String name = normalizeName(item == null ? "" : item.getDisplayName());
    String words = " " + name + " ";
    return matchesAny(name, SlayerLoadoutData.list("body_armor_fragments"))
        || words.contains(" body ")
        || words.contains(" top ");
  }

  private static boolean isArmorLegs(KitItem item) {
    String name = normalizeName(item == null ? "" : item.getDisplayName());
    String words = " " + name + " ";
    return matchesAny(name, SlayerLoadoutData.list("leg_armor_fragments"))
        || words.contains(" leg ")
        || words.contains(" legs ")
        || words.contains(" skirt ")
        || words.contains(" bottoms ");
  }

  private static String armorSetFamily(KitItem item) {
    return normalizeName(item == null ? "" : item.getDisplayName())
        .replaceAll(
            "\\b(?:robe top|robe bottom|robetop|robebottom|robeskirt|"
                + "leathertop|leatherskirt|platebody|platelegs|plateskirt|"
                + "chainbody|chainskirt|chestplate|hauberk|torso|tunic|"
                + "tassets|chaps|trousers|cuisse|body|top|leg|legs|skirt|bottoms)\\b",
            " ")
        .replaceAll("\\s+", " ")
        .trim();
  }

  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  private static final class Candidate {
    private final KitItem item;
    private final int sourceIndex;
  }

  private static final class SwitchGroup {
    private final KitItem.SwitchStyle style;
    private final List<Candidate> items = new ArrayList<>();

    private SwitchGroup(KitItem.SwitchStyle style) {
      this.style = style == null ? KitItem.SwitchStyle.OTHER : style;
    }
  }

  @Getter(AccessLevel.PACKAGE)
  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  static final class InventoryPlacement {
    private final KitItem item;
    private final int slotIndex;
  }

  private static int bankInventoryVisualGroup(KitItem item) {
    String name = normalizeName(item == null ? "" : item.getDisplayName());
    if (name.contains("saradomin brew")) {
      return 3;
    }
    if (name.contains("goading potion")) {
      return 0;
    }
    if (matchesAny(name, SlayerLoadoutData.list("restore_potion_names"))) {
      return 4;
    }
    if (isBankInventoryFood(name)) {
      return 5;
    }
    if (matchesAny(name, SlayerLoadoutData.list("protection_potion_names"))) {
      return 2;
    }
    if (matchesAny(name, SlayerLoadoutData.list("boost_potion_names"))) {
      return 1;
    }
    return 0;
  }

  private static boolean isBankInventoryFood(String name) {
    return matchesAny(name, SlayerLoadoutData.list("bank_food_names"));
  }

  private static String bankInventoryVisualFamily(KitItem item) {
    return normalizeName(item == null ? "" : item.getDisplayName())
        .replaceFirst("^divine ", "")
        .replaceFirst(" [1-4]$", "")
        .trim();
  }

  private static String normalizeName(String value) {
    return value == null
        ? ""
        : value
            .toLowerCase(java.util.Locale.ENGLISH)
            .replace('’', '\'')
            .replaceAll("[^a-z0-9]+", " ")
            .trim();
  }

  private static boolean place(Layout layout, Set<Integer> tags, KitItem item, int position) {
    if (!concrete(item)) {
      return false;
    }
    return placeItemId(layout, tags, item.getItemId(), position);
  }

  private static boolean placeInventory(
      Layout layout, Set<Integer> tags, KitItem item, int position) {
    if (!concrete(item)) {
      return false;
    }
    return placeInventoryItemId(layout, tags, item.getItemId(), position);
  }

  static boolean placeBraceletAlternative(
      Layout layout, Set<Integer> tags, int recommendedId, Set<Integer> pinnedIds) {
    return placeEquipmentItemId(
        layout,
        tags,
        braceletAlternativeId(recommendedId),
        EQUIPMENT_POSITIONS[8] + BANK_COLUMNS,
        pinnedIds);
  }

  private static int braceletAlternativeId(int recommendedId) {
    return recommendedId == ItemID.EXPEDITIOUS_BRACELET
        ? ItemID.BRACELET_OF_SLAUGHTER
        : recommendedId == ItemID.BRACELET_OF_SLAUGHTER ? ItemID.EXPEDITIOUS_BRACELET : -1;
  }

  static boolean showOptionalItem(
      KitItem item, List<KitItem> equipment, int braceletAlternative, Set<Integer> pinnedIds) {
    return pinnedIds.contains(item.getItemId())
        || !(item.getItemId() == braceletAlternative
            || isLightbearer(item)
            || duplicatesConcreteEquipment(item, equipment));
  }

  static boolean placeEquipmentItemId(
      Layout layout, Set<Integer> tags, int raw, int position, Set<Integer> pinnedIds) {
    return pinnedIds.contains(raw)
        ? placeInventoryItemId(layout, tags, raw, position)
        : placeItemId(layout, tags, raw, position);
  }

  private static boolean placeInventoryItemId(
      Layout layout, Set<Integer> tags, int raw, int position) {
    if (raw <= 0) {
      return false;
    }
    tags.add(raw);
    layout.setItemAtPos(raw, position);
    return true;
  }

  private static boolean placeItemId(Layout layout, Set<Integer> tags, int raw, int position) {
    if (raw <= 0 || !tags.add(raw)) {
      return false;
    }
    layout.setItemAtPos(raw, position);
    return true;
  }

  private static boolean concrete(KitItem item) {
    return item != null && item.hasItemId();
  }

  private static int position(int row, int column) {
    return row * BANK_COLUMNS + column;
  }

  @Getter
  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  public static final class Result {
    private final boolean success;
    private final String message;

    public static Result success(String message) {
      return new Result(true, message);
    }

    public static Result failure(String message) {
      return new Result(false, message);
    }
  }

  static boolean optionalItemDuplicatesEquipmentForTest(
      KitItem optionalItem, List<KitItem> equipment) {
    return duplicatesConcreteEquipment(optionalItem, equipment);
  }

  static boolean preparationReferencesRenderBelowGearForTest() {
    int lowestEquipmentRow = 0;
    for (int equipmentPosition : EQUIPMENT_POSITIONS) {
      lowestEquipmentRow = Math.max(lowestEquipmentRow, equipmentPosition / BANK_COLUMNS);
    }
    return PREPARATION_REFERENCE_START_ROW > lowestEquipmentRow
        && PREPARATION_REFERENCE_START_COLUMN == 0
        && PREPARATION_REFERENCE_COLUMNS == 4;
  }
}

