package com.slayerplus;

import java.util.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.util.Text;

final class SlayerOptionalPins {
  static final String CONFIG_KEY = "optionalItemPinsV1";
  static final int LIMIT = 8;

  private SlayerOptionalPins() {}

  static boolean allowsMenu(String activeTag, int componentId, int itemId, boolean shiftHeld) {
    return componentId == InterfaceID.Bankmain.ITEMS
        && itemId > 0
        && (shiftHeld
            || activeTag != null
                && Text.standardize(BankTagLayout.TAG_NAME).equals(Text.standardize(activeTag)));
  }

  static boolean isMenuTrigger(String option, boolean bankContainsItem) {
    // Match Bank Tags: potion-storage entries have no Examine action.
    return "Examine".equals(option) || "Withdraw-All-but-1".equals(option) && !bankContainsItem;
  }

  static Set<Integer> read(String saved) {
    Set<Integer> pins = new LinkedHashSet<>();
    for (int id : SlayerPlusPlugin.parseItemIds(saved)) {
      if (pins.size() == LIMIT) {
        break;
      }
      pins.add(id);
    }
    return pins;
  }

  static KitPlan prepend(KitPlan plan, List<KitItem> pins) {
    if (plan == null || pins.isEmpty()) {
      return plan;
    }
    Map<Integer, KitItem> optional = new LinkedHashMap<>();
    for (KitItem item : pins) {
      if (optional.size() == LIMIT) {
        break;
      }
      if (item.hasItemId()) {
        optional.putIfAbsent(item.getItemId(), item);
      }
    }
    // BankTagLayout applies its existing equipment/swap filters to unpinned items.
    for (KitItem item : plan.getOptionalItems()) {
      if (item.hasItemId()) {
        optional.putIfAbsent(item.getItemId(), item);
      }
    }
    return new KitPlan(
        plan.getOwnedStatus(),
        plan.getLayoutTitle(),
        plan.getEquipmentItems(),
        plan.getInventoryItems(),
        new ArrayList<>(optional.values()));
  }
}

package com.slayerplus;

import java.util.*;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;

class SlayerElementalWeaknessCatalog {
  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  private enum Element {
    AIR("Wind"),
    EARTH("Earth"),
    FIRE("Fire"),
    WATER("Water");
    private final String spellLabel;
  }

  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  static final class Entry {
    private final Element element;
    private final int percent;

    String getSpellLabel() {
      return element.spellLabel;
    }

    int getPercent() {
      return percent;
    }
  }

  private static final Map<String, Entry> ENTRIES = createEntries();

  private SlayerElementalWeaknessCatalog() {}

  static Entry find(String assignment) {
    return ENTRIES.get(normalize(assignment));
  }

  static TaskStrategy preferenceStrategy(String assignment, boolean wilderness) {
    Entry entry = find(assignment);
    if (entry == null) {
      return null;
    }
    TaskStrategy.Builder builder =
        TaskStrategy.builder(
                TaskStrategy.CombatStyle.MAGIC,
                "Use the best "
                    + entry.element.spellLabel
                    + " spell against the Wiki-listed "
                    + entry.percent
                    + "% "
                    + entry.element.spellLabel
                    + " weakness")
            .armourFocus(TaskStrategy.ArmourFocus.DAMAGE)
            .costPolicy(
                wilderness ? TaskStrategy.CostPolicy.LOW_RISK : TaskStrategy.CostPolicy.EFFICIENT)
            .weapons(staffPriorities(entry.element))
            .runePouch(true)
            .strictWeaponProfile(true)
            .prayers(3)
            .tags(TaskStrategy.MethodTag.PREFERENCE_ONLY_ALTERNATIVE)
            .reviewed(TaskResearch.REVIEW_DATE);
    if (wilderness) {
      builder.tags(
          TaskStrategy.MethodTag.PREFERENCE_ONLY_ALTERNATIVE, TaskStrategy.MethodTag.WILDERNESS);
    }
    return builder.build();
  }

  static int sizeForTest() {
    return ENTRIES.size();
  }

  private static String[] staffPriorities(Element element) {
    switch (element) {
      case WATER:
        return SlayerLoadoutData.array("water_weakness_staves");
      case FIRE:
        return SlayerLoadoutData.array("fire_weakness_staves");
      case EARTH:
        return SlayerLoadoutData.array("earth_weakness_staves");
      case AIR:
      default:
        return SlayerLoadoutData.array("air_weakness_staves");
    }
  }

  private static Map<String, Entry> createEntries() {
    Map<String, Entry> map = new LinkedHashMap<>();
    for (String[] row : ResourceTable.rows("slayer-elemental-weaknesses.tsv", 3)) {
      put(map, Element.valueOf(row[1]), Integer.parseInt(row[2]), row[0]);
    }
    return Collections.unmodifiableMap(map);
  }

  private static void put(
      Map<String, Entry> map, Element element, int percent, String... taskNames) {
    for (String assignment : taskNames) {
      String key = normalize(assignment);
      if (map.put(key, new Entry(element, percent)) != null) {
        throw new IllegalStateException("Duplicate elemental weakness audit: " + assignment);
      }
    }
  }

  private static String normalize(String value) {
    return SlayerText.encounter(value);
  }
}

