package com.slayerplus;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.util.Text;

@Getter(AccessLevel.PACKAGE)
@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
class SlayerTaskChatUpdate {
  private static final Pattern ASSIGNMENT =
      Pattern.compile(
          "^you(?:'|\u2019)re assigned to kill (.+?);\\s*(?:only\\s+)?([\\d,]+) more to go\\.?$",
          Pattern.CASE_INSENSITIVE);
  private static final Pattern STATUS =
      Pattern.compile(
          "^you(?:'|\u2019)ve completed ([\\d,]+) tasks? in a row and currently have a total of"
              + " ([\\d,]+) points?\\.?$",
          Pattern.CASE_INSENSITIVE);
  private final String assignment;
  private final int remaining;
  private final int streak;
  private final int points;

  static SlayerTaskChatUpdate parse(String rawMessage) {
    if (rawMessage == null) {
      return null;
    }
    String message = Text.removeTags(rawMessage).replace('\u00a0', ' ').trim();
    Matcher assignment = ASSIGNMENT.matcher(message);
    if (assignment.matches()) {
      return new SlayerTaskChatUpdate(
          formatTaskName(assignment.group(1)), parseNumber(assignment.group(2)), -1, -1);
    }
    Matcher status = STATUS.matcher(message);
    if (status.matches()) {
      return new SlayerTaskChatUpdate(
          "", -1, parseNumber(status.group(1)), parseNumber(status.group(2)));
    }
    return null;
  }

  private static int parseNumber(String value) {
    try {
      return Integer.parseInt(value.replace(",", ""));
    } catch (NumberFormatException ex) {
      return -1;
    }
  }

  private static String formatTaskName(String value) {
    String trimmed = value == null ? "" : value.trim();
    if (trimmed.isEmpty()) {
      return "";
    }
    String lower = trimmed.toLowerCase(Locale.ENGLISH);
    return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
  }

  String getTaskName() {
    return assignment;
  }
}

package com.slayerplus;

import java.util.*;

/** Ordered item-name and matching-fragment data used by loadout selection and layout rendering. */
final class SlayerLoadoutData {
  private static final Map<String, List<String>> LISTS = load("slayer-loadout-lists.tsv");
  private static final Map<String, List<String>> ARRAYS = load("slayer-loadout-arrays.tsv");

  private SlayerLoadoutData() {}

  static List<String> list(String key) {
    return value(LISTS, key);
  }

  static String[] array(String key) {
    return value(ARRAYS, key).toArray(new String[0]);
  }

  private static List<String> value(Map<String, List<String>> values, String key) {
    List<String> result = values.get(key);
    if (result == null) {
      throw new IllegalStateException("Missing Slayer loadout data: " + key);
    }
    return result;
  }

  private static Map<String, List<String>> load(String resource) {
    Map<String, List<String>> values = new LinkedHashMap<>();
    for (String[] row : ResourceTable.rows(resource, 2)) {
      List<String> previous =
          values.put(row[0], Collections.unmodifiableList(Arrays.asList(row[1].split("\\|", -1))));
      if (previous != null) {
        throw new IllegalStateException("Duplicate Slayer loadout data key: " + row[0]);
      }
    }
    return Collections.unmodifiableMap(values);
  }
}

package com.slayerplus;

import java.util.*;
import lombok.Getter;
import net.runelite.api.gameval.ItemID;

@Getter
public final class MethodRules {
  public static final int MAX_TASK_METHOD_LENGTH = 220;

  public enum DamageControl {
    STRATEGY_DEFINED,
    DIRECT_DAMAGE,
    PARTIAL_MITIGATION,
    PRAYER_PROTECTED,
    SAFESPOT,
    FREEZE_SAFESPOT,
    STEP_UNDER,
    BOSS_MECHANICS
  }

  public enum DosePolicy {
    FULLEST_OWNED
  }

  public enum LayoutProfile {
    STANDARD,
    PRAYER_TASK,
    BARRAGE,
    FREEZE_MAGIC,
    CANNON,
    BOSS,
    HYBRID_BOSS,
    WILDERNESS
  }

  public enum Spellbook {
    STRATEGY_DEFINED,
    NONE,
    STANDARD,
    ANCIENT,
    ARCEUUS,
    LUNAR
  }

  public enum UtilityRecommendation {
    NONE,
    OPTIONAL,
    RECOMMENDED
  }

  public enum InventoryGroup {
    TRAVEL,
    UTILITY,
    SWITCH,
    RUNES,
    BOOST,
    PROTECTION,
    RESTORE,
    FOOD,
    OTHER
  }

  @Getter
  public static final class RequiredItem {
    private final String displayName;
    private final int quantity;
    private final int slotCount;
    private final InventoryGroup group;
    private final boolean ownedOnly;
    private final List<String> alternatives;

    private RequiredItem(
        String displayName,
        int quantity,
        int slotCount,
        InventoryGroup group,
        boolean ownedOnly,
        String... alternatives) {
      this.displayName = clean(displayName);
      this.quantity = Math.max(1, quantity);
      this.slotCount = Math.max(1, slotCount);
      this.group = group == null ? InventoryGroup.OTHER : group;
      this.ownedOnly = ownedOnly;
      List<String> values = new ArrayList<>();
      if (alternatives != null) {
        for (String alternative : alternatives) {
          String value = clean(alternative);
          if (!value.isEmpty()) {
            values.add(value);
          }
        }
      }
      this.alternatives = Collections.unmodifiableList(values);
    }
  }

  @Getter
  public static final class RuneRequirement {
    private final int itemId;
    private final String name;
    private final int minimumQuantity;

    private RuneRequirement(int itemId, String name, int minimumQuantity) {
      this.itemId = itemId;
      this.name = clean(name);
      this.minimumQuantity = Math.max(1, minimumQuantity);
    }
  }

  private final String coverageKey;
  private final String method;
  private final String researchSource;
  private final String reviewDate;
  private final boolean reviewed;
  private final TaskStrategy.CombatStyle style;
  private final Spellbook spellbook;
  private final String primarySpell;
  private final UtilityRecommendation thrallRecommendation;
  private final UtilityRecommendation deathChargeRecommendation;
  private final boolean wardOfArceuus;
  private final boolean requireBookOfDead;
  private final boolean requireRunePouch;
  private final int minimumMagicLevel;
  private final List<RuneRequirement> pouchRunes;
  private final boolean cannonMethod;
  private final int cannonballQuantity;
  private final DamageControl control;
  private final DosePolicy dosePolicy;
  private final LayoutProfile layoutProfile;
  private final String primaryRestoreFamily;
  private final String fallbackRestoreFamily;
  private final boolean allowRestoreFallback;
  private final int restoreSlotsOverride;
  private final int foodSlotsOverride;
  private final String foodDisplayName;
  private final List<String> foodAlternatives;
  private final boolean fillRestore;
  private final boolean fillFood;
  private final boolean includeStyleBoost;
  private final boolean includeRunePouchForMagic;
  private final int inventoryTarget;
  private final int loot;
  private final List<RequiredItem> requiredItems;

  private MethodRules(Builder builder) {
    coverageKey = clean(builder.coverageKey);
    method = clean(builder.method);
    researchSource = clean(builder.researchSource);
    reviewDate = clean(builder.reviewDate);
    reviewed = builder.reviewed;
    style = builder.style;
    spellbook = builder.spellbook;
    primarySpell = clean(builder.primarySpell);
    thrallRecommendation = builder.thrallRecommendation;
    deathChargeRecommendation = builder.deathChargeRecommendation;
    wardOfArceuus = builder.wardOfArceuus;
    requireBookOfDead = builder.requireBookOfDead;
    requireRunePouch = builder.requireRunePouch;
    minimumMagicLevel = Math.max(0, builder.minimumMagicLevel);
    pouchRunes = Collections.unmodifiableList(new ArrayList<>(builder.pouchRunes));
    cannonMethod = builder.cannonMethod;
    cannonballQuantity = Math.max(0, builder.cannonballQuantity);
    control = builder.control;
    dosePolicy = builder.dosePolicy;
    layoutProfile = builder.layoutProfile;
    primaryRestoreFamily = clean(builder.primaryRestoreFamily);
    fallbackRestoreFamily = clean(builder.fallbackRestoreFamily);
    allowRestoreFallback = builder.allowRestoreFallback;
    restoreSlotsOverride = builder.restoreSlotsOverride;
    foodSlotsOverride = builder.foodSlotsOverride;
    foodDisplayName = clean(builder.foodDisplayName);
    foodAlternatives = Collections.unmodifiableList(new ArrayList<>(builder.foodAlternatives));
    fillRestore = builder.fillRestore;
    fillFood = builder.fillFood;
    includeStyleBoost = builder.includeStyleBoost;
    includeRunePouchForMagic = builder.includeRunePouchForMagic;
    inventoryTarget = clamp(builder.inventoryTarget, 0, 28);
    loot = clamp(builder.loot, 0, 28);
    requiredItems = Collections.unmodifiableList(new ArrayList<>(builder.requiredItems));
  }

  public static Builder builder() {
    return new Builder();
  }

  public boolean usesThralls() {
    return thrallRecommendation == UtilityRecommendation.RECOMMENDED;
  }

  public boolean usesDeathCharge() {
    return deathChargeRecommendation == UtilityRecommendation.RECOMMENDED;
  }

  public boolean usesWardOfArceuus() {
    return wardOfArceuus;
  }

  public boolean requiresBookOfDead() {
    return requireBookOfDead;
  }

  public boolean requiresRunePouch() {
    return requireRunePouch;
  }

  public boolean usesCannon() {
    return cannonMethod;
  }

  public boolean allowsRestoreFallback() {
    return allowRestoreFallback;
  }

  public boolean hasRestorePolicy() {
    return !primaryRestoreFamily.isEmpty();
  }

  public boolean fillsRemainingWithRestore() {
    return fillRestore;
  }

  public boolean fillsRemainingWithFood() {
    return fillFood;
  }

  public boolean includesStyleBoost() {
    return includeStyleBoost;
  }

  public boolean includesRunePouchForMagic() {
    return includeRunePouchForMagic;
  }

  public boolean preventsExpectedDamageWhenExecuted() {
    return control == DamageControl.PRAYER_PROTECTED
        || control == DamageControl.SAFESPOT
        || control == DamageControl.FREEZE_SAFESPOT;
  }

  public int resolveRestoreSlots(TaskStrategy strategy) {
    if (restoreSlotsOverride >= 0) {
      return restoreSlotsOverride;
    }
    return strategy == null ? 0 : Math.max(0, strategy.getPrayers());
  }

  public int resolveFoodSlots(TaskStrategy strategy, int strategyFoodSlots) {
    if (foodSlotsOverride >= 0) {
      return foodSlotsOverride;
    }
    if (preventsExpectedDamageWhenExecuted()) {
      return 0;
    }
    return Math.max(0, strategyFoodSlots);
  }

  public void validateFor(String encounter, TaskStrategy strategy) {
    String label = clean(encounter).isEmpty() ? "Unknown Slayer encounter" : clean(encounter);
    if (!reviewed) {
      throw new IllegalStateException("Unreviewed Slayer method rules: " + label);
    }
    if (coverageKey.isEmpty()) {
      throw new IllegalStateException("Slayer method has no coverage key: " + label);
    }
    if (style == null) {
      throw new IllegalStateException("Slayer method has no combat style: " + label);
    }
    if (method.isEmpty()) {
      throw new IllegalStateException("Slayer method has no Task Method text: " + label);
    }
    if (method.length() > MAX_TASK_METHOD_LENGTH) {
      throw new IllegalStateException(
          "Task Method is too long for " + label + ": " + method.length() + " characters");
    }
    if (researchSource.isEmpty()) {
      throw new IllegalStateException("Slayer method has no research source: " + label);
    }
    if (reviewDate.isEmpty()) {
      throw new IllegalStateException("Slayer method has no review date: " + label);
    }
    if (fillFood && fillRestore) {
      throw new IllegalStateException("Conflicting inventory-fill rules: " + label);
    }
    if (spellbook == Spellbook.ANCIENT && primarySpell.isEmpty()) {
      throw new IllegalStateException("Ancient spell method has no spell name: " + label);
    }
    if (!pouchRunes.isEmpty()
        && (spellbook == Spellbook.STRATEGY_DEFINED || spellbook == Spellbook.NONE)) {
      throw new IllegalStateException("Rune-pouch method has no selected spellbook: " + label);
    }
    if ((usesThralls() || usesDeathCharge() || usesWardOfArceuus())
        && spellbook != Spellbook.ARCEUUS) {
      throw new IllegalStateException(
          "Arceuus utility method is not on Arceuus spellbook: " + label);
    }
    if (usesThralls() && !requireBookOfDead) {
      throw new IllegalStateException("Thrall method does not require Book of the dead: " + label);
    }
    if ((usesThralls() || usesDeathCharge() || usesWardOfArceuus()) && !requireRunePouch) {
      throw new IllegalStateException(
          "Arceuus utility method does not require a rune pouch: " + label);
    }
    if (usesThralls() && minimumMagicLevel < 76) {
      throw new IllegalStateException(
          "Greater Thrall method has an invalid Magic requirement: " + label);
    }
    if (usesDeathCharge() && minimumMagicLevel < 80) {
      throw new IllegalStateException(
          "Death Charge method has an invalid Magic requirement: " + label);
    }
    if (usesWardOfArceuus() && (spellbook != Spellbook.ARCEUUS || minimumMagicLevel < 73)) {
      throw new IllegalStateException(
          "Ward of Arceuus method has an invalid spellbook/Magic requirement: " + label);
    }
    if ((usesThralls() || usesDeathCharge() || usesWardOfArceuus()) && pouchRunes.isEmpty()) {
      throw new IllegalStateException("Arceuus utility method has no rune-pouch package: " + label);
    }
    if (cannonMethod && cannonballQuantity <= 0) {
      throw new IllegalStateException("Cannon method has no cannonball quantity: " + label);
    }
    if ((resolveRestoreSlots(strategy) > 0 || fillRestore) && primaryRestoreFamily.isEmpty()) {
      throw new IllegalStateException("Restore slots have no potion family: " + label);
    }
    if (allowRestoreFallback && fallbackRestoreFamily.isEmpty()) {
      throw new IllegalStateException(
          "Restore fallback is enabled without a fallback family: " + label);
    }
    if ((resolveFoodSlots(strategy, strategy == null ? 0 : strategy.getFood()) > 0 || fillFood)
        && (foodDisplayName.isEmpty() || foodAlternatives.isEmpty())) {
      throw new IllegalStateException("Food slots have no researched food family: " + label);
    }
    int requiredSlotCount = 0;
    for (RequiredItem require : requiredItems) {
      if (require.getDisplayName().isEmpty()) {
        throw new IllegalStateException("Blank required item in Slayer rules: " + label);
      }
      if (require.getAlternatives().isEmpty()) {
        throw new IllegalStateException(
            "Required Slayer inventory item has no resolvable item family: "
                + label
                + " -> "
                + require.getDisplayName());
      }
      requiredSlotCount += require.getSlotCount();
    }
    if (requiredSlotCount > 28) {
      throw new IllegalStateException(
          "Required Slayer utility items exceed the 4x7 inventory: "
              + label
              + " -> "
              + requiredSlotCount
              + " slots");
    }
  }

  private static String clean(String value) {
    return value == null ? "" : value.trim();
  }

  private static int clamp(int value, int minimum, int maximum) {
    return Math.max(minimum, Math.min(maximum, value));
  }

  public static final class Builder {
    private String coverageKey;
    private String method;
    private String researchSource;
    private String reviewDate;
    private boolean reviewed;
    private TaskStrategy.CombatStyle style;
    private Spellbook spellbook = Spellbook.STRATEGY_DEFINED;
    private String primarySpell;
    private UtilityRecommendation thrallRecommendation = UtilityRecommendation.NONE;
    private UtilityRecommendation deathChargeRecommendation = UtilityRecommendation.NONE;
    private boolean wardOfArceuus;
    private boolean requireBookOfDead;
    private boolean requireRunePouch;
    private int minimumMagicLevel;
    private final List<RuneRequirement> pouchRunes = new ArrayList<>();
    private boolean cannonMethod;
    private int cannonballQuantity;
    private DamageControl control = DamageControl.STRATEGY_DEFINED;
    private DosePolicy dosePolicy = DosePolicy.FULLEST_OWNED;
    private LayoutProfile layoutProfile = LayoutProfile.STANDARD;
    private String primaryRestoreFamily;
    private String fallbackRestoreFamily;
    private boolean allowRestoreFallback;
    private int restoreSlotsOverride = -1;
    private int foodSlotsOverride = -1;
    private String foodDisplayName = "High-healing food";
    private final List<String> foodAlternatives =
        new ArrayList<>(
            Arrays.asList(
                "anglerfish",
                "manta ray",
                "dark crab",
                "moonlight antelope",
                "shark",
                "sea turtle",
                "cooked karambwan",
                "monkfish"));
    private boolean fillRestore;
    private boolean fillFood;
    private boolean includeStyleBoost = true;
    private boolean includeRunePouchForMagic = false;
    private int inventoryTarget;
    private int loot;
    private final List<RequiredItem> requiredItems = new ArrayList<>();

    private Builder() {}

    Builder withoutStandardCombatSpell() {
      if (spellbook == Spellbook.STANDARD && PoweredMagic.replacesStandardAttack(primarySpell)) {
        spellbook = Spellbook.NONE;
        primarySpell = "";
        requireRunePouch = false;
        includeRunePouchForMagic = false;
        pouchRunes.clear();
        requiredItems.removeIf(item -> item.getGroup() == InventoryGroup.RUNES);
      }
      return this;
    }

    public Builder coverageKey(String value) {
      coverageKey = value;
      return this;
    }

    public Builder method(String value) {
      method = value;
      return this;
    }

    public Builder research(String source, String date, boolean isReviewed) {
      researchSource = source;
      reviewDate = date;
      reviewed = isReviewed;
      return this;
    }

    public Builder style(TaskStrategy.CombatStyle value) {
      style = value;
      return this;
    }

    public Builder spell(Spellbook value, String spellName) {
      spellbook = value == null ? Spellbook.STRATEGY_DEFINED : value;
      primarySpell = spellName;
      return this;
    }

    public Builder arceuusUtility(
        boolean useThralls, boolean useDeathCharge, boolean useWardOfArceuus) {
      thrallRecommendation =
          useThralls ? UtilityRecommendation.RECOMMENDED : UtilityRecommendation.NONE;
      deathChargeRecommendation =
          useDeathCharge ? UtilityRecommendation.RECOMMENDED : UtilityRecommendation.NONE;
      wardOfArceuus = useWardOfArceuus;
      return this;
    }

    public Builder cannon(boolean enabled, int cannonballs) {
      cannonMethod = enabled;
      cannonballQuantity = enabled ? Math.max(1, cannonballs) : 0;
      return this;
    }

    public Builder control(DamageControl value) {
      control = value == null ? DamageControl.STRATEGY_DEFINED : value;
      return this;
    }

    public Builder layout(LayoutProfile value) {
      layoutProfile = value == null ? LayoutProfile.STANDARD : value;
      return this;
    }

    public Builder restore(String primaryFamily, String fallbackFamily) {
      primaryRestoreFamily = primaryFamily;
      fallbackRestoreFamily = fallbackFamily;
      allowRestoreFallback = fallbackFamily != null && !fallbackFamily.trim().isEmpty();
      return this;
    }

    public Builder noRestoreFallback() {
      fallbackRestoreFamily = "";
      allowRestoreFallback = false;
      return this;
    }

    public Builder restoreSlots(int value) {
      restoreSlotsOverride = Math.max(0, value);
      return this;
    }

    public Builder food(int value) {
      foodSlotsOverride = Math.max(0, value);
      return this;
    }

    public Builder food(String displayName, String... alternatives) {
      foodDisplayName = clean(displayName);
      foodAlternatives.clear();
      if (alternatives != null) {
        for (String alternative : alternatives) {
          String value = clean(alternative);
          if (!value.isEmpty()) {
            foodAlternatives.add(value);
          }
        }
      }
      return this;
    }

    public Builder noInventoryFill() {
      fillFood = false;
      fillRestore = false;
      return this;
    }

    public Builder runePouch(boolean required) {
      requireRunePouch = required;
      return this;
    }

    public Builder pouchRune(int itemId, String name, int minimumQuantity) {
      pouchRunes.add(new RuneRequirement(itemId, name, minimumQuantity));
      return this;
    }

    public Builder fillRestore() {
      fillRestore = true;
      fillFood = false;
      return this;
    }

    public Builder fillFood() {
      fillFood = true;
      fillRestore = false;
      return this;
    }

    public Builder includeStyleBoost(boolean value) {
      includeStyleBoost = value;
      return this;
    }

    public Builder includeRunePouchForMagic(boolean value) {
      includeRunePouchForMagic = value;
      return this;
    }

    public Builder inventoryTarget(int value) {
      inventoryTarget = value;
      return this;
    }

    public Builder loot(int value) {
      loot = Math.max(0, value);
      return this;
    }

    public Builder require(
        String displayName, int quantity, InventoryGroup group, String... alternatives) {
      requiredItems.add(new RequiredItem(displayName, quantity, 1, group, false, alternatives));
      return this;
    }

    public Builder ownedOnlyItem(
        String displayName, int quantity, InventoryGroup group, String... alternatives) {
      requiredItems.add(new RequiredItem(displayName, quantity, 1, group, true, alternatives));
      return this;
    }

    public Builder requiredSlots(
        String displayName, int slotCount, InventoryGroup group, String... alternatives) {
      requiredItems.add(
          new RequiredItem(displayName, 1, Math.max(1, slotCount), group, false, alternatives));
      return this;
    }

    public MethodRules build() {
      prepareArceuusPackage();
      return new MethodRules(this);
    }

    private void prepareArceuusPackage() {
      boolean thralls = thrallRecommendation == UtilityRecommendation.RECOMMENDED;
      boolean deathCharge = deathChargeRecommendation == UtilityRecommendation.RECOMMENDED;
      boolean ward = wardOfArceuus;
      if (!thralls && !deathCharge && !ward) {
        return;
      }
      spellbook = Spellbook.ARCEUUS;
      requireRunePouch = true;
      requireBookOfDead = thralls;
      minimumMagicLevel = deathCharge ? 80 : thralls ? 76 : 73;
      if (thralls && deathCharge && ward) {
        primarySpell = "Resurrect Greater Ghost + Death Charge + Ward of Arceuus";
      } else if (thralls && deathCharge) {
        primarySpell = "Resurrect Greater Ghost + Death Charge";
      } else if (thralls && ward) {
        primarySpell = "Resurrect Greater Ghost + Ward of Arceuus";
      } else if (deathCharge && ward) {
        primarySpell = "Death Charge + Ward of Arceuus";
      } else if (thralls) {
        primarySpell = "Resurrect Greater Ghost";
      } else if (deathCharge) {
        primarySpell = "Death Charge";
      } else {
        primarySpell = "Ward of Arceuus";
      }
      pouchRunes.clear();
      if (thralls && deathCharge) {
        addRune(ItemID.FIRERUNE, "Fire", 10);
        if (ward) {
          addRune(ItemID.AETHERRUNE, "Aether", 6);
        } else {
          addRune(ItemID.COSMICRUNE, "Cosmic", 1);
          addRune(ItemID.SOULRUNE, "Soul", 1);
        }
        addRune(ItemID.BLOODRUNE, "Blood", 6);
        addRune(ItemID.DEATHRUNE, "Death", 1);
        if (ward) {
          addRune(ItemID.NATURERUNE, "Nature", 2);
        }
        return;
      }
      if (thralls) {
        addRune(ItemID.FIRERUNE, "Fire", 10);
        addRune(ItemID.BLOODRUNE, "Blood", 5);
        if (ward) {
          addRune(ItemID.AETHERRUNE, "Aether", 5);
          addRune(ItemID.NATURERUNE, "Nature", 2);
        } else {
          addRune(ItemID.COSMICRUNE, "Cosmic", 1);
        }
        return;
      }
      if (deathCharge) {
        addRune(ItemID.BLOODRUNE, "Blood", 1);
        addRune(ItemID.DEATHRUNE, "Death", 1);
        if (ward) {
          addRune(ItemID.AETHERRUNE, "Aether", 5);
          addRune(ItemID.NATURERUNE, "Nature", 2);
        } else {
          addRune(ItemID.SOULRUNE, "Soul", 1);
        }
        return;
      }
      addRune(ItemID.SOULRUNE, "Soul", 4);
      addRune(ItemID.NATURERUNE, "Nature", 2);
      addRune(ItemID.COSMICRUNE, "Cosmic", 1);
    }

    private void addRune(int itemId, String name, int minimumQuantity) {
      pouchRunes.add(new RuneRequirement(itemId, name, minimumQuantity));
    }
  }
}

package com.slayerplus;

import static com.slayerplus.SlayerText.normalize;

import java.util.*;

class SlayerTargetFootprintCatalog {
  private static final Set<String> MULTI_TILE_SCYTHE_TARGETS = loadMultiTileScytheTargets();

  private SlayerTargetFootprintCatalog() {}

  static boolean allowsWeapon(String assignment, String weapon) {
    String key = normalize(weapon);
    if (!key.contains("scythe of vitur")) {
      return true;
    }
    return MULTI_TILE_SCYTHE_TARGETS.contains(normalize(assignment));
  }

  static boolean isReviewedMultiTileScytheTarget(String assignment) {
    return MULTI_TILE_SCYTHE_TARGETS.contains(normalize(assignment));
  }

  private static Set<String> loadMultiTileScytheTargets() {
    Set<String> targets = new HashSet<>();
    for (String[] row : ResourceTable.rows("slayer-multitile-targets.tsv", 1)) {
      targets.add(normalize(row[0]));
    }
    return Collections.unmodifiableSet(targets);
  }
}

package com.slayerplus;

import lombok.AccessLevel;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
public final class KitItem {
  public enum SwitchStyle {
    MAGIC,
    RANGED,
    MELEE,
    OTHER
  }

  @Getter
  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  public enum Status {
    EQUIPPED("Equipped"),
    INVENTORY("In inventory"),
    BANK("In bank"),
    MISSING("Missing"),
    UNKNOWN("Bank not scanned");
    private final String label;
  }

  private final String displayName;
  private final int itemId;
  private final int quantity;
  private final Status status;
  private final boolean equipmentSwitch;
  private final SwitchStyle switchStyle;
  private final MethodRules.InventoryGroup inventoryGroup;

  public KitItem(String displayName, int itemId, int quantity, Status status) {
    this(
        displayName,
        itemId,
        quantity,
        status,
        false,
        SwitchStyle.OTHER,
        MethodRules.InventoryGroup.OTHER);
  }

  private KitItem(
      String displayName,
      int itemId,
      int quantity,
      Status status,
      boolean equipmentSwitch,
      SwitchStyle switchStyle,
      MethodRules.InventoryGroup inventoryGroup) {
    this.displayName =
        displayName == null || displayName.trim().isEmpty()
            ? "Recommended item"
            : displayName.trim();
    this.itemId = itemId;
    this.quantity = Math.max(1, quantity);
    this.status = status == null ? Status.UNKNOWN : status;
    this.equipmentSwitch = equipmentSwitch;
    this.switchStyle = switchStyle == null ? SwitchStyle.OTHER : switchStyle;
    this.inventoryGroup =
        inventoryGroup == null ? MethodRules.InventoryGroup.OTHER : inventoryGroup;
  }

  public KitItem asEquipmentSwitch(SwitchStyle style) {
    return new KitItem(displayName, itemId, quantity, status, true, style, inventoryGroup);
  }

  public KitItem withInventoryGroup(MethodRules.InventoryGroup group) {
    return new KitItem(displayName, itemId, quantity, status, equipmentSwitch, switchStyle, group);
  }

  KitItem withQuantity(int value) {
    return new KitItem(
        displayName, itemId, value, status, equipmentSwitch, switchStyle, inventoryGroup);
  }

  public boolean hasItemId() {
    return itemId > 0;
  }

  public boolean isBanked() {
    return status == Status.BANK;
  }
}

package com.slayerplus;

import java.util.*;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;

public final class SlayerBossInventoryCatalog {
  public static final String REVIEW_DATE = "2026-08-13";
  private static final int DEFINITION_COLUMN_COUNT = 19;
  private static final int MAPPING_COLUMN_COUNT = 3;
  private static final int RECORD_TYPE = 0;
  private static final int POLICY_NAME = 1;
  private static final int TARGET_SLOTS = 2;
  private static final int RESTORE_SLOTS = 3;
  private static final int FOOD_SLOTS = 4;
  private static final int LOOT_SLOTS = 5;
  private static final int INCLUDE_STYLE_BOOST = 6;
  private static final int INCLUDE_MAGIC_POUCH = 7;
  private static final int LAYOUT_PROFILE = 8;
  private static final int RESTORE_NAME = 9;
  private static final int RESTORE_FALLBACK = 10;
  private static final int FOOD_NAME = 11;
  private static final int FOOD_ALTERNATIVES = 12;
  private static final int SPELLBOOK = 13;
  private static final int SPELL_NAME = 14;
  private static final int INCLUDE_RUNE_POUCH = 15;
  private static final int FILL_POLICY = 16;
  private static final int RUNE_REQUIREMENTS = 17;
  private static final int REQUIRED_ITEMS = 18;
  private static final int ENCOUNTER_NAME = 1;
  private static final int MAPPED_POLICY_NAME = 2;
  private static final Map<String, Policy> POLICIES = loadPolicies();
  private static final Set<String> REVIEWED_BOSS_KEYS = reviewedKeys();

  private SlayerBossInventoryCatalog() {}

  public static Set<String> getReviewedBossKeys() {
    return REVIEWED_BOSS_KEYS;
  }

  public static boolean apply(String assignment, MethodRules.Builder rules, TaskStrategy strategy) {
    String task = canonicalBossKey(assignment);
    if (rules == null || !REVIEWED_BOSS_KEYS.contains(task)) {
      return false;
    }
    Policy policy = POLICIES.get(policyKey(task, strategy));
    if (policy == null) {
      policy = POLICIES.get(task);
    }
    if (policy == null) {
      return false;
    }
    policy.apply(rules);
    return true;
  }

  private static String policyKey(String task, TaskStrategy strategy) {
    if (strategy == null) {
      return task;
    }
    TaskStrategy.CombatStyle style = strategy.getStyle();
    if ((task.equals("k ril tsutsaroth") || task.equals("general graardor"))
        && style == TaskStrategy.CombatStyle.RANGED) {
      return task + "#ranged";
    }
    if (task.equals("kalphite queen") && style == TaskStrategy.CombatStyle.MAGIC) {
      return task + "#magic";
    }
    if (task.equals("vorkath") && style == TaskStrategy.CombatStyle.MELEE) {
      return task + "#melee";
    }
    if (task.equals("tzkal zuk")) {
      String method = normalize(strategy.getMethod());
      if (method.contains("not afk") || method.contains("completion first")) {
        return task + "#safety";
      }
      if (strategy.getCostPolicy() == TaskStrategy.CostPolicy.EFFICIENT) {
        return task + "#efficient";
      }
    }
    return task;
  }

  public static String canonicalBossKey(String value) {
    String key = normalize(value);
    if (key.equals("cave kraken boss")) {
      return "kraken";
    }
    if (key.equals("crazy archaeologists")) {
      return "crazy archaeologist";
    }
    return key;
  }

  private static Map<String, Policy> loadPolicies() {
    Map<String, Policy> definitions = new LinkedHashMap<>();
    Map<String, Policy> policies = new LinkedHashMap<>();
    List<String[]> rows =
        ResourceTable.rows(
            "slayer-boss-inventory.tsv", MAPPING_COLUMN_COUNT, DEFINITION_COLUMN_COUNT);
    for (int row = 0; row < rows.size(); row++) {
      String[] fields = rows.get(row);
      int lineNumber = row + 1;
      if (fields.length == DEFINITION_COLUMN_COUNT && fields[RECORD_TYPE].equals("D")) {
        definitions.put(fields[POLICY_NAME], Policy.parse(fields, lineNumber));
        continue;
      }
      if (fields.length == MAPPING_COLUMN_COUNT && fields[RECORD_TYPE].equals("P")) {
        Policy policy = definitions.get(fields[MAPPED_POLICY_NAME]);
        if (policy == null)
          throw new IllegalStateException(
              "Unknown boss policy " + fields[MAPPED_POLICY_NAME] + " at row " + lineNumber);
        policies.put(restoreEscapedDelimiters(fields[ENCOUNTER_NAME]), policy);
        continue;
      }
      throw new IllegalStateException("Invalid boss policy row " + lineNumber);
    }
    return Collections.unmodifiableMap(policies);
  }

  private static Set<String> reviewedKeys() {
    Set<String> keys = new LinkedHashSet<>();
    for (String key : POLICIES.keySet()) {
      int separator = key.indexOf('#');
      keys.add(key.substring(0, separator < 0 ? key.length() : separator));
    }
    return Collections.unmodifiableSet(keys);
  }

  private static String normalize(String value) {
    return SlayerText.encounter(value);
  }

  private static String restoreEscapedDelimiters(String escapedText) {
    if (escapedText == null || escapedText.indexOf('\\') < 0) {
      return escapedText;
    }
    StringBuilder value = new StringBuilder(escapedText.length());
    boolean escaped = false;
    for (int index = 0; index < escapedText.length(); index++) {
      char character = escapedText.charAt(index);
      if (!escaped && character == '\\') {
        escaped = true;
        continue;
      }
      if (escaped) {
        switch (character) {
          case 't':
            value.append('\t');
            break;
          case 'r':
            value.append('\r');
            break;
          case 'n':
            value.append('\n');
            break;
          case 'p':
            value.append('|');
            break;
          case 'c':
            value.append(',');
            break;
          case 's':
            value.append(';');
            break;
          default:
            value.append(character);
            break;
        }
        escaped = false;
      } else {
        value.append(character);
      }
    }
    if (escaped) {
      value.append('\\');
    }
    return value.toString();
  }

  private static String[] splitList(String escapedText) {
    if (!hasValue(escapedText)) {
      return new String[0];
    }
    String[] values = escapedText.split(";", -1);
    for (int index = 0; index < values.length; index++) {
      values[index] = restoreEscapedDelimiters(values[index]);
    }
    return values;
  }

  private static boolean hasValue(String value) {
    return value != null && !value.isEmpty() && !value.equals("-");
  }

  private static final class Policy {
    private int target;
    private Integer restoreSlots;
    private Integer meals;
    private int loot;
    private boolean styleBoost;
    private boolean magicPouch;
    private MethodRules.LayoutProfile layout;
    private String restore;
    private String restoreFallback;
    private String food;
    private String[] foodAlternatives;
    private MethodRules.Spellbook spellbook;
    private String spell;
    private boolean runePouch;
    private String fill;
    private final List<Rune> runes = new ArrayList<>();
    private final List<Required> required = new ArrayList<>();

    private static Policy parse(String[] fields, int lineNumber) {
      try {
        Policy policy = new Policy();
        policy.target = Integer.parseInt(fields[TARGET_SLOTS]);
        policy.restoreSlots =
            fields[RESTORE_SLOTS].isEmpty() ? null : Integer.valueOf(fields[RESTORE_SLOTS]);
        policy.meals = fields[FOOD_SLOTS].isEmpty() ? null : Integer.valueOf(fields[FOOD_SLOTS]);
        policy.loot = Integer.parseInt(fields[LOOT_SLOTS]);
        policy.styleBoost = Boolean.parseBoolean(fields[INCLUDE_STYLE_BOOST]);
        policy.magicPouch = Boolean.parseBoolean(fields[INCLUDE_MAGIC_POUCH]);
        policy.layout = MethodRules.LayoutProfile.valueOf(fields[LAYOUT_PROFILE]);
        policy.restore = restoreEscapedDelimiters(fields[RESTORE_NAME]);
        policy.restoreFallback = restoreEscapedDelimiters(fields[RESTORE_FALLBACK]);
        policy.food = restoreEscapedDelimiters(fields[FOOD_NAME]);
        policy.foodAlternatives = splitList(fields[FOOD_ALTERNATIVES]);
        policy.spellbook = MethodRules.Spellbook.valueOf(fields[SPELLBOOK]);
        policy.spell = restoreEscapedDelimiters(fields[SPELL_NAME]);
        policy.runePouch = Boolean.parseBoolean(fields[INCLUDE_RUNE_POUCH]);
        policy.fill = fields[FILL_POLICY];
        if (hasValue(fields[RUNE_REQUIREMENTS])) {
          for (String value : fields[RUNE_REQUIREMENTS].split(";")) {
            String[] rune = value.split(",", -1);
            policy.runes.add(
                new Rune(
                    Integer.parseInt(rune[0]),
                    restoreEscapedDelimiters(rune[1]),
                    Integer.parseInt(rune[2])));
          }
        }
        if (hasValue(fields[REQUIRED_ITEMS])) {
          for (String value : fields[REQUIRED_ITEMS].split("\\|")) {
            String[] item = value.split(",", -1);
            policy.required.add(
                new Required(
                    restoreEscapedDelimiters(item[0]),
                    Integer.parseInt(item[1]),
                    Integer.parseInt(item[2]),
                    ("RUNES".equals(item[3]) || "RUNES_AMMO".equals(item[3]))
                        ? MethodRules.InventoryGroup.RUNES
                        : MethodRules.InventoryGroup.valueOf(item[3]),
                    Boolean.parseBoolean(item[4]),
                    splitList(item[5])));
          }
        }
        return policy;
      } catch (RuntimeException ex) {
        throw new IllegalStateException("Invalid boss inventory policy at row " + lineNumber, ex);
      }
    }

    private void apply(MethodRules.Builder rules) {
      rules
          .inventoryTarget(target)
          .noInventoryFill()
          .includeRunePouchForMagic(magicPouch)
          .includeStyleBoost(styleBoost)
          .loot(loot)
          .layout(layout)
          .food(food, foodAlternatives);
      if (restoreSlots != null) {
        rules.restoreSlots(restoreSlots);
      }
      if (meals != null) {
        rules.food(meals);
      }
      if (!restore.isEmpty()) {
        rules.restore(restore, restoreFallback);
        if (restoreFallback.isEmpty()) {
          rules.noRestoreFallback();
        }
      }
      if (spellbook != MethodRules.Spellbook.STRATEGY_DEFINED) {
        rules.spell(spellbook, spell);
      }
      rules.runePouch(runePouch);
      for (Rune rune : runes) {
        rules.pouchRune(rune.id, rune.name, rune.quantity);
      }
      for (Required item : required) {
        item.apply(rules);
      }
      if (fill.equals("FOOD")) {
        rules.fillFood();
      } else if (fill.equals("RESTORE")) {
        rules.fillRestore();
      }
    }
  }

  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  private static final class Rune {
    private final int id;
    private final String name;
    private final int quantity;
  }

  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  private static final class Required {
    private final String name;
    private final int quantity;
    private final int slots;
    private final MethodRules.InventoryGroup group;
    private final boolean ownedOnly;
    private final String[] alternatives;

    private void apply(MethodRules.Builder rules) {
      if (ownedOnly) {
        rules.ownedOnlyItem(name, quantity, group, alternatives);
      } else if (slots > 1) {
        rules.requiredSlots(name, slots, group, alternatives);
      } else {
        rules.require(name, quantity, group, alternatives);
      }
    }
  }
}

package com.slayerplus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class SlayerTaskReadinessOverlay extends OverlayPanel {
  private static final Color READY = new Color(74, 214, 126);
  private static final Color WARNING = new Color(255, 171, 64);
  private static final Color MISSING = new Color(255, 92, 92);
  private static final Color MUTED = new Color(190, 190, 190);
  private String renderedFingerprint = "";
  private boolean rowsVisible;

  @Inject
  SlayerTaskReadinessOverlay(SlayerPlusPlugin plugin) {
    super(plugin);
    setPosition(OverlayPosition.TOP_RIGHT);
    setPriority(PRIORITY_HIGH);
    setLayer(OverlayLayer.ABOVE_SCENE);
    setResizable(false);
    setClearChildren(false);
    panelComponent.setPreferredSize(new Dimension(240, 0));
  }

  void update(PreparationCatalog.PreparationPlan plan) {
    boolean setupRequired = plan != null && plan.isActive() && !plan.isReady();
    if (!setupRequired) {
      clearRows();
      return;
    }
    String fingerprint = renderFingerprint(plan);
    if (rowsVisible && fingerprint.equals(renderedFingerprint)) {
      return;
    }
    panelComponent.getChildren().clear();
    renderedFingerprint = fingerprint;
    rowsVisible = true;
    panelComponent
        .getChildren()
        .add(
            TitleComponent.builder()
                .text("Slayer setup required")
                .color(WARNING)
                .build());
    panelComponent
        .getChildren()
        .add(
            LineComponent.builder()
                .left(plan.spellbookName().isEmpty() ? "Spellbook" : plan.spellbookName())
                .right(plan.isSpellbookReady() ? "Ready" : "Switch")
                .rightColor(plan.isSpellbookReady() ? READY : MISSING)
                .build());
    if (!plan.getRequiredItemName().isEmpty()) {
      panelComponent
          .getChildren()
          .add(
              LineComponent.builder()
                  .left(plan.getRequiredItemName())
                  .leftColor(MUTED)
                  .right(plan.isRequiredItemReady() ? "Ready" : "Missing")
                  .rightColor(plan.isRequiredItemReady() ? READY : MISSING)
                  .build());
    }
    if (!plan.getSpellName().isEmpty()) {
      for (String spell : plan.getSpellName().split("\\s*\\+\\s*")) {
        panelComponent
            .getChildren()
            .add(LineComponent.builder().left("Spell: " + spell).leftColor(MUTED).build());
      }
    }
    if (!plan.isLevelReady()) {
      panelComponent
          .getChildren()
          .add(
              LineComponent.builder()
                  .left("Magic level")
                  .right(plan.getMagicLevel() + " / " + plan.getRequiredMagicLevel())
                  .rightColor(MISSING)
                  .build());
    }
    for (PreparationCatalog.RuneStatus rune : plan.getRuneStatuses()) {
      boolean runeReady = rune.isReady();
      panelComponent
          .getChildren()
          .add(
              LineComponent.builder()
                  .left(rune.getName() + " runes")
                  .leftColor(MUTED)
                  .right(rune.getAvailable() + " / " + rune.getRequired())
                  .rightColor(runeReady ? READY : MISSING)
                  .build());
    }
    if (plan.getCastsAvailable() > 0) {
      panelComponent
          .getChildren()
          .add(
              LineComponent.builder()
                  .left("Casts available")
                  .right(Integer.toString(plan.getCastsAvailable()))
                  .rightColor(plan.isRunesReady() ? READY : MISSING)
                  .build());
    }
  }

  @Override
  public Dimension render(Graphics2D graphics) {
    return rowsVisible ? super.render(graphics) : null;
  }

  private void clearRows() {
    if (!rowsVisible) {
      return;
    }
    panelComponent.getChildren().clear();
    renderedFingerprint = "";
    rowsVisible = false;
  }

  static String renderFingerprint(PreparationCatalog.PreparationPlan plan) {
    if (plan == null || !plan.isActive() || plan.isReady()) {
      return "hidden";
    }
    StringBuilder value =
        new StringBuilder(128)
            .append(plan.spellbookName())
            .append('|')
            .append(plan.isSpellbookReady())
            .append('|')
            .append(plan.isLevelReady())
            .append('|')
            .append(plan.getMagicLevel())
            .append('|')
            .append(plan.getRequiredMagicLevel())
            .append('|')
            .append(plan.getRequiredItemName())
            .append('|')
            .append(plan.isRequiredItemReady())
            .append('|')
            .append(plan.getSpellName())
            .append('|')
            .append(plan.getCastsAvailable())
            .append('|')
            .append(plan.isRunesReady());
    for (PreparationCatalog.RuneStatus rune : plan.getRuneStatuses()) {
      value
          .append('|')
          .append(rune.getName())
          .append(':')
          .append(rune.getAvailable())
          .append('/')
          .append(rune.getRequired());
    }
    return value.toString();
  }
}

