package com.slayerplus;

import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Rasterizer;

@RequiredArgsConstructor
public final class PlayerPortraitRenderer {
  private static final int CAPTURE_SIZE = 320;
  private static final int OUTPUT_SIZE = 140;
  private static final int FRONT_YAW = 0;
  private static final double HEAD_TURN_RADIANS = Math.toRadians(7.0);
  private static final int NECK_SCAN_BINS = 72;
  private static final int CLEAR_RGB = 0x010203;
  private static final int EXTENDED_CAPTURE_EXTRA = 640;
  private static final int SIDE_SOURCE_EXTENSION_COLUMNS = 32;
  private static final int TOP_SOURCE_EXTENSION_ROWS = 64;
  private static final int[] ZOOM_LEVELS = {120, 145, 170, 200, 230, 260, 300, 340, 380};
  private final Client client;
  private Framing lockedFraming;
  private ContentBounds lockedContentBounds;

  public BufferedImage render(Model displayInputModel, Model bodyInputModel, int turnDirection) {
    if (displayInputModel == null || bodyInputModel == null) {
      return null;
    }
    boolean weaponEquipped = displayInputModel != bodyInputModel;
    Model bodyUnskewed = bodyInputModel.getUnskewedModel();
    Model bodyModel = bodyUnskewed != null ? bodyUnskewed : bodyInputModel;
    Model displayModel = bodyModel;
    if (weaponEquipped) {
      Model displayUnskewed = displayInputModel.getUnskewedModel();
      displayModel = displayUnskewed != null ? displayUnskewed : displayInputModel;
    }
    Rasterizer rasterizer = client.getRasterizer();
    if (rasterizer == null) {
      return null;
    }
    int rasterWidth = rasterizer.getWidth();
    int rasterHeight = rasterizer.getHeight();
    int[] pixels = rasterizer.getPixels();
    if (pixels == null || rasterWidth < CAPTURE_SIZE || rasterHeight < CAPTURE_SIZE) {
      return null;
    }
    int captureX = (rasterWidth - CAPTURE_SIZE) / 2;
    int captureY = (rasterHeight - CAPTURE_SIZE) / 2;
    int extendedCaptureSize =
        Math.max(
            CAPTURE_SIZE,
            Math.min(CAPTURE_SIZE + EXTENDED_CAPTURE_EXTRA, Math.min(rasterWidth, rasterHeight)));
    int extendedCaptureX = (rasterWidth - extendedCaptureSize) / 2;
    int extendedCaptureY = (rasterHeight - extendedCaptureSize) / 2;
    int extendedOffsetX = captureX - extendedCaptureX;
    int extendedOffsetY = captureY - extendedCaptureY;
    int[] savedPixels =
        copyRegion(
            pixels,
            rasterWidth,
            extendedCaptureX,
            extendedCaptureY,
            extendedCaptureSize,
            extendedCaptureSize);
    try {
      rasterizer.setDrawRegion(
          captureX, captureY, captureX + CAPTURE_SIZE, captureY + CAPTURE_SIZE);
      bodyModel.calculateBoundsCylinder();
      if (weaponEquipped) {
        displayModel.calculateBoundsCylinder();
      }
      if (lockedFraming == null) {
        lockedFraming =
            findInitialFraming(bodyModel, rasterizer, pixels, rasterWidth, captureX, captureY);
      }
      if (lockedFraming == null) {
        return null;
      }
      if (lockedContentBounds == null) {
        var calibrationCapture =
            renderCaptureSized(
                bodyModel,
                rasterizer,
                pixels,
                rasterWidth,
                captureX,
                captureY,
                CAPTURE_SIZE,
                lockedFraming);
        var calibrationPortrait =
            copyLockedCrop(calibrationCapture, lockedFraming, true, 0, 0, 1);
        if (calibrationPortrait == null) {
          return null;
        }
      }
      int renderScale = extendedCaptureSize / CAPTURE_SIZE;
      Framing renderFraming =
          renderScale == 1
              ? lockedFraming
              : supersampledFraming(
                  lockedFraming, lockedContentBounds, client.get3dZoom(), renderScale);
      NeckTurn neckTurn = applyTemporaryNeckTurn(displayModel, bodyModel, turnDirection);
      try {
        var capture =
            renderCaptureSized(
                displayModel,
                rasterizer,
                pixels,
                rasterWidth,
                extendedCaptureX,
                extendedCaptureY,
                extendedCaptureSize,
                renderFraming);
        return copyLockedCrop(
            capture,
            lockedFraming,
            false,
            extendedOffsetX,
            extendedOffsetY,
            renderScale);
      } finally {
        if (neckTurn != null) {
          neckTurn.restore();
        }
      }
    } finally {
      try {
        restoreRegion(
            pixels,
            rasterWidth,
            extendedCaptureX,
            extendedCaptureY,
            extendedCaptureSize,
            extendedCaptureSize,
            savedPixels);
      } finally {
        rasterizer.resetRasterClipping();
      }
    }
  }

  private static BufferedImage renderCaptureSized(
      Model model,
      Rasterizer rasterizer,
      int[] pixels,
      int rasterWidth,
      int captureX,
      int captureY,
      int captureSize,
      Framing framing) {
    rasterizer.setDrawRegion(captureX, captureY, captureX + captureSize, captureY + captureSize);
    rasterizer.fillRectangle(captureX, captureY, captureSize, captureSize, CLEAR_RGB);
    model.drawOrtho(0, 0, FRONT_YAW, 0, 0, framing.verticalOffset, 0, framing.zoom);
    return captureRegion(pixels, rasterWidth, captureX, captureY, captureSize, captureSize);
  }

  private static Framing supersampledFraming(
      Framing framing, ContentBounds bounds, int projectionZoom, int renderScale) {
    double contentCenter = framing.cropY + (bounds.minY + bounds.maxY + 1) / 2.0;
    int verticalOffset = framing.verticalOffset;
    if (projectionZoom > 0) {
      verticalOffset +=
          (int)
              Math.round(
                  (CAPTURE_SIZE / 2.0 - contentCenter) * framing.zoom / projectionZoom);
    }
    return new Framing(
        Math.max(1, framing.zoom / renderScale),
        verticalOffset,
        framing.cropX,
        framing.cropY,
        framing.cropWidth,
        framing.cropHeight);
  }

  public boolean hasCalibration() {
    return lockedFraming != null && lockedContentBounds != null;
  }

  public String exportCalibration() {
    if (!hasCalibration()) {
      return null;
    }
    return String.format(
        "v2,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d",
        lockedFraming.zoom,
        lockedFraming.verticalOffset,
        lockedFraming.cropX,
        lockedFraming.cropY,
        lockedFraming.cropWidth,
        lockedFraming.cropHeight,
        lockedContentBounds.minX,
        lockedContentBounds.minY,
        lockedContentBounds.maxX,
        lockedContentBounds.maxY);
  }

  public boolean loadCalibration(String value) {
    if (value == null || value.trim().isEmpty()) {
      return false;
    }
    String[] parts = value.split(",");
    if (parts.length != 11 || !"v2".equals(parts[0])) {
      return false;
    }
    try {
      int[] values = new int[10];
      for (int index = 0; index < values.length; index++) {
        values[index] = Integer.parseInt(parts[index + 1]);
      }
      int zoom = values[0];
      int cropX = values[2];
      int cropY = values[3];
      int cropWidth = values[4];
      int cropHeight = values[5];
      if (zoom <= 0
          || cropWidth <= 0
          || cropHeight <= 0
          || cropX < 0
          || cropY < 0
          || cropX + cropWidth > CAPTURE_SIZE
          || cropY + cropHeight > CAPTURE_SIZE
          || values[6] < 0
          || values[7] < 0
          || values[8] < values[6]
          || values[9] < values[7]
          || values[8] >= cropWidth
          || values[9] >= cropHeight) {
        return false;
      }
      lockedFraming = new Framing(zoom, values[1], cropX, cropY, cropWidth, cropHeight);
      lockedContentBounds = new ContentBounds(values[6], values[7], values[8], values[9]);
      return true;
    } catch (NumberFormatException exception) {
      return false;
    }
  }

  private static Framing findInitialFraming(
      Model model,
      Rasterizer rasterizer,
      int[] pixels,
      int rasterWidth,
      int captureX,
      int captureY) {
    int modelHeight = Math.max(1, model.getModelHeight());
    int[] verticalOffsets = {
      -modelHeight,
      -(modelHeight * 3 / 4),
      -(modelHeight / 2),
      -(modelHeight / 4),
      0,
      modelHeight / 4,
      modelHeight / 2,
      modelHeight * 3 / 4,
      modelHeight
    };
    Candidate best = null;
    for (int zoom : ZOOM_LEVELS) {
      for (int verticalOffset : verticalOffsets) {
        rasterizer.fillRectangle(captureX, captureY, CAPTURE_SIZE, CAPTURE_SIZE, CLEAR_RGB);
        model.drawOrtho(0, 0, FRONT_YAW, 0, 0, verticalOffset, 0, zoom);
        Candidate candidate =
            measure(pixels, rasterWidth, captureX, captureY, zoom, verticalOffset);
        if (candidate != null && (best == null || candidate.score > best.score)) {
          best = candidate;
        }
      }
    }
    if (best == null) {
      return null;
    }
    int fullWidth = best.maxX - best.minX + 1;
    int centerX = best.minX + fullWidth / 2;
    Framing bestFraming = new Framing(best.zoom, best.verticalOffset, 0, 0, 1, 1);
    BufferedImage bestCapture =
        renderCaptureSized(
            model,
            rasterizer,
            pixels,
            rasterWidth,
            captureX,
            captureY,
            CAPTURE_SIZE,
            bestFraming);
    int cropHeight = findHeadAndShoulderHeight(bestCapture, best.minY, best.maxY, fullWidth);
    int widestUpperBody =
        findMaximumRowWidth(
            bestCapture, best.minY, Math.min(best.maxY, best.minY + cropHeight - 1));
    int cropWidth =
        Math.min(
            CAPTURE_SIZE,
            Math.max(96, Math.max(widestUpperBody + 8, (int) Math.round(cropHeight * 1.08))));
    int headwearTopPadding = 24;
    int finalCropHeight = Math.min(CAPTURE_SIZE, cropHeight + headwearTopPadding);
    int cropX = clamp(centerX - cropWidth / 2, 0, CAPTURE_SIZE - cropWidth);
    int cropY = clamp(best.minY - headwearTopPadding, 0, CAPTURE_SIZE - finalCropHeight);
    return new Framing(best.zoom, best.verticalOffset, cropX, cropY, cropWidth, finalCropHeight);
  }

  private static int findHeadAndShoulderHeight(
      BufferedImage image, int minY, int maxY, int fullWidth) {
    int fullHeight = maxY - minY + 1;
    int[] widths = new int[fullHeight];
    for (int offset = 0; offset < fullHeight; offset++) {
      widths[offset] = rowWidth(image, minY + offset);
    }
    int[] smoothed = new int[fullHeight];
    for (int i = 0; i < fullHeight; i++) {
      int total = 0;
      int count = 0;
      for (int sample = Math.max(0, i - 2); sample <= Math.min(fullHeight - 1, i + 2); sample++) {
        if (widths[sample] > 0) {
          total += widths[sample];
          count++;
        }
      }
      smoothed[i] = count == 0 ? 0 : total / count;
    }
    int searchStart = Math.max(1, (int) Math.round(fullHeight * 0.18));
    int searchEnd = Math.min(fullHeight - 1, (int) Math.round(fullHeight * 0.58));
    int neckOffset = -1;
    int neckWidth = Integer.MAX_VALUE;
    int minimumMeaningfulWidth = Math.max(6, fullWidth / 12);
    for (int i = searchStart; i <= searchEnd; i++) {
      int width = smoothed[i];
      if (width >= minimumMeaningfulWidth && width < neckWidth) {
        neckWidth = width;
        neckOffset = i;
      }
    }
    if (neckOffset >= 0) {
      int shoulderSearchEnd = Math.min(fullHeight - 1, neckOffset + Math.max(12, fullHeight / 7));
      int shoulderThreshold = Math.max(neckWidth + 12, (int) Math.round(neckWidth * 1.45));
      for (int i = neckOffset + 1; i <= shoulderSearchEnd; i++) {
        if (smoothed[i] >= shoulderThreshold) {
          int bottomPadding = Math.max(3, fullHeight / 45);
          return clamp(i + bottomPadding, 64, fullHeight);
        }
      }
    }
    return clamp((int) Math.round(fullHeight * 0.34), 72, fullHeight);
  }

  private static int findMaximumRowWidth(BufferedImage image, int startY, int endY) {
    int maximum = 0;
    for (int y = startY; y <= endY; y++) {
      maximum = Math.max(maximum, rowWidth(image, y));
    }
    return maximum;
  }

  private static int rowWidth(BufferedImage image, int y) {
    if (y < 0 || y >= image.getHeight()) {
      return 0;
    }
    int minimumX = image.getWidth();
    int maximumX = -1;
    for (int x = 0; x < image.getWidth(); x++) {
      int rgb = image.getRGB(x, y) & 0x00FFFFFF;
      if (rgb == CLEAR_RGB) {
        continue;
      }
      minimumX = Math.min(minimumX, x);
      maximumX = Math.max(maximumX, x);
    }
    return maximumX < minimumX ? 0 : maximumX - minimumX + 1;
  }

  private static Candidate measure(
      int[] pixels,
      int rasterWidth,
      int captureX,
      int captureY,
      int zoom,
      int verticalOffset) {
    int minX = CAPTURE_SIZE;
    int minY = CAPTURE_SIZE;
    int maxX = -1;
    int maxY = -1;
    int pixelCount = 0;
    for (int y = 0; y < CAPTURE_SIZE; y++) {
      int row = (captureY + y) * rasterWidth + captureX;
      for (int x = 0; x < CAPTURE_SIZE; x++) {
        int rgb = pixels[row + x] & 0x00FFFFFF;
        if (rgb == CLEAR_RGB) {
          continue;
        }
        pixelCount++;
        minX = Math.min(minX, x);
        minY = Math.min(minY, y);
        maxX = Math.max(maxX, x);
        maxY = Math.max(maxY, y);
      }
    }
    if (pixelCount == 0 || maxX < minX || maxY < minY) {
      return null;
    }
    int fullWidth = maxX - minX + 1;
    int fullHeight = maxY - minY + 1;
    int portraitHeight = Math.max(1, (int) Math.round(fullHeight * 0.20));
    int portraitWidth =
        Math.max(
            1,
            Math.min((int) Math.round(fullWidth * 0.62), (int) Math.round(portraitHeight * 1.04)));
    int score = 200000;
    score -= Math.abs(portraitHeight - 88) * 1800;
    score -= Math.abs(portraitWidth - 92) * 1400;
    if (minY <= 12
        || maxY >= CAPTURE_SIZE - 13
        || minX <= 12
        || maxX >= CAPTURE_SIZE - 13) {
      return null;
    }
    return new Candidate(minX, minY, maxX, maxY, zoom, verticalOffset, score);
  }

  private BufferedImage copyLockedCrop(
      BufferedImage capture,
      Framing framing,
      boolean allowCalibration,
      int captureOffsetX,
      int captureOffsetY,
      int renderScale) {
    int requestedTopExtension = allowCalibration ? 0 : TOP_SOURCE_EXTENSION_ROWS;
    int sideExtension = allowCalibration ? 0 : SIDE_SOURCE_EXTENSION_COLUMNS;
    int availableTopExtension =
        renderScale == 1
            ? Math.max(0, captureOffsetY + framing.cropY)
            : requestedTopExtension;
    int sourceTopExtension = Math.min(requestedTopExtension, availableTopExtension);
    var source =
        new BufferedImage(
            (framing.cropWidth + sideExtension * 2) * renderScale,
            (framing.cropHeight + sourceTopExtension) * renderScale,
            BufferedImage.TYPE_INT_ARGB_PRE);
    int sourceOriginX;
    int sourceOriginY;
    if (renderScale == 1) {
      sourceOriginX = captureOffsetX + framing.cropX - sideExtension;
      sourceOriginY = captureOffsetY + framing.cropY - sourceTopExtension;
    } else {
      double contentCenter =
          framing.cropY
              + (lockedContentBounds.minY + lockedContentBounds.maxY + 1) / 2.0;
      sourceOriginX =
          (int)
              Math.round(
                  capture.getWidth() / 2.0
                      + (framing.cropX - sideExtension - CAPTURE_SIZE / 2.0) * renderScale);
      sourceOriginY =
          (int)
              Math.round(
                  capture.getHeight() / 2.0
                      + (framing.cropY - sourceTopExtension - contentCenter) * renderScale);
    }
    for (int y = 0; y < source.getHeight(); y++) {
      for (int x = 0; x < source.getWidth(); x++) {
        int sourceX = sourceOriginX + x;
        int sourceY = sourceOriginY + y;
        if (sourceX < 0
            || sourceX >= capture.getWidth()
            || sourceY < 0
            || sourceY >= capture.getHeight()) {
          continue;
        }
        int rgb = capture.getRGB(sourceX, sourceY) & 0x00FFFFFF;
        if (rgb != CLEAR_RGB) {
          source.setRGB(x, y, 0xFF000000 | rgb);
        }
      }
    }
    if (lockedContentBounds == null) {
      if (!allowCalibration) {
        return null;
      }
      int measuredMinX = source.getWidth();
      int measuredMinY = source.getHeight();
      int measuredMaxX = -1;
      int measuredMaxY = -1;
      for (int y = 0; y < source.getHeight(); y++) {
        for (int x = 0; x < source.getWidth(); x++) {
          if ((source.getRGB(x, y) >>> 24) == 0) {
            continue;
          }
          measuredMinX = Math.min(measuredMinX, x);
          measuredMinY = Math.min(measuredMinY, y);
          measuredMaxX = Math.max(measuredMaxX, x);
          measuredMaxY = Math.max(measuredMaxY, y);
        }
      }
      if (measuredMaxX < measuredMinX || measuredMaxY < measuredMinY) {
        return new BufferedImage(OUTPUT_SIZE, OUTPUT_SIZE, BufferedImage.TYPE_INT_ARGB);
      }
      int horizontalPadding = 3;
      int topPadding = 16;
      int bottomPadding = 1;
      lockedContentBounds =
          new ContentBounds(
              Math.max(0, measuredMinX - horizontalPadding),
              Math.max(0, measuredMinY - topPadding),
              Math.min(source.getWidth() - 1, measuredMaxX + horizontalPadding),
              Math.min(source.getHeight() - 1, measuredMaxY + bottomPadding));
    }
    int minX = (lockedContentBounds.minX + sideExtension) * renderScale;
    int minY = (lockedContentBounds.minY + sourceTopExtension) * renderScale;
    int maxX = (lockedContentBounds.maxX + sideExtension + 1) * renderScale - 1;
    int maxY = (lockedContentBounds.maxY + sourceTopExtension + 1) * renderScale - 1;
    if (!allowCalibration) {
      int[] horizontalBounds = horizontalOpaqueBounds(source);
      if (horizontalBounds != null) {
        minX = Math.min(minX, horizontalBounds[0]);
        maxX = Math.max(maxX, horizontalBounds[1]);
      }
    }
    int visibleWidth = maxX - minX + 1;
    int visibleHeight = maxY - minY + 1;
    int availableWidth = OUTPUT_SIZE - 4;
    int availableHeight = OUTPUT_SIZE - 3;
    double scale =
        Math.min((double) availableWidth / visibleWidth, (double) availableHeight / visibleHeight);
    int drawWidth = Math.max(1, (int) Math.round(visibleWidth * scale));
    int drawHeight = Math.max(1, (int) Math.round(visibleHeight * scale));
    int targetX = (OUTPUT_SIZE - drawWidth) / 2;
    int targetY = OUTPUT_SIZE - drawHeight;
    int availableTopSourceRows = Math.min(minY, Math.max(0, (int) Math.floor(targetY / scale)));
    int extendedMinY = minY - availableTopSourceRows;
    int extendedVisibleHeight = maxY - extendedMinY + 1;
    int extendedDrawHeight = Math.max(1, (int) Math.round(extendedVisibleHeight * scale));
    int extensionDrawHeight = extendedDrawHeight - drawHeight;
    int extendedTargetY = Math.max(0, targetY - extensionDrawHeight);
    var scaledPortrait =
        downsampleCrop(
            source,
            minX,
            extendedMinY,
            maxX + 1,
            maxY + 1,
            drawWidth,
            extendedDrawHeight);
    var output = new BufferedImage(OUTPUT_SIZE, OUTPUT_SIZE, BufferedImage.TYPE_INT_ARGB_PRE);
    var graphics = output.createGraphics();
    graphics.setRenderingHint(
        RenderingHints.KEY_ALPHA_INTERPOLATION, RenderingHints.VALUE_ALPHA_INTERPOLATION_QUALITY);
    graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
    graphics.drawImage(scaledPortrait, targetX, extendedTargetY, null);
    graphics.dispose();
    return output;
  }

  private static int[] horizontalOpaqueBounds(BufferedImage image) {
    int minimum = image.getWidth();
    int maximum = -1;
    for (int y = 0; y < image.getHeight(); y++) {
      for (int x = 0; x < image.getWidth(); x++) {
        if ((image.getRGB(x, y) >>> 24) != 0) {
          minimum = Math.min(minimum, x);
          maximum = Math.max(maximum, x);
        }
      }
    }
    return maximum < minimum ? null : new int[] {minimum, maximum};
  }

  private static BufferedImage downsampleCrop(
      BufferedImage source,
      int sourceX,
      int sourceY,
      int sourceMaxX,
      int sourceMaxY,
      int width,
      int height) {
    var intermediate =
        new BufferedImage(width * 2, height * 2, BufferedImage.TYPE_INT_ARGB_PRE);
    var graphics = intermediate.createGraphics();
    configureResampling(graphics);
    graphics.drawImage(
        source,
        0,
        0,
        intermediate.getWidth(),
        intermediate.getHeight(),
        sourceX,
        sourceY,
        sourceMaxX,
        sourceMaxY,
        null);
    graphics.dispose();

    var output = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB_PRE);
    graphics = output.createGraphics();
    configureResampling(graphics);
    graphics.drawImage(intermediate, 0, 0, width, height, null);
    graphics.dispose();
    return output;
  }

  private static void configureResampling(java.awt.Graphics2D graphics) {
    graphics.setRenderingHint(
        RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
    graphics.setRenderingHint(
        RenderingHints.KEY_ALPHA_INTERPOLATION, RenderingHints.VALUE_ALPHA_INTERPOLATION_QUALITY);
    graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
  }

  private static NeckTurn applyTemporaryNeckTurn(
      Model model, Model bodyModel, int turnDirection) {
    int vertexCount = model.getVerticesCount();
    float[] verticesX = model.getVerticesX();
    float[] verticesY = model.getVerticesY();
    float[] verticesZ = model.getVerticesZ();
    int bodyVertexCount = bodyModel.getVerticesCount();
    float[] bodyX = bodyModel.getVerticesX();
    float[] bodyY = bodyModel.getVerticesY();
    float[] bodyZ = bodyModel.getVerticesZ();
    if (vertexCount < 12
        || verticesX == null
        || verticesY == null
        || verticesZ == null
        || verticesX.length < vertexCount
        || verticesY.length < vertexCount
        || verticesZ.length < vertexCount
        || bodyVertexCount < 12
        || bodyX == null
        || bodyY == null
        || bodyZ == null
        || bodyX.length < bodyVertexCount
        || bodyY.length < bodyVertexCount
        || bodyZ.length < bodyVertexCount) {
      return null;
    }
    float minimumY = Float.POSITIVE_INFINITY;
    float maximumY = Float.NEGATIVE_INFINITY;
    float minimumX = Float.POSITIVE_INFINITY;
    float maximumX = Float.NEGATIVE_INFINITY;
    float minimumZ = Float.POSITIVE_INFINITY;
    float maximumZ = Float.NEGATIVE_INFINITY;
    for (int vertex = 0; vertex < bodyVertexCount; vertex++) {
      minimumY = Math.min(minimumY, bodyY[vertex]);
      maximumY = Math.max(maximumY, bodyY[vertex]);
      minimumX = Math.min(minimumX, bodyX[vertex]);
      maximumX = Math.max(maximumX, bodyX[vertex]);
      minimumZ = Math.min(minimumZ, bodyZ[vertex]);
      maximumZ = Math.max(maximumZ, bodyZ[vertex]);
    }
    float modelHeight = maximumY - minimumY;
    if (modelHeight < 20.0f) {
      return null;
    }
    float neckY = findNeckY(bodyX, bodyY, bodyZ, bodyVertexCount, minimumY, maximumY);
    float[] pivot =
        findNeckPivot(
            bodyX,
            bodyY,
            bodyZ,
            bodyVertexCount,
            neckY,
            modelHeight,
            minimumX,
            maximumX,
            minimumZ,
            maximumZ);
    float[] originalX = Arrays.copyOf(verticesX, vertexCount);
    float[] originalY = Arrays.copyOf(verticesY, vertexCount);
    float[] originalZ = Arrays.copyOf(verticesZ, vertexCount);
    Set<VertexKey> bodyVertices = null;
    if (model != bodyModel) {
      bodyVertices = new HashSet<>(bodyVertexCount * 2);
      for (int vertex = 0; vertex < bodyVertexCount; vertex++) {
        bodyVertices.add(new VertexKey(bodyX[vertex], bodyY[vertex], bodyZ[vertex]));
      }
    }
    double direction = turnDirection < 0 ? -1.0 : 1.0;
    float fullTurnY = neckY - Math.max(3.0f, modelHeight / 45.0f);
    float stationaryY = neckY + Math.max(7.0f, modelHeight / 18.0f);
    float transitionHeight = Math.max(1.0f, stationaryY - fullTurnY);
    for (int vertex = 0; vertex < vertexCount; vertex++) {
      double weight = turnWeight(originalY[vertex], fullTurnY, stationaryY, transitionHeight);
      if (weight <= 0.0) {
        continue;
      }
      if (bodyVertices != null
          && !bodyVertices.contains(
              new VertexKey(originalX[vertex], originalY[vertex], originalZ[vertex]))) {
        continue;
      }
      double angle = direction * HEAD_TURN_RADIANS * weight;
      double sine = Math.sin(angle);
      double cosine = Math.cos(angle);
      double relativeX = originalX[vertex] - pivot[0];
      double relativeZ = originalZ[vertex] - pivot[1];
      verticesX[vertex] = (float) (pivot[0] + relativeX * cosine + relativeZ * sine);
      verticesZ[vertex] = (float) (pivot[1] - relativeX * sine + relativeZ * cosine);
    }
    return new NeckTurn(
        verticesX, verticesY, verticesZ, originalX, originalY, originalZ, vertexCount);
  }

  private static double turnWeight(
      float vertexY, float fullTurnY, float stationaryY, float transitionHeight) {
    if (vertexY <= fullTurnY) {
      return 1.0;
    }
    if (vertexY >= stationaryY) {
      return 0.0;
    }
    double linear = (stationaryY - vertexY) / transitionHeight;
    return linear * linear * (3.0 - 2.0 * linear);
  }

  private static float findNeckY(
      float[] verticesX,
      float[] verticesY,
      float[] verticesZ,
      int vertexCount,
      float minimumY,
      float maximumY) {
    double[] widths = modelWidths(verticesX, verticesY, verticesZ, vertexCount, minimumY, maximumY);
    double[] smoothed = smoothWidths(widths);
    int searchStart = (int) Math.round(NECK_SCAN_BINS * 0.22);
    int searchEnd = (int) Math.round(NECK_SCAN_BINS * 0.68);
    int bestBin = -1;
    double bestScore = Double.POSITIVE_INFINITY;
    for (int bin = searchStart; bin <= searchEnd; bin++) {
      double width = smoothed[bin];
      if (Double.isNaN(width) || width < 8.0) {
        continue;
      }
      double widestBelow = width;
      for (int lower = bin + 2; lower <= Math.min(NECK_SCAN_BINS - 1, bin + 11); lower++) {
        if (!Double.isNaN(smoothed[lower])) {
          widestBelow = Math.max(widestBelow, smoothed[lower]);
        }
      }
      if (widestBelow < width * 1.28 + 5.0) {
        continue;
      }
      double position = (bin + 0.5) / NECK_SCAN_BINS;
      double score = width + Math.abs(position - 0.48) * 28.0 - (widestBelow - width) * 0.16;
      if (score < bestScore) {
        bestScore = score;
        bestBin = bin;
      }
    }
    float modelHeight = maximumY - minimumY;
    return bestBin < 0
        ? minimumY + modelHeight * 0.48f
        : minimumY + (float) ((bestBin + 0.5) * modelHeight / NECK_SCAN_BINS);
  }

  private static double[] modelWidths(
      float[] verticesX,
      float[] verticesY,
      float[] verticesZ,
      int vertexCount,
      float minimumY,
      float maximumY) {
    float[] minimumX = new float[NECK_SCAN_BINS];
    float[] maximumX = new float[NECK_SCAN_BINS];
    float[] minimumZ = new float[NECK_SCAN_BINS];
    float[] maximumZ = new float[NECK_SCAN_BINS];
    int[] counts = new int[NECK_SCAN_BINS];
    Arrays.fill(minimumX, Float.POSITIVE_INFINITY);
    Arrays.fill(maximumX, Float.NEGATIVE_INFINITY);
    Arrays.fill(minimumZ, Float.POSITIVE_INFINITY);
    Arrays.fill(maximumZ, Float.NEGATIVE_INFINITY);
    float modelHeight = Math.max(1.0f, maximumY - minimumY);
    for (int vertex = 0; vertex < vertexCount; vertex++) {
      int bin =
          clamp(
              (int) ((verticesY[vertex] - minimumY) * NECK_SCAN_BINS / (modelHeight + 1.0f)),
              0,
              NECK_SCAN_BINS - 1);
      minimumX[bin] = Math.min(minimumX[bin], verticesX[vertex]);
      maximumX[bin] = Math.max(maximumX[bin], verticesX[vertex]);
      minimumZ[bin] = Math.min(minimumZ[bin], verticesZ[vertex]);
      maximumZ[bin] = Math.max(maximumZ[bin], verticesZ[vertex]);
      counts[bin]++;
    }
    double[] widths = new double[NECK_SCAN_BINS];
    for (int bin = 0; bin < NECK_SCAN_BINS; bin++) {
      widths[bin] =
          counts[bin] < 2
              ? Double.NaN
              : Math.max(maximumX[bin] - minimumX[bin], maximumZ[bin] - minimumZ[bin]);
    }
    return widths;
  }

  private static double[] smoothWidths(double[] widths) {
    double[] smoothed = new double[NECK_SCAN_BINS];
    for (int bin = 0; bin < NECK_SCAN_BINS; bin++) {
      double total = 0.0;
      int samples = 0;
      for (int sample = Math.max(0, bin - 2);
          sample <= Math.min(NECK_SCAN_BINS - 1, bin + 2);
          sample++) {
        if (!Double.isNaN(widths[sample])) {
          total += widths[sample];
          samples++;
        }
      }
      smoothed[bin] = samples == 0 ? Double.NaN : total / samples;
    }
    return smoothed;
  }

  private static float[] findNeckPivot(
      float[] verticesX,
      float[] verticesY,
      float[] verticesZ,
      int vertexCount,
      float neckY,
      float modelHeight,
      float minimumX,
      float maximumX,
      float minimumZ,
      float maximumZ) {
    float defaultX = (minimumX + maximumX) / 2.0f;
    float defaultZ = (minimumZ + maximumZ) / 2.0f;
    float xLimit = Math.max(8.0f, (maximumX - minimumX) * 0.35f);
    float zLimit = Math.max(8.0f, (maximumZ - minimumZ) * 0.35f);
    float neckBand = Math.max(4.0f, modelHeight / 25.0f);
    double totalX = 0.0;
    double totalZ = 0.0;
    int samples = 0;
    for (int vertex = 0; vertex < vertexCount; vertex++) {
      if (Math.abs(verticesY[vertex] - neckY) > neckBand
          || Math.abs(verticesX[vertex] - defaultX) > xLimit
          || Math.abs(verticesZ[vertex] - defaultZ) > zLimit) {
        continue;
      }
      totalX += verticesX[vertex];
      totalZ += verticesZ[vertex];
      samples++;
    }
    return samples < 3
        ? new float[] {defaultX, defaultZ}
        : new float[] {(float) (totalX / samples), (float) (totalZ / samples)};
  }

  private static int clamp(int value, int minimum, int maximum) {
    if (maximum < minimum) {
      return minimum;
    }
    return Math.max(minimum, Math.min(maximum, value));
  }

  private static int[] copyRegion(
      int[] pixels, int rasterWidth, int x, int y, int width, int height) {
    int[] copy = new int[width * height];
    for (int row = 0; row < height; row++) {
      System.arraycopy(pixels, (y + row) * rasterWidth + x, copy, row * width, width);
    }
    return copy;
  }

  private static void restoreRegion(
      int[] pixels, int rasterWidth, int x, int y, int width, int height, int[] savedPixels) {
    for (int row = 0; row < height; row++) {
      System.arraycopy(savedPixels, row * width, pixels, (y + row) * rasterWidth + x, width);
    }
  }

  private static BufferedImage captureRegion(
      int[] pixels, int rasterWidth, int x, int y, int width, int height) {
    var image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
    for (int row = 0; row < height; row++) {
      for (int column = 0; column < width; column++) {
        int rgb = pixels[(y + row) * rasterWidth + x + column] & 0x00FFFFFF;
        image.setRGB(column, row, 0xFF000000 | rgb);
      }
    }
    return image;
  }

  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  private static final class ContentBounds {
    private final int minX;
    private final int minY;
    private final int maxX;
    private final int maxY;
  }

  @Value
  private static class VertexKey {
    float x;
    float y;
    float z;
  }

  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  private static final class NeckTurn {
    private final float[] verticesX;
    private final float[] verticesY;
    private final float[] verticesZ;
    private final float[] originalX;
    private final float[] originalY;
    private final float[] originalZ;
    private final int vertexCount;

    private void restore() {
      System.arraycopy(originalX, 0, verticesX, 0, vertexCount);
      System.arraycopy(originalY, 0, verticesY, 0, vertexCount);
      System.arraycopy(originalZ, 0, verticesZ, 0, vertexCount);
    }
  }

  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  private static final class Candidate {
    private final int minX;
    private final int minY;
    private final int maxX;
    private final int maxY;
    private final int zoom;
    private final int verticalOffset;
    private final int score;
  }

  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  private static final class Framing {
    private final int zoom;
    private final int verticalOffset;
    private final int cropX;
    private final int cropY;
    private final int cropWidth;
    private final int cropHeight;
  }
}

package com.slayerplus;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;

class SlayerBraceletChargeTracker {
  static final int MAX_CHARGES = 30;
  static final String CONFIG_GROUP = "itemCharge";
  static final String SLAUGHTER_KEY = "braceletOfSlaughter";
  static final String EXPEDITIOUS_KEY = "expeditiousBracelet";
  private static final Pattern SLAUGHTER_ACTIVATE =
      Pattern.compile(
          "Your bracelet of slaughter prevents your slayer count from decreasing\\. "
              + "(?:It has (\\d{1,2}) charges? left\\.|It then crumbles to dust\\.|"
              + "It then regenerates itself to full charge!)");
  private static final Pattern SLAUGHTER_CHECK =
      Pattern.compile("Your bracelet of slaughter has (\\d{1,2}) charges? left\\.");
  private static final Pattern EXPEDITIOUS_ACTIVATE =
      Pattern.compile(
          "Your expeditious bracelet helps you progress your slayer (?:task )?faster\\. "
              + "(?:It has (\\d{1,2}) charges? left\\.|It then crumbles to dust\\.|"
              + "It then regenerates itself to full charge!)");
  private static final Pattern EXPEDITIOUS_CHECK =
      Pattern.compile("Your expeditious bracelet has (\\d{1,2}) charges? left\\.");

  private SlayerBraceletChargeTracker() {}

  static Update parse(String message) {
    if (message == null || message.isEmpty()) {
      return null;
    }
    Update update =
        match(message, SLAUGHTER_ACTIVATE, ItemID.BRACELET_OF_SLAUGHTER, SLAUGHTER_KEY, true);
    if (update != null) {
      return update;
    }
    update = match(message, SLAUGHTER_CHECK, ItemID.BRACELET_OF_SLAUGHTER, SLAUGHTER_KEY, false);
    if (update != null) {
      return update;
    }
    update =
        match(message, EXPEDITIOUS_ACTIVATE, ItemID.EXPEDITIOUS_BRACELET, EXPEDITIOUS_KEY, true);
    return update != null
        ? update
        : match(message, EXPEDITIOUS_CHECK, ItemID.EXPEDITIOUS_BRACELET, EXPEDITIOUS_KEY, false);
  }

  private static Update match(
      String message, Pattern pattern, int itemId, String configKey, boolean resetWhenNoCount) {
    Matcher matcher = pattern.matcher(message);
    if (!matcher.find()) {
      return null;
    }
    String count = matcher.group(1);
    int charges =
        count == null && resetWhenNoCount
            ? message.contains("crumbles to dust") ? 0 : MAX_CHARGES
            : Integer.parseInt(count);
    return new Update(itemId, configKey, charges);
  }

  static String configKey(int itemId) {
    if (itemId == ItemID.BRACELET_OF_SLAUGHTER) {
      return SLAUGHTER_KEY;
    }
    if (itemId == ItemID.EXPEDITIOUS_BRACELET) {
      return EXPEDITIOUS_KEY;
    }
    return "";
  }

  static final class Update {
    private final int itemId;
    private final String configKey;
    private final int charges;

    private Update(int itemId, String configKey, int charges) {
      this.itemId = itemId;
      this.configKey = configKey;
      this.charges = Math.max(0, Math.min(MAX_CHARGES, charges));
    }

    int getItemId() {
      return itemId;
    }

    String getConfigKey() {
      return configKey;
    }

    int getCharges() {
      return charges;
    }
  }
}

package com.slayerplus;

import java.util.*;
import lombok.Getter;

@Getter
public final class KitPlan {
  private final String ownedStatus;
  private final String layoutTitle;
  private final List<KitItem> equipmentItems;
  private final List<KitItem> inventoryItems;
  private final List<KitItem> optionalItems;

  public KitPlan(String ownedStatus) {
    this(
        ownedStatus,
        "Recommended setup",
        Collections.emptyList(),
        Collections.emptyList(),
        Collections.emptyList());
  }

  public KitPlan(
      String ownedStatus,
      String layoutTitle,
      List<KitItem> equipmentItems,
      List<KitItem> inventoryItems,
      List<KitItem> optionalItems) {
    this.ownedStatus = safe(ownedStatus, "No item scan available");
    this.layoutTitle = safe(layoutTitle, "Recommended setup");
    this.equipmentItems = immutableCopy(equipmentItems);
    this.inventoryItems = immutableCopy(inventoryItems);
    this.optionalItems = immutableCopy(optionalItems);
  }

  public List<KitItem> getBankWithdrawalItems() {
    List<KitItem> result = new ArrayList<>();
    Set<Integer> seenIds = new LinkedHashSet<>();
    addBankedUnique(result, seenIds, equipmentItems);
    addBankedUnique(result, seenIds, inventoryItems);
    return Collections.unmodifiableList(result);
  }

  KitPlan withRemainingFinishers(int remaining) {
    List<KitItem> updated = null;
    for (int i = 0; i < inventoryItems.size(); i++) {
      KitItem item = inventoryItems.get(i);
      String name = item.getDisplayName().toLowerCase(Locale.ROOT);
      int quantity =
          name.equals("fungicide")
              ? 1 + (Math.max(1, remaining) - 1) / 10
              : name.equals("bag of salt")
                      || name.equals("ice cooler")
                      || name.contains("fishing explosive")
                  ? Math.max(1, remaining)
                  : item.getQuantity();
      quantity = Math.min(item.getQuantity(), quantity);
      if (quantity != item.getQuantity()) {
        if (updated == null) {
          updated = new ArrayList<>(inventoryItems);
        }
        updated.set(i, item.withQuantity(quantity));
      }
    }
    return updated == null
        ? this
        : new KitPlan(ownedStatus, layoutTitle, equipmentItems, updated, optionalItems);
  }

  public boolean hasVisualLayout() {
    return !equipmentItems.isEmpty() || !inventoryItems.isEmpty();
  }

  public boolean hasConcreteItems() {
    return getConcreteItemCount() > 0;
  }

  public int getConcreteItemCount() {
    return countConcrete(equipmentItems)
        + countConcrete(inventoryItems)
        + countConcrete(optionalItems);
  }

  public int getUnresolvedItemCount() {
    return countUnresolved(equipmentItems)
        + countUnresolved(inventoryItems)
        + countUnresolved(optionalItems);
  }

  public static KitPlan hidden() {
    return new KitPlan(
        "Loadout recommendations disabled",
        "Loadout recommendations disabled",
        Collections.emptyList(),
        Collections.emptyList(),
        Collections.emptyList());
  }

  public static KitPlan researchPending(String assignment) {
    String task =
        assignment == null || assignment.trim().isEmpty() ? "This task" : assignment.trim();
    return new KitPlan(
        "SlayerPlus will not create a broad or guessed loadout.",
        task + " — strategy review pending",
        Collections.emptyList(),
        Collections.emptyList(),
        Collections.emptyList());
  }

  public static KitPlan empty() {
    return new KitPlan(
        "No active loadout",
        "Waiting for Slayer task",
        Collections.emptyList(),
        Collections.emptyList(),
        Collections.emptyList());
  }

  private static void addBankedUnique(
      List<KitItem> destination, Set<Integer> seenIds, List<KitItem> source) {
    for (KitItem item : source) {
      if (item != null && item.isBanked() && item.hasItemId() && seenIds.add(item.getItemId())) {
        destination.add(item);
      }
    }
  }

  private static int countConcrete(List<KitItem> items) {
    int count = 0;
    for (KitItem item : items) {
      if (item != null && item.hasItemId()) {
        count++;
      }
    }
    return count;
  }

  private static int countUnresolved(List<KitItem> items) {
    int count = 0;
    for (KitItem item : items) {
      if (item != null
          && !item.hasItemId()
          && (item.getStatus() == KitItem.Status.MISSING
              || item.getStatus() == KitItem.Status.UNKNOWN)) {
        count++;
      }
    }
    return count;
  }

  private static List<KitItem> immutableCopy(List<KitItem> source) {
    if (source == null || source.isEmpty()) {
      return Collections.emptyList();
    }
    List<KitItem> copy = new ArrayList<>();
    for (KitItem item : source) {
      if (item != null) {
        copy.add(item);
      }
    }
    return Collections.unmodifiableList(copy);
  }

  private static String safe(String value, String fallback) {
    return value == null || value.trim().isEmpty() ? fallback : value.trim();
  }
}

package com.slayerplus;

import java.util.*;

public final class SlayerTaskStrategyCatalog {
  private static final int STRATEGY_COLUMN_COUNT = 26;
  private static final int PROFILE_COLUMN_COUNT = 3;
  private static final int RECORD_TYPE = 0;
  private static final int STRATEGY_NAME = 1;
  private static final int COMBAT_STYLE = 2;
  private static final int ARMOUR_FOCUS = 3;
  private static final int COST_POLICY = 4;
  private static final int METHOD = 5;
  private static final int RATIONALE = 6;
  private static final int SELECTION_NOTE = 7;
  private static final int REVIEW_DATE = 8;
  private static final int WEAPONS = 9;
  private static final int MAX_DPS_WEAPONS = 10;
  private static final int EFFICIENT_WEAPONS = 11;
  private static final int OPTIONAL_ITEMS = 12;
  private static final int METHOD_TAGS = 13;
  private static final int PRAYER_SLOTS = 14;
  private static final int FOOD_SLOTS = 15;
  private static final int DAMAGE_PROFILE = 16;
  private static final int EXPECTED_DAMAGE_PER_KILL = 17;
  private static final int MINIMUM_FOOD_SLOTS = 18;
  private static final int INVENTORY_TARGET_SLOTS = 19;
  private static final int INCLUDE_RUNE_POUCH = 20;
  private static final int INCLUDE_ANTIVENOM = 21;
  private static final int INCLUDE_STAMINA = 22;
  private static final int STRICT_WEAPON_PROFILE = 23;
  private static final int BOSS_PROFILE = 24;
  private static final int REVIEWED_PROFILE = 25;
  private static final int PROFILE_KEY = 1;
  private static final int PROFILE_MAPPINGS = 2;
  private static final Map<String, Profiles> DATA = loadData();
  private static final Map<String, String> TASK_ALIASES = loadTaskAliases();
  private static final Map<String, Profiles> PROFILES = baseProfiles(DATA);
  private static final Set<String> COVERED_TASKS = TaskResearch.getReviewedTaskNames();
  private static final Set<String> REVIEWED_TASK_KEYS = TaskResearch.getReviewedTaskKeys();

  private SlayerTaskStrategyCatalog() {}

  public static TaskStrategy resolve(
      String assignment,
      Preference.Cannon cannonPreference,
      Preference.Burst burstPreference,
      Preference.CombatStyle combatPreference,
      String location,
      boolean wilderness) {
    var task = canonicalTaskKey(assignment);
    if (!REVIEWED_TASK_KEYS.contains(task)) {
      return unreviewed(assignment);
    }
    if (wilderness) {
      return wildernessStrategyFor(
          assignment, task, cannonPreference, burstPreference, combatPreference);
    }
    var base = PROFILES.get(task);
    if (base == null) {
      return unreviewed(assignment);
    }
    var profiles = profilesForLocation(task, normalize(location), base);
    TaskStrategy selected = null;
    if (combatPreference == Preference.CombatStyle.PREFER_MAGIC && profiles.magic == null) {
      var automatic = profiles.selectAutomatic();
      if (automatic != null
          && !automatic.isBoss()
          && automatic.getStyle() != TaskStrategy.CombatStyle.HYBRID) {
        var elemental = SlayerElementalWeaknessCatalog.preferenceStrategy(assignment, false);
        if (elemental != null) {
          selected =
              elemental.withSelectionNote(
                  "Magic preference applied using the current Wiki-listed elemental weakness;"
                      + " Automatic keeps the reviewed practical method.");
        }
      }
    }
    if (selected == null) {
      selected = profiles.select(cannonPreference, burstPreference, combatPreference);
    }
    if (selected != null
        && !selected.isBoss()
        && cannonPreference == Preference.Cannon.PREFER
        && !selected.hasTag(TaskStrategy.MethodTag.CANNON)
        && locationAllowsCannon(assignment, location)
        && cannonSupportsSelectedCombat(assignment, selected)) {
      selected =
          selected
              .withAdditionalTags(TaskStrategy.MethodTag.CANNON)
              .withSelectionNote(
                  "Cannon preference applied because the individually audited task location permits"
                      + " a dwarf multicannon.");
    }
    return selected;
  }

  private static boolean cannonSupportsSelectedCombat(String assignment, TaskStrategy strategy) {
    return strategy != null
        && (!canonicalTaskKey(assignment).equals("greater demons")
            || strategy.getStyle() != TaskStrategy.CombatStyle.MELEE);
  }

  private static boolean locationAllowsCannon(String assignment, String location) {
    var area = normalize(location);
    var task = canonicalTaskKey(assignment);
    if (task.equals("greater demons") && area.contains("karuulm")) {
      return true;
    }
    return !area.contains("catacombs")
        && !area.contains("slayer tower")
        && !area.contains("fremennik slayer dungeon")
        && !area.contains("karuulm")
        && !area.contains("kraken")
        && !area.contains("god wars")
        && !area.contains("mos le harmless");
  }

  public static TaskStrategy legacy(String method) {
    return unreviewed("Legacy recommendation");
  }

  public static boolean hasExplicitStrategy(String assignment) {
    return REVIEWED_TASK_KEYS.contains(canonicalTaskKey(assignment));
  }

  public static List<String> getCurrentTaskNames() {
    return Collections.unmodifiableList(new ArrayList<>(COVERED_TASKS));
  }

  public static TaskResearch.Entry getResearchRecord(String assignment) {
    return TaskResearch.find(canonicalTaskKey(assignment));
  }

  private static TaskStrategy wildernessStrategyFor(
      String assignment,
      String task,
      Preference.Cannon cannonPreference,
      Preference.Burst burstPreference,
      Preference.CombatStyle combatPreference) {
    var research = TaskResearch.find(assignment);
    if (research == null || !research.isWildernessReviewed()) {
      return unreviewedWilderness(assignment);
    }
    var base = PROFILES.get(task);
    if (base != null) {
      var selected = base.select(cannonPreference, burstPreference, combatPreference);
      if (selected != null
          && selected.hasTag(TaskStrategy.MethodTag.WILDERNESS)
          && selected.getCostPolicy() == TaskStrategy.CostPolicy.LOW_RISK) {
        return selected.withSelectionNote("Reviewed low-risk Wilderness profile applied.");
      }
    }
    var wilderness = DATA.get("wilderness:" + task);
    if (wilderness != null) {
      return wilderness
          .select(cannonPreference, burstPreference, combatPreference)
          .withSelectionNote(
              "Krystilia assignment: individually reviewed LOW_RISK Wilderness branch applied.");
    }
    return unreviewedWilderness(assignment);
  }

  private static Profiles profilesForLocation(String task, String location, Profiles fallback) {
    if (task.equals("ankou")) {
      if (location.contains("stronghold slayer cave")) {
        return data("location:ankou:stronghold_slayer_cave", fallback);
      }
      if (location.contains("stronghold of security")) {
        return data("location:ankou:stronghold_of_security", fallback);
      }
    }
    if (task.equals("abyssal demons") && location.contains("slayer tower")) {
      return data("location:abyssal_demons:slayer_tower", fallback);
    }
    if (task.equals("bloodveld")) {
      if (location.contains("meiyerditch") || location.contains("buccaneer")) {
        return data("location:bloodveld:multi_cannon", fallback);
      }
      if (location.contains("iorwerth") || location.contains("stronghold slayer cave")) {
        return data("location:bloodveld:single_cannon", fallback);
      }
      if (location.contains("catacombs")) {
        return data("location:bloodveld:catacombs", fallback);
      }
      if (location.contains("slayer tower")) {
        return data("location:bloodveld:slayer_tower", fallback);
      }
      if (location.contains("god wars dungeon")) {
        return data("location:bloodveld:god_wars", fallback);
      }
    }
    if (task.equals("aberrant spectres")) {
      if (location.contains("stronghold slayer cave")) {
        return data("location:aberrant_spectres:stronghold_slayer_cave", fallback);
      }
      if (location.contains("catacombs")) {
        return data("location:aberrant_spectres:catacombs", fallback);
      }
    }
    if (task.equals("hellhounds")) {
      if (location.contains("stronghold slayer cave")
          || location.contains("taverley dungeon")
          || location.contains("karuulm slayer dungeon")) {
        return data("location:hellhounds:cannon", fallback);
      }
      if (location.contains("catacombs")) {
        return data("location:hellhounds:catacombs", fallback);
      }
    }
    if (task.equals("greater demons") && locationAllowsCannon(task, location)) {
      return data("location:greater_demons:cannon", fallback);
    }
    if (task.equals("nechryael") && location.contains("iorwerth")) {
      return data("location:nechryael:iorwerth", fallback);
    }
    return fallback;
  }

  private static Profiles data(String key, Profiles fallback) {
    var profiles = DATA.get(key);
    return profiles == null ? fallback : profiles;
  }

  private static TaskStrategy unreviewed(String assignment) {
    return TaskStrategy.builder(
            TaskStrategy.CombatStyle.HYBRID, "Research pending — loadout disabled")
        .rationale(
            (assignment == null ? "This task" : assignment)
                + " has not yet passed individual strategy review. SlayerPlus will not invent a"
                + " broad equipment template.")
        .prayers(0)
        .food(0)
        .strictWeaponProfile(true)
        .build();
  }

  private static TaskStrategy unreviewedWilderness(String assignment) {
    return TaskStrategy.builder(
            TaskStrategy.CombatStyle.HYBRID, "Wilderness research pending — loadout disabled")
        .costPolicy(TaskStrategy.CostPolicy.LOW_RISK)
        .rationale(
            (assignment == null ? "This task" : assignment)
                + " has no individually reviewed Krystilia profile. The normal-task profile is"
                + " never reused in the Wilderness.")
        .tags(TaskStrategy.MethodTag.WILDERNESS)
        .prayers(0)
        .food(0)
        .strictWeaponProfile(true)
        .build();
  }

  private static Map<String, Profiles> loadData() {
    Map<String, TaskStrategy> strategies = new LinkedHashMap<>();
    Map<String, Profiles> profiles = new LinkedHashMap<>();
    var lineNumber = 0;
    try {
      for (String[] fields :
          ResourceTable.rows(
              "slayer-task-strategies.tsv", PROFILE_COLUMN_COUNT, STRATEGY_COLUMN_COUNT)) {
        lineNumber++;
        if (fields.length == STRATEGY_COLUMN_COUNT && "S".equals(fields[RECORD_TYPE])) {
          var id = restoreEscapedDelimiters(fields[STRATEGY_NAME]);
          if (strategies.put(id, parseStrategy(fields, lineNumber)) != null) {
            throw new IllegalStateException("Duplicate Slayer strategy id " + id);
          }
          continue;
        }
        if (fields.length == PROFILE_COLUMN_COUNT && "P".equals(fields[RECORD_TYPE])) {
          var key = restoreEscapedDelimiters(fields[PROFILE_KEY]);
          var group = new Profiles();
          for (String mapping : fields[PROFILE_MAPPINGS].split(";", -1)) {
            var separator = mapping.indexOf('=');
            if (separator <= 0 || separator == mapping.length() - 1) {
              throw new IllegalStateException(
                  "Invalid Slayer profile mapping at row " + lineNumber);
            }
            var id = mapping.substring(separator + 1);
            var strategy = strategies.get(id);
            if (strategy == null) {
              throw new IllegalStateException(
                  "Unknown Slayer strategy id " + id + " at row " + lineNumber);
            }
            group.set(mapping.substring(0, separator), strategy);
          }
          if (profiles.put(key, group) != null) {
            throw new IllegalStateException("Duplicate Slayer profile " + key);
          }
          continue;
        }
        throw new IllegalStateException(
            "Invalid Slayer strategy row " + lineNumber + ": expected an S or P record");
      }
    } catch (RuntimeException ex) {
      throw new IllegalStateException("Unable to load reviewed Slayer strategies", ex);
    }
    for (Map.Entry<String, Profiles> entry : profiles.entrySet()) {
      entry.getValue().validate(entry.getKey());
    }
    return Collections.unmodifiableMap(profiles);
  }

  private static TaskStrategy parseStrategy(String[] fields, int lineNumber) {
    try {
      var builder =
          TaskStrategy.builder(
                  TaskStrategy.CombatStyle.valueOf(restoreEscapedDelimiters(fields[COMBAT_STYLE])),
                  restoreEscapedDelimiters(fields[METHOD]))
              .armourFocus(
                  TaskStrategy.ArmourFocus.valueOf(restoreEscapedDelimiters(fields[ARMOUR_FOCUS])))
              .costPolicy(
                  TaskStrategy.CostPolicy.valueOf(restoreEscapedDelimiters(fields[COST_POLICY])))
              .rationale(restoreEscapedDelimiters(fields[RATIONALE]))
              .selectionNote(restoreEscapedDelimiters(fields[SELECTION_NOTE]))
              .weapons(splitList(fields[WEAPONS]))
              .maxDpsWeapons(splitList(fields[MAX_DPS_WEAPONS]))
              .efficientWeapons(splitList(fields[EFFICIENT_WEAPONS]))
              .optionalItems(splitList(fields[OPTIONAL_ITEMS]))
              .tags(tags(fields[METHOD_TAGS]))
              .prayers(Integer.parseInt(fields[PRAYER_SLOTS]))
              .food(Integer.parseInt(fields[FOOD_SLOTS]))
              .damageProfile(TaskStrategy.DamageProfile.valueOf(fields[DAMAGE_PROFILE]))
              .damagePerKill(Double.parseDouble(fields[EXPECTED_DAMAGE_PER_KILL]))
              .minimumFoodSlots(Integer.parseInt(fields[MINIMUM_FOOD_SLOTS]))
              .inventoryTargetSlots(Integer.parseInt(fields[INVENTORY_TARGET_SLOTS]))
              .runePouch(Boolean.parseBoolean(fields[INCLUDE_RUNE_POUCH]))
              .antivenom(Boolean.parseBoolean(fields[INCLUDE_ANTIVENOM]))
              .stamina(Boolean.parseBoolean(fields[INCLUDE_STAMINA]))
              .strictWeaponProfile(Boolean.parseBoolean(fields[STRICT_WEAPON_PROFILE]))
              .boss(Boolean.parseBoolean(fields[BOSS_PROFILE]));
      if (Boolean.parseBoolean(fields[REVIEWED_PROFILE])) {
        builder.reviewed(restoreEscapedDelimiters(fields[REVIEW_DATE]));
      }
      return builder.build();
    } catch (RuntimeException ex) {
      throw new IllegalStateException("Invalid Slayer strategy at row " + lineNumber, ex);
    }
  }

  private static String[] splitList(String escapedText) {
    var value = restoreEscapedDelimiters(escapedText);
    return value.isEmpty() ? new String[0] : value.split("; ", -1);
  }

  private static TaskStrategy.MethodTag[] tags(String escapedText) {
    var values = splitList(escapedText);
    var tags = new TaskStrategy.MethodTag[values.length];
    for (var index = 0; index < values.length; index++) {
      tags[index] =
          "BURST_BARRAGE".equals(values[index])
              ? TaskStrategy.MethodTag.BARRAGE
              : TaskStrategy.MethodTag.valueOf(values[index]);
    }
    return tags;
  }

  private static String restoreEscapedDelimiters(String escapedText) {
    if (escapedText == null || escapedText.indexOf('\\') < 0) {
      return escapedText;
    }
    var value = new StringBuilder(escapedText.length());
    var escaped = false;
    for (var index = 0; index < escapedText.length(); index++) {
      var character = escapedText.charAt(index);
      if (!escaped && character == '\\') {
        escaped = true;
        continue;
      }
      if (escaped) {
        switch (character) {
          case 't':
            value.append('\t');
            break;
          case 'r':
            value.append('\r');
            break;
          case 'n':
            value.append('\n');
            break;
          case 'p':
            value.append('|');
            break;
          default:
            value.append(character);
            break;
        }
        escaped = false;
      } else {
        value.append(character);
      }
    }
    if (escaped) {
      value.append('\\');
    }
    return value.toString();
  }

  private static Map<String, Profiles> baseProfiles(Map<String, Profiles> data) {
    final Map<String, Profiles> base = new HashMap<>();
    for (Map.Entry<String, Profiles> entry : data.entrySet()) {
      if (entry.getKey().startsWith("base:")) {
        base.put(entry.getKey().substring(5), entry.getValue());
      }
    }
    return Collections.unmodifiableMap(base);
  }

  private static String normalize(String value) {
    return SlayerText.encounter(value);
  }

  private static String canonicalTaskKey(String value) {
    var key = normalize(value);
    return TASK_ALIASES.getOrDefault(key, key);
  }

  private static Map<String, String> loadTaskAliases() {
    Map<String, String> aliases = new HashMap<>();
    for (String[] row : ResourceTable.rows("slayer-task-aliases.tsv", 2)) {
      var previous = aliases.put(normalize(row[0]), normalize(row[1]));
      if (previous != null) {
        throw new IllegalStateException("Duplicate task alias " + row[0]);
      }
    }
    return Collections.unmodifiableMap(aliases);
  }

  private static final class Profiles {
    private TaskStrategy balanced;
    private TaskStrategy fast;
    private TaskStrategy afk;
    private TaskStrategy profit;
    private TaskStrategy melee;
    private TaskStrategy ranged;
    private TaskStrategy magic;
    private TaskStrategy burst;
    private TaskStrategy nonBurst;
    private TaskStrategy cannon;
    private TaskStrategy nonCannon;

    private void set(String role, TaskStrategy value) {
      switch (role) {
        case "balanced":
          balanced = value;
          break;
        case "fast":
          fast = value;
          break;
        case "afk":
          afk = value;
          break;
        case "profit":
          profit = value;
          break;
        case "melee":
          melee = value;
          break;
        case "ranged":
          ranged = value;
          break;
        case "magic":
          magic = value;
          break;
        case "burst":
          burst = value;
          break;
        case "non_burst":
          nonBurst = value;
          break;
        case "cannon":
          cannon = value;
          break;
        case "non_cannon":
          nonCannon = value;
          break;
        default:
          throw new IllegalStateException("Unknown strategy role " + role);
      }
    }

    private void validate(String key) {
      if (balanced == null || fast == null || afk == null || profit == null)
        throw new IllegalStateException("Incomplete Slayer strategy group " + key);
    }

    private TaskStrategy select(
        Preference.Cannon cannonPreference,
        Preference.Burst burstPreference,
        Preference.CombatStyle combatPreference) {
      var selected = selectCombatPreference(combatPreference);
      var explicitCombat = selected != null;
      var note = "";
      if (!explicitCombat) {
        selected = selectAutomatic();
      }
      if (!explicitCombat && cannonPreference == Preference.Cannon.PREFER && cannon != null) {
        selected = cannon;
      }
      if (!explicitCombat && burstPreference == Preference.Burst.PREFER && burst != null) {
        selected = burst;
      }
      if (violatesEnabledPreferences(selected, cannonPreference, burstPreference)) {
        selected = safePreferenceFallback(selected, cannonPreference, burstPreference);
        note =
            "Disabled cannon/burst preferences were enforced with a reviewed compatible fallback.";
      }
      selected = applyAutomaticLoadoutPolicy(selected);
      var authoredNote = selected.getSelectionNote();
      if (note.isEmpty() && explicitCombat)
        note =
            combatPreference
                + " applied because this task has a reviewed viable "
                + selected.getStyle().getLabel()
                + " setup.";
      if (note.isEmpty()) {
        note =
            "Automatic selected the reviewed "
                + selected.getStyle().getLabel()
                + " method."
                + (selected.hasTag(TaskStrategy.MethodTag.BARRAGE)
                    ? " Burst/Barrage preference permits this method."
                    : "")
                + (selected.hasTag(TaskStrategy.MethodTag.CANNON)
                    ? " Cannon preference permits this method."
                    : "");
      }
      var generated = note + automaticLoadoutNote(selected);
      return selected.withSelectionNote(
          authoredNote == null || authoredNote.trim().isEmpty()
              ? generated
              : generated + " " + authoredNote.trim());
    }

    private TaskStrategy applyAutomaticLoadoutPolicy(TaskStrategy strategy) {
      if (strategy == null) {
        return null;
      }
      if (strategy.getCostPolicy() == TaskStrategy.CostPolicy.LOW_RISK
          || strategy.hasTag(TaskStrategy.MethodTag.WILDERNESS)) {
        return strategy;
      }
      return strategy.withLoadoutPolicy(
          TaskStrategy.ArmourFocus.DAMAGE, TaskStrategy.CostPolicy.MAX_DPS);
    }

    private String automaticLoadoutNote(TaskStrategy strategy) {
      if (strategy == null
          || strategy.getCostPolicy() == TaskStrategy.CostPolicy.LOW_RISK
          || strategy.hasTag(TaskStrategy.MethodTag.WILDERNESS)) {
        return "";
      }
      return " Automatic loadouts use damage gear and MAX_DPS equipment without considering item"
          + " or charge cost.";
    }

    private TaskStrategy selectCombatPreference(Preference.CombatStyle preference) {
      if (preference == null || preference == Preference.CombatStyle.AUTOMATIC) {
        return null;
      }
      switch (preference) {
        case PREFER_MELEE:
          return melee;
        case PREFER_RANGED:
          return ranged;
        case PREFER_MAGIC:
          return magic;
        default:
          return null;
      }
    }

    private boolean violatesEnabledPreferences(
        TaskStrategy strategy,
        Preference.Cannon cannonPreference,
        Preference.Burst burstPreference) {
      return strategy != null
          && ((cannonPreference == Preference.Cannon.NEVER
                  && strategy.hasTag(TaskStrategy.MethodTag.CANNON))
              || (burstPreference == Preference.Burst.NEVER
                  && strategy.hasTag(TaskStrategy.MethodTag.BARRAGE)));
    }

    private TaskStrategy safePreferenceFallback(
        TaskStrategy current,
        Preference.Cannon cannonPreference,
        Preference.Burst burstPreference) {
      TaskStrategy[] candidates = {
        current, nonCannon, nonBurst, melee, ranged, magic, balanced, fast, afk, profit, cannon,
        burst
      };
      for (TaskStrategy candidate : candidates) {
        if (candidate != null
            && !violatesEnabledPreferences(candidate, cannonPreference, burstPreference)) {
          return candidate;
        }
      }
      return current;
    }

    private TaskStrategy selectAutomatic() {
      return fast;
    }
  }
}

package com.slayerplus;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

final class ResourceTable {
  private ResourceTable() {}

  static List<String[]> rows(String name, int... columns) {
    return rows(name, false, columns);
  }

  static List<String[]> rowsWithEscapedDelimiters(String name, int... columns) {
    return rows(name, true, columns);
  }

  private static List<String[]> rows(String name, boolean decode, int... columns) {
    String path = "/com/slayerplus/" + name;
    InputStream input = ResourceTable.class.getResourceAsStream(path);
    if (input == null) {
      throw new IllegalStateException("Missing SlayerPlus resource: " + path);
    }
    List<String[]> rows = new ArrayList<>();
    try (BufferedReader reader =
        new BufferedReader(new InputStreamReader(input, StandardCharsets.UTF_8))) {
      String line;
      while ((line = reader.readLine()) != null) {
        if (line.isEmpty() || line.charAt(0) == '#') {
          continue;
        }
        String[] row = line.split("\\t", -1);
        boolean valid = columns.length == 0;
        for (int columnsInShape : columns) {
          valid |= row.length == columnsInShape;
        }
        if (!valid) {
          throw new IllegalStateException("Invalid " + name + " row: " + line);
        }
        if (decode) {
          for (int index = 0; index < row.length; index++) {
            row[index] = restoreEscapedDelimiters(row[index]);
          }
        }
        rows.add(row);
      }
    } catch (IOException ex) {
      throw new IllegalStateException("Unable to read SlayerPlus resource: " + path, ex);
    }
    return Collections.unmodifiableList(rows);
  }

  private static String restoreEscapedDelimiters(String value) {
    return value.replace("%7C", "|").replace("%0A", "\n").replace("%09", "\t").replace("%25", "%");
  }
}

package com.slayerplus;

import lombok.AccessLevel;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

public final class BoostCoordinator {
  public static final int TURAEL_AYA_MASTER_ID = 1;

  private BoostCoordinator() {}

  public static Decision nextAssignment(int completedStreak, Preference.BonusMaster bonusMaster) {
    int safeStreak = Math.max(0, completedStreak);
    int completionNumber = safeStreak + 1;
    boolean bonusTask = completionNumber % 10 == 0;
    Preference.BonusMaster selectedBonusMaster =
        bonusMaster == null ? Preference.BonusMaster.KONAR : bonusMaster;
    return new Decision(
        completionNumber,
        bonusTask ? selectedBonusMaster.getMasterId() : TURAEL_AYA_MASTER_ID,
        bonusTask,
        bonusTask ? 10 : completionNumber % 10);
  }

  @Getter
  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  public static final class Decision {
    private final int completionNumber;
    private final int masterId;
    private final boolean bonusTask;
    private final int cycleStep;

    public String getProgressText() {
      return bonusTask
          ? "Bonus task " + completionNumber
          : "Turael/Aya task " + cycleStep + " of 9";
    }
  }
}

package com.slayerplus;

import java.util.*;
import net.runelite.api.EquipmentInventorySlot;

public final class SlayerEquipmentAuditCatalog {
  private static final Map<String, List<String>> LISTS = loadLists();
  private static final Map<String, Map<EquipmentInventorySlot, List<String>>> PROFILES =
      loadProfiles();

  private SlayerEquipmentAuditCatalog() {}

  public static List<String> priorities(
      String assignment,
      TaskStrategy strategy,
      EquipmentInventorySlot slot,
      String selectedWeaponName) {
    if (strategy == null || slot == null) {
      return Collections.emptyList();
    }
    var style = strategy.getStyle();
    var focus = strategy.getArmourFocus();
    var task = normalize(assignment);
    var weapon = normalize(selectedWeaponName);
    var prayer = focus == TaskStrategy.ArmourFocus.PRAYER;
    var magicDefence = focus == TaskStrategy.ArmourFocus.MAGIC_DEFENCE;
    var wilderness =
        strategy.getCostPolicy() == TaskStrategy.CostPolicy.LOW_RISK
            || strategy.hasTag(TaskStrategy.MethodTag.WILDERNESS);
    if (slot == EquipmentInventorySlot.HEAD) {
      if (task.contains("shellbane gryphon")) {
        return list("equipment_black_mask_i_black_mask");
      }
      if ((task.equals("blue dragon") || task.equals("blue dragons"))
          && style == TaskStrategy.CombatStyle.RANGED) {
        return list("equipment_slayer_helmet_i_black_mask_i");
      }
      return style == TaskStrategy.CombatStyle.MELEE
          ? list("equipment_slayer_helmet_i_black_mask_i_2")
          : list("equipment_slayer_helmet_i_black_mask_i_3");
    }
    if (task.equals("blue dragon") || task.equals("blue dragons")) {
      return profile(
          style == TaskStrategy.CombatStyle.MAGIC
              ? "blue-magic"
              : style == TaskStrategy.CombatStyle.MELEE ? "blue-melee" : "blue-ranged",
          slot);
    }
    if (task.equals("vorkath")) {
      return profile(
          style == TaskStrategy.CombatStyle.MELEE ? "vorkath-melee" : "vorkath-ranged", slot);
    }
    if (task.equals("tzkal zuk")) {
      return ranged(slot, weapon, false);
    }
    if (task.equals("royal titans")) {
      return royalTitans(slot);
    }
    if (task.equals("araxxor")) {
      return araxxor(slot, weapon);
    }
    if (task.equals("dagannoth rex")) {
      return profile("dagannoth-rex", slot);
    }
    if (task.equals("dagannoth kings")) {
      return profile("dagannoth-kings", slot);
    }
    if (slot == EquipmentInventorySlot.AMULET && task.contains("banshee")) {
      return list("equipment_salve_amulet_ei_salve_amulet_e");
    }
    if ((task.equals("blue dragon") || task.equals("blue dragons"))
        && style == TaskStrategy.CombatStyle.RANGED
        && slot == EquipmentInventorySlot.SHIELD) {
      return list("equipment_dragonfire_ward_anti_dragon_shield");
    }
    if ((task.equals("skeletal wyvern") || task.equals("skeletal wyverns"))
        && slot == EquipmentInventorySlot.SHIELD) {
      if (style == TaskStrategy.CombatStyle.RANGED) {
        return list("equipment_dragonfire_ward_ancient_wyvern_shield");
      }
      if (style == TaskStrategy.CombatStyle.MAGIC) {
        return list("equipment_ancient_wyvern_shield_mind_shield");
      }
      return list("equipment_ancient_wyvern_shield_dragonfire_shield");
    }
    if (task.equals("barrows brothers")) {
      return slot == EquipmentInventorySlot.HEAD
          ? list("equipment_ancestral_hat_virtus_mask")
          : profile("barrows", slot);
    }
    if (task.equals("k ril tsutsaroth") && style == TaskStrategy.CombatStyle.RANGED) {
      if (weapon.contains("bow of faerdhinen")) {
        if (slot == EquipmentInventorySlot.BODY) {
          return list("equipment_crystal_body_masori_body_f");
        }
        if (slot == EquipmentInventorySlot.LEGS) {
          return list("equipment_crystal_legs_masori_chaps_f");
        }
      }
      return profile("kril-ranged", slot);
    }
    if (task.equals("k ril tsutsaroth") && style == TaskStrategy.CombatStyle.MELEE) {
      return profile("kril-melee", slot);
    }
    if (task.equals("grotesque guardians") || task.equals("the grotesque guardians")) {
      return profile("grotesque", slot);
    }
    if (task.equals("tormented demons")) {
      return profile("tormented", slot);
    }
    if (task.equals("whisperer") || task.equals("the whisperer")) {
      if (slot == EquipmentInventorySlot.RING && weapon.contains("tumeken s shadow")) {
        return list("equipment_magus_ring_lightbearer");
      }
      return profile("whisperer", slot);
    }
    if (task.equals("kalphite queen") || task.equals("the kalphite queen")) {
      return profile(
          style == TaskStrategy.CombatStyle.MAGIC ? "kalphite-magic" : "kalphite-melee", slot);
    }
    if (task.contains("shellbane gryphon")) {
      switch (slot) {
        case BODY:
          return list("equipment_torva_platebody_oathplate_chest_4");
        case LEGS:
          return list("equipment_torva_platelegs_oathplate_legs_4");
        case SHIELD:
          return list("equipment_tortugan_shield");
        case BOOTS:
          return list("equipment_avernic_treads_echo_boots");
        default:
          break;
      }
    }
    if (task.equals("gryphon") || task.equals("gryphons")) {
      switch (slot) {
        case HEAD:
          return list("equipment_black_mask_i_black_mask");
        case BODY:
          return list("equipment_torva_platebody_oathplate_chest_5");
        case LEGS:
          return list("equipment_torva_platelegs_oathplate_legs_5");
        case BOOTS:
          return list("equipment_guardian_boots_echo_boots");
        default:
          break;
      }
    }
    if (task.contains("maggot king")) {
      return profile("maggot", slot);
    }
    if (wilderness) {
      return wilderness(style, slot);
    }
    if (slot == EquipmentInventorySlot.GLOVES && strategy.isBoss()) {
      return bossGloves(style);
    }
    switch (style) {
      case RANGED:
        return ranged(slot, weapon, prayer);
      case MAGIC:
        return magic(slot, prayer, magicDefence, assignment);
      case HYBRID:
        return hybrid(slot);
      case MELEE:
      default:
        return melee(slot, prayer, magicDefence);
    }
  }

  private static List<String> bossGloves(TaskStrategy.CombatStyle style) {
    switch (style) {
      case RANGED:
        return list("equipment_zaryte_vambraces_barrows_gloves_2");
      case MAGIC:
        return list("equipment_confliction_gauntlets_tormented_bracelet_3");
      case HYBRID:
        return list("equipment_barrows_gloves_ferocious_gloves_2");
      case MELEE:
      default:
        return list("equipment_ferocious_gloves_barrows_gloves_3");
    }
  }

  public static List<String> weaponProgression(TaskStrategy strategy) {
    if (strategy == null) {
      return Collections.emptyList();
    }
    var wilderness =
        strategy.getCostPolicy() == TaskStrategy.CostPolicy.LOW_RISK
            || strategy.hasTag(TaskStrategy.MethodTag.WILDERNESS);
    if (wilderness) {
      switch (strategy.getStyle()) {
        case MAGIC:
          return list("equipment_accursed_sceptre_thammaron_s_sceptre");
        case RANGED:
          return list("equipment_webweaver_bow_craw_s_bow");
        case MELEE:
        default:
          return list("equipment_abyssal_whip_zombie_axe");
      }
    }
    switch (strategy.getStyle()) {
      case RANGED:
        return list("equipment_venator_bow_toxic_blowpipe");
      case MAGIC:
        return list("equipment_tumeken_s_shadow_eye_of_ayak");
      case HYBRID:
        return list("equipment_tumeken_s_shadow_eye_of_ayak_2");
      case MELEE:
      default:
        return list("equipment_soulreaper_axe_ghrazi_rapier");
    }
  }

  private static List<String> melee(
      EquipmentInventorySlot slot, boolean prayer, boolean magicDefence) {
    var overlay = magicDefence ? "melee-magic-defence" : prayer ? "melee-prayer" : null;
    var values = overlay == null ? null : profile(overlay, slot);
    if (values != null && !values.isEmpty()) {
      return values;
    }
    return profile("melee", slot);
  }

  private static List<String> ranged(EquipmentInventorySlot slot, String weapon, boolean prayer) {
    if (weapon.contains("bow of faerdhinen")) {
      if (slot == EquipmentInventorySlot.BODY) {
        return prepend("crystal body", profile("ranged", slot));
      }
      if (slot == EquipmentInventorySlot.LEGS) {
        return prepend("crystal legs", profile("ranged", slot));
      }
    }
    var values = prayer ? profile("ranged-prayer", slot) : null;
    if (values != null && !values.isEmpty()) {
      return values;
    }
    return profile("ranged", slot);
  }

  private static List<String> magic(
      EquipmentInventorySlot slot, boolean prayer, boolean magicDefence, String assignment) {
    var accuracySensitive = normalize(assignment).contains("smoke devil");
    var overlay =
        magicDefence ? "magic-defence" : prayer && !accuracySensitive ? "magic-prayer" : null;
    var values = overlay == null ? null : profile(overlay, slot);
    if (values != null && !values.isEmpty()) {
      return values;
    }
    return profile("magic", slot);
  }

  private static List<String> hybrid(EquipmentInventorySlot slot) {
    return profile("hybrid", slot);
  }

  private static List<String> royalTitans(EquipmentInventorySlot slot) {
    return profile("royal-titans", slot);
  }

  private static List<String> araxxor(EquipmentInventorySlot slot, String weapon) {
    var soulreaper = weapon.contains("soulreaper axe");
    if (soulreaper) {
      if (slot == EquipmentInventorySlot.BODY) {
        return list("equipment_oathplate_chest_inquisitor_s_hauberk");
      }
      if (slot == EquipmentInventorySlot.LEGS) {
        return list("equipment_oathplate_legs_inquisitor_s_plateskirt");
      }
    }
    return profile("araxxor", slot);
  }

  private static List<String> wilderness(
      TaskStrategy.CombatStyle style, EquipmentInventorySlot slot) {
    var name =
        style == TaskStrategy.CombatStyle.MAGIC
            ? "wilderness-magic"
            : style == TaskStrategy.CombatStyle.MELEE ? "wilderness-melee" : "wilderness-ranged";
    return profile(name, slot);
  }

  private static List<String> prepend(String value, List<String> remaining) {
    var values = new String[remaining.size() + 1];
    values[0] = value;
    for (var i = 0; i < remaining.size(); i++) {
      values[i + 1] = remaining.get(i);
    }
    return values(values);
  }

  private static List<String> values(String... values) {
    return Collections.unmodifiableList(Arrays.asList(values));
  }

  private static List<String> list(String key) {
    var values = LISTS.get(key);
    if (values == null) {
      throw new IllegalStateException("Missing equipment list: " + key);
    }
    return values;
  }

  private static List<String> profile(String name, EquipmentInventorySlot slot) {
    var values = PROFILES.get(name);
    if (values == null) {
      throw new IllegalStateException("Missing equipment profile: " + name);
    }
    return values.getOrDefault(slot, Collections.emptyList());
  }

  private static Map<String, List<String>> loadLists() {
    Map<String, List<String>> lists = new LinkedHashMap<>();
    for (String[] row : ResourceTable.rows("slayer-equipment-lists.tsv", 2)) {
      lists.put(row[0], values(row[1].split("\\|", -1)));
    }
    return Collections.unmodifiableMap(lists);
  }

  private static Map<String, Map<EquipmentInventorySlot, List<String>>> loadProfiles() {
    EquipmentInventorySlot[] slots = {
      EquipmentInventorySlot.CAPE,
      EquipmentInventorySlot.AMULET,
      EquipmentInventorySlot.BODY,
      EquipmentInventorySlot.SHIELD,
      EquipmentInventorySlot.LEGS,
      EquipmentInventorySlot.GLOVES,
      EquipmentInventorySlot.BOOTS,
      EquipmentInventorySlot.RING,
      EquipmentInventorySlot.AMMO
    };
    Map<String, Map<EquipmentInventorySlot, List<String>>> profiles = new LinkedHashMap<>();
    for (String[] row : ResourceTable.rows("slayer-equipment-profiles.tsv", 10)) {
      Map<EquipmentInventorySlot, List<String>> values =
          new EnumMap<>(EquipmentInventorySlot.class);
      for (var i = 0; i < slots.length; i++) {
        if (!row[i + 1].isEmpty() && !row[i + 1].equals("-")) {
          values.put(slots[i], list(row[i + 1]));
        }
      }
      profiles.put(row[0], Collections.unmodifiableMap(values));
    }
    return Collections.unmodifiableMap(profiles);
  }

  private static String normalize(String value) {
    return SlayerText.normalize(value);
  }
}

package com.slayerplus;

import java.util.*;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
public final class TaskStrategy {
  @Getter
  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  public enum CombatStyle {
    MELEE("melee"),
    RANGED("ranged"),
    MAGIC("magic"),
    HYBRID("hybrid");
    private final String label;
  }

  public enum ArmourFocus {
    DAMAGE,
    PRAYER,
    DEFENCE,
    MAGIC_DEFENCE,
    HYBRID
  }

  public enum CostPolicy {
    EFFICIENT,
    MAX_DPS,
    LOW_RISK
  }

  public enum DamageProfile {
    FIXED,
    ZERO_WHILE_PROTECTED,
    ZERO_WHILE_SAFESPOTTING,
    ESTIMATED_PER_KILL,
    BOSS_MECHANICS
  }

  public enum MethodTag {
    BARRAGE,
    CANNON,
    VENATOR,
    SAFESPOT,
    AUTOMATIC_STYLE_LOCKED,
    PREFERENCE_ONLY_ALTERNATIVE,
    MULTI_COMBAT,
    REQUIRED_SPECIAL_GEAR,
    BOSS,
    WILDERNESS,
    TURAEL_POINT_BOOST,
    CHINNING
  }

  private final CombatStyle style;
  private final ArmourFocus armourFocus;
  private final CostPolicy costPolicy;
  private final String method;
  private final String rationale;
  private final String selectionNote;
  private final String reviewDate;
  private final List<String> weapons;
  private final List<String> dpsWeapons;
  private final List<String> efficientWeaponPriorities;
  private final List<String> optionalItemPriorities;
  private final Set<MethodTag> methodTags;
  private final int prayers;
  private final int food;
  private final DamageProfile damageProfile;
  private final double damagePerKill;
  private final int minimumFoodSlots;
  private final int inventoryTargetSlots;
  private final boolean runePouch;
  private final boolean antivenom;
  private final boolean stamina;
  private final boolean strictWeaponProfile;
  private final boolean boss;
  private final boolean reviewed;

  private TaskStrategy(Builder builder) {
    style = builder.style;
    armourFocus = builder.armourFocus;
    costPolicy = builder.costPolicy;
    method = safe(builder.method, "Use a task-appropriate setup");
    rationale = safe(builder.rationale, "Task-specific combat profile");
    selectionNote = safe(builder.selectionNote, "");
    reviewDate = safe(builder.reviewDate, "");
    weapons = immutable(builder.weapons);
    dpsWeapons = immutable(builder.dpsWeapons);
    efficientWeaponPriorities = immutable(builder.efficientWeaponPriorities);
    optionalItemPriorities = immutable(builder.optionalItemPriorities);
    EnumSet<MethodTag> resolvedTags =
        builder.methodTags.isEmpty()
            ? EnumSet.noneOf(MethodTag.class)
            : EnumSet.copyOf(builder.methodTags);
    if (builder.boss) {
      resolvedTags.add(MethodTag.BOSS);
    }
    methodTags = immutableTags(resolvedTags);
    prayers = clamp(builder.prayers, 0, 12);
    food = clamp(builder.food, 0, 20);
    damageProfile = builder.damageProfile;
    damagePerKill = Math.max(0.0, builder.damagePerKill);
    minimumFoodSlots = clamp(builder.minimumFoodSlots, 0, food);
    inventoryTargetSlots = clamp(builder.inventoryTargetSlots, 0, 28);
    runePouch = builder.runePouch;
    antivenom = builder.antivenom;
    stamina = builder.stamina;
    strictWeaponProfile = builder.strictWeaponProfile;
    boss = builder.boss;
    reviewed = builder.reviewed;
  }

  public static Builder builder(CombatStyle style, String method) {
    return new Builder(style, method);
  }

  public String getRationale() {
    StringBuilder text = new StringBuilder(rationale);
    if (!selectionNote.isEmpty()) {
      text.append(' ').append(selectionNote);
    }
    if (reviewed && !reviewDate.isEmpty()) {
      text.append(" Reviewed ").append(reviewDate).append('.');
    }
    return text.toString();
  }

  public List<String> weapons() {
    if (costPolicy == CostPolicy.MAX_DPS && !dpsWeapons.isEmpty()) {
      return dpsWeapons;
    }
    if (costPolicy == CostPolicy.EFFICIENT && !efficientWeaponPriorities.isEmpty()) {
      return efficientWeaponPriorities;
    }
    return weapons;
  }

  public List<String> getWeaponPriorities() {
    return weapons;
  }

  public boolean hasTag(MethodTag tag) {
    return tag != null && methodTags.contains(tag);
  }

  public boolean fillsInventoryToTarget() {
    return inventoryTargetSlots > 0;
  }

  public int getRecommendedFoodSlots(int remainingKills) {
    switch (damageProfile) {
      case ZERO_WHILE_PROTECTED:
      case ZERO_WHILE_SAFESPOTTING:
        return 0;
      case ESTIMATED_PER_KILL:
        int kills = Math.max(1, remainingKills);
        int estimated = (int) Math.ceil((damagePerKill * kills) / 20.0);
        return clamp(Math.max(minimumFoodSlots, estimated), 0, food);
      case BOSS_MECHANICS:
      case FIXED:
      default:
        return food;
    }
  }

  public boolean needsRunePouch() {
    return runePouch;
  }

  public boolean needsAntivenom() {
    return antivenom;
  }

  public boolean needsStamina() {
    return stamina;
  }

  public TaskStrategy withAdditionalTags(MethodTag... tags) {
    Builder copy = copyBuilder(armourFocus, costPolicy, selectionNote);
    copy.tags(tags);
    return copy.build();
  }

  public TaskStrategy withLoadoutPolicy(ArmourFocus focus, CostPolicy policy) {
    ArmourFocus resolvedFocus = focus == null ? armourFocus : focus;
    CostPolicy resolvedPolicy = policy == null ? costPolicy : policy;
    if (resolvedFocus == armourFocus && resolvedPolicy == costPolicy) {
      return this;
    }
    return copyBuilder(resolvedFocus, resolvedPolicy, selectionNote).build();
  }

  public TaskStrategy withSelectionNote(String note) {
    return copyBuilder(armourFocus, costPolicy, note).build();
  }

  private Builder copyBuilder(ArmourFocus focus, CostPolicy policy, String note) {
    Builder copy =
        builder(style, method)
            .armourFocus(focus)
            .costPolicy(policy)
            .rationale(rationale)
            .selectionNote(note)
            .prayers(prayers)
            .food(food)
            .damageProfile(damageProfile)
            .damagePerKill(damagePerKill)
            .minimumFoodSlots(minimumFoodSlots)
            .inventoryTargetSlots(inventoryTargetSlots)
            .runePouch(runePouch)
            .antivenom(antivenom)
            .stamina(stamina)
            .strictWeaponProfile(strictWeaponProfile)
            .boss(boss);
    copy.weapons(weapons.toArray(new String[0]));
    copy.maxDpsWeapons(dpsWeapons.toArray(new String[0]));
    copy.efficientWeapons(efficientWeaponPriorities.toArray(new String[0]));
    copy.optionalItems(optionalItemPriorities.toArray(new String[0]));
    copy.tags(methodTags.toArray(new MethodTag[0]));
    if (reviewed) {
      copy.reviewed(reviewDate);
    }
    return copy;
  }

  private static List<String> immutable(List<String> source) {
    return Collections.unmodifiableList(new ArrayList<>(source));
  }

  private static Set<MethodTag> immutableTags(Set<MethodTag> source) {
    if (source == null || source.isEmpty()) {
      return Collections.emptySet();
    }
    return Collections.unmodifiableSet(EnumSet.copyOf(source));
  }

  private static int clamp(int value, int minimum, int maximum) {
    return Math.max(minimum, Math.min(maximum, value));
  }

  private static String safe(String value, String fallback) {
    return value == null || value.trim().isEmpty() ? fallback : value.trim();
  }

  public static final class Builder {
    private final CombatStyle style;
    private final String method;
    private ArmourFocus armourFocus = ArmourFocus.DAMAGE;
    private CostPolicy costPolicy = CostPolicy.EFFICIENT;
    private String rationale = "Task-specific combat profile";
    private String selectionNote = "";
    private String reviewDate = "";
    private final List<String> weapons = new ArrayList<>();
    private final List<String> dpsWeapons = new ArrayList<>();
    private final List<String> efficientWeaponPriorities = new ArrayList<>();
    private final List<String> optionalItemPriorities = new ArrayList<>();
    private final EnumSet<MethodTag> methodTags = EnumSet.noneOf(MethodTag.class);
    private int prayers = 3;
    private int food = 8;
    private DamageProfile damageProfile = DamageProfile.FIXED;
    private double damagePerKill;
    private int minimumFoodSlots;
    private int inventoryTargetSlots;
    private boolean runePouch;
    private boolean antivenom;
    private boolean stamina;
    private boolean strictWeaponProfile;
    private boolean boss;
    private boolean reviewed;

    private Builder(CombatStyle style, String method) {
      this.style = style == null ? CombatStyle.MELEE : style;
      this.method = method;
    }

    public Builder armourFocus(ArmourFocus value) {
      armourFocus = value == null ? ArmourFocus.DAMAGE : value;
      return this;
    }

    public Builder costPolicy(CostPolicy value) {
      costPolicy = value == null ? CostPolicy.EFFICIENT : value;
      return this;
    }

    public Builder rationale(String value) {
      rationale = value;
      return this;
    }

    public Builder selectionNote(String value) {
      selectionNote = value;
      return this;
    }

    public Builder weapons(String... values) {
      addAll(weapons, values);
      return this;
    }

    public Builder maxDpsWeapons(String... values) {
      addAll(dpsWeapons, values);
      return this;
    }

    public Builder efficientWeapons(String... values) {
      addAll(efficientWeaponPriorities, values);
      return this;
    }

    public Builder optionalItems(String... values) {
      addAll(optionalItemPriorities, values);
      return this;
    }

    public Builder tags(MethodTag... values) {
      if (values != null) {
        for (MethodTag value : values) {
          if (value != null) {
            methodTags.add(value);
          }
        }
      }
      return this;
    }

    public Builder prayers(int value) {
      prayers = value;
      return this;
    }

    public Builder food(int value) {
      food = value;
      return this;
    }

    public Builder damageProfile(DamageProfile value) {
      damageProfile = value == null ? DamageProfile.FIXED : value;
      return this;
    }

    public Builder damagePerKill(double value) {
      damagePerKill = Math.max(0.0, value);
      return this;
    }

