package com.slayerplus;

import java.util.*;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

public final class MasterRoutes {
  private static final Map<Integer, MasterRoute> ROUTES = createRoutes();

  private MasterRoutes() {}

  public static MasterRoute find(int masterId) {
    return ROUTES.get(masterId);
  }

  public static String getName(int masterId) {
    MasterRoute route = find(masterId);
    if (route != null) {
      return route.getName();
    }
    return masterId > 0 ? "Master ID " + masterId : "Unknown";
  }

  private static Map<Integer, MasterRoute> createRoutes() {
    Map<Integer, MasterRoute> routes = new LinkedHashMap<>();
    for (String[] row : ResourceTable.rows("slayer-master-routes.tsv", 8)) {
      int id = Integer.parseInt(row[0]);
      MasterRoute previous =
          routes.put(
              id,
              new MasterRoute(
                  id,
                  row[1],
                  new WorldPoint(
                      Integer.parseInt(row[2]), Integer.parseInt(row[3]), Integer.parseInt(row[4])),
                  new WorldPoint(Integer.parseInt(row[5]), Integer.parseInt(row[6]), 0),
                  row[7].split("\\|", -1)));
      if (previous != null) {
        throw new IllegalStateException("Duplicate Slayer master route: " + id);
      }
    }
    return Collections.unmodifiableMap(routes);
  }

  @Getter
  public static final class MasterRoute {
    private final int id;
    private final String name;
    private final WorldPoint destination;
    private final WorldPoint bank;
    private final List<String> returnItemFamilies;

    private MasterRoute(
        int id,
        String name,
        WorldPoint destination,
        WorldPoint bank,
        String... returnItemFamilies) {
      this.id = id;
      this.name = name;
      this.destination = destination;
      this.bank = bank;
      this.returnItemFamilies =
          Collections.unmodifiableList(
              Arrays.asList(
                  returnItemFamilies == null ? new String[0] : returnItemFamilies.clone()));
    }
  }
}

package com.slayerplus;

import java.util.*;
import java.util.function.Supplier;
import net.runelite.api.coords.WorldPoint;

final class BankRoutes {
  private static final List<WorldPoint> BANKS = load();
  static final String CONFIG_KEY = "visitedBanksV1";
  private static final int LIMIT = 512;
  private String profile;
  private final Set<WorldPoint> visited = new LinkedHashSet<>();

  void useProfile(String next, Supplier<String> saved) {
    if (Objects.equals(profile, next)) {
      return;
    }
    profile = next;
    visited.clear();
    if (next == null) {
      return;
    }
    String value = saved.get();
    if (value == null) {
      return;
    }
    for (String entry : value.split(";")) {
      if (visited.size() >= LIMIT) {
        break;
      }
      String[] parts = entry.split(",");
      if (parts.length != 3) {
        continue;
      }
      try {
        WorldPoint point =
            new WorldPoint(
                Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
        if (valid(point)) {
          visited.add(point);
        }
      } catch (NumberFormatException ignored) {
      }
    }
  }

  boolean remember(WorldPoint point, boolean instanced) {
    if (profile == null || instanced || !valid(point) || visited.size() >= LIMIT) {
      return false;
    }
    for (WorldPoint known : visited) {
      if (known.getPlane() == point.getPlane() && chebyshev(known, point) <= 8) {
        return false;
      }
    }
    return visited.add(point);
  }

  String serialize() {
    StringJoiner value = new StringJoiner(";");
    for (WorldPoint point : visited) {
      value.add(point.getX() + "," + point.getY() + "," + point.getPlane());
    }
    return value.toString();
  }

  private static boolean valid(WorldPoint point) {
    return point != null
        && point.getX() > 0
        && point.getX() < 16384
        && point.getY() > 0
        && point.getY() < 16384
        && point.getPlane() >= 0
        && point.getPlane() < 4;
  }

  WorldPoint nearest(WorldPoint from) {
    if (from == null) {
      return null;
    }
    WorldPoint best = null;
    long bestDistance = Long.MAX_VALUE;
    for (Collection<WorldPoint> banks : Arrays.asList(visited, BANKS)) {
      for (WorldPoint bank : banks) {
        long distance = chebyshev(from, bank) + (bank.getPlane() == from.getPlane() ? 0 : 1000);
        if (distance < bestDistance) {
          bestDistance = distance;
          best = bank;
        }
      }
    }
    return best;
  }

  private static long chebyshev(WorldPoint a, WorldPoint b) {
    return Math.max(Math.abs((long) a.getX() - b.getX()), Math.abs((long) a.getY() - b.getY()));
  }

  private static List<WorldPoint> load() {
    List<WorldPoint> banks = new ArrayList<>();
    for (String[] row : ResourceTable.rows("slayer-common-banks.tsv", 4)) {
      banks.add(
          new WorldPoint(
              Integer.parseInt(row[1]), Integer.parseInt(row[2]), Integer.parseInt(row[3])));
    }
    return Collections.unmodifiableList(banks);
  }
}

package com.slayerplus;

import java.util.List;

public final class SlayerEncounterStandards {
  private SlayerEncounterStandards() {}

  public static String cleanEncounterLabel(String value) {
    if (value == null || value.trim().isEmpty()) {
      return "Task";
    }
    return value
        .trim()
        .replaceFirst("(?i)^regular\\s+", "")
        .replaceFirst("(?i)\\s*\\((?:boss|bosses)\\)\\s*$", "")
        .replaceFirst("(?i)\\s*\\[(?:boss|bosses)\\]\\s*$", "")
        .replaceFirst("(?i)\\s*[-–—]\\s*(?:boss|bosses)\\s*$", "")
        .trim();
  }

  static boolean isDragonTask(String task) {
    return task.contains("dragon")
        && !task.startsWith("baby ")
        && !task.contains("dragonfly")
        && !task.contains("dragon impling");
  }

  static boolean isSafespot(TaskStrategy strategy) {
    return strategy != null
        && (strategy.hasTag(TaskStrategy.MethodTag.SAFESPOT)
            || strategy.getDamageProfile() == TaskStrategy.DamageProfile.ZERO_WHILE_SAFESPOTTING);
  }

  public static boolean validateBossDefinitions(
      List<VariantCatalog.EncounterDefinition> definitions) {
    if (definitions == null) {
      throw new IllegalStateException("Slayer boss catalog is unavailable");
    }
    for (VariantCatalog.EncounterDefinition definition : definitions) {
      if (definition == null) {
        throw new IllegalStateException("Null Slayer boss definition");
      }
      if (definition.getVariant() != null && !definition.getVariant().isBoss()) {
        throw new IllegalStateException(
            "Encounter definition uses a non-boss variant: " + definition.getTargetName());
      }
      if (safe(definition.getTargetName()).isEmpty()) {
        throw new IllegalStateException("Boss definition has no target name");
      }
      if (safe(definition.getLocation()).isEmpty()) {
        throw new IllegalStateException(
            "Boss definition has no location: " + definition.getTargetName());
      }
      if (cleanEncounterLabel(definition.getOptionLabel()).equals("Task")) {
        throw new IllegalStateException(
            "Boss definition has no display label: " + definition.getTargetName());
      }
    }
    return true;
  }

  private static String safe(String value) {
    return value == null ? "" : value.trim();
  }
}

package com.slayerplus;

import java.util.List;
import java.util.Locale;

final class SlayerText {
  private SlayerText() {}

  static String normalize(String value) {
    return value == null
        ? ""
        : value
            .toLowerCase(Locale.ENGLISH)
            .replace('\u2019', '\'')
            .replaceAll("[^a-z0-9]+", " ")
            .trim();
  }

  static String encounter(String value) {
    return normalize(value).replaceFirst("^the\\s+", "");
  }

  static boolean matchesAny(String value, List<String> fragments) {
    for (String fragment : fragments) {
      if (value.contains(fragment)) {
        return true;
      }
    }
    return false;
  }
}

package com.slayerplus;

import java.util.*;
import net.runelite.api.coords.WorldPoint;

final class SlayerTaskWaypoints {
  private static final Map<String, WorldPoint> WAYPOINTS = load();
  private static final Map<String, WorldPoint> MONSTER_WAYPOINTS = loadMonster();
  private static final Map<String, List<int[]>> PATH_STAGES = loadPaths();
  private static final Map<String, List<int[]>> AGILITY_SHORTCUTS = loadAgilityShortcuts();
  private static final Map<String, List<int[]>> COMBAT_TIERS = loadCombatTiers();
  private static final Map<String, WorldPoint> PRE_ENTRANCE = loadPreEntrance();

  private SlayerTaskWaypoints() {}

  static WorldPoint find(String creature, String location) {
    WorldPoint specific = findSpecific(creature, location, 0);
    return specific != null ? specific : find(location);
  }

  static WorldPoint findSpecific(String creature, String location) {
    return findSpecific(creature, location, 0);
  }

  static WorldPoint findSpecific(String creature, String location, int combatLevel) {
    if (creature == null) {
      return null;
    }
    String key = singular(normalize(creature)) + "|" + normalize(location);
    WorldPoint tiered = combatTierWaypoint(key, combatLevel);
    return tiered != null ? tiered : MONSTER_WAYPOINTS.get(key);
  }

  private static WorldPoint combatTierWaypoint(String key, int combatLevel) {
    List<int[]> tiers = COMBAT_TIERS.get(key);
    if (tiers == null) {
      return null;
    }
    for (int[] tier : tiers) {
      if (combatLevel >= tier[0]) {
        return new WorldPoint(tier[1], tier[2], tier[3]);
      }
    }
    return null;
  }

  static WorldPoint find(String location) {
    return location == null ? null : WAYPOINTS.get(normalize(location));
  }

  static List<WorldPoint> findPath(String creature, String location) {
    return findPath(creature, location, 0, 0);
  }

  static List<WorldPoint> findPath(
      String creature, String location, int agilityLevel, int combatLevel) {
    List<WorldPoint> path = new ArrayList<>();
    WorldPoint preEntrance =
        creature == null
            ? null
            : PRE_ENTRANCE.get(singular(normalize(creature)) + "|" + normalize(location));
    if (preEntrance != null) {
      path.add(preEntrance);
    }
    WorldPoint entrance = agilityEntrance(creature, location, agilityLevel);
    if (entrance == null) {
      entrance = find(location);
    }
    if (entrance != null) {
      path.add(entrance);
    }
    List<WorldPoint> stages =
        creature == null
            ? null
            : pathStages(singular(normalize(creature)) + "|" + normalize(location), agilityLevel);
    if (stages != null) {
      path.addAll(stages);
    }
    WorldPoint interior = findSpecific(creature, location, combatLevel);
    if (interior != null && (path.isEmpty() || !path.get(path.size() - 1).equals(interior))) {
      path.add(interior);
    }
    return Collections.unmodifiableList(path);
  }

  private static List<WorldPoint> pathStages(String key, int agilityLevel) {
    List<int[]> rows = PATH_STAGES.get(key);
    if (rows == null) {
      return null;
    }
    int bestVariant = -1;
    for (int[] row : rows) {
      if (row[0] <= agilityLevel && row[0] > bestVariant) {
        bestVariant = row[0];
      }
    }
    if (bestVariant < 0) {
      return null;
    }
    List<int[]> matched = new ArrayList<>();
    for (int[] row : rows) {
      if (row[0] == bestVariant) {
        matched.add(row);
      }
    }
    matched.sort(Comparator.comparingInt(value -> value[1]));
    List<WorldPoint> points = new ArrayList<>();
    for (int[] row : matched) {
      points.add(new WorldPoint(row[2], row[3], row[4]));
    }
    return points;
  }

  private static WorldPoint agilityEntrance(String creature, String location, int agilityLevel) {
    if (creature == null) {
      return null;
    }
    List<int[]> shortcuts =
        AGILITY_SHORTCUTS.get(singular(normalize(creature)) + "|" + normalize(location));
    if (shortcuts == null) {
      return null;
    }
    for (int[] shortcut : shortcuts) {
      if (agilityLevel >= shortcut[0]) {
        return new WorldPoint(shortcut[1], shortcut[2], shortcut[3]);
      }
    }
    return null;
  }

  private static String normalize(String value) {
    return value == null ? "" : value.trim().toLowerCase(Locale.ENGLISH);
  }

  private static String singular(String value) {
    if (value.equals("jellies")) {
      return "jelly";
    }
    return value.length() > 3 && value.endsWith("s") && !value.endsWith("ss")
        ? value.substring(0, value.length() - 1)
        : value;
  }

  private static Map<String, WorldPoint> load() {
    Map<String, WorldPoint> map = new HashMap<>();
    for (String[] row : ResourceTable.rows("slayer-task-waypoints.tsv", 4)) {
      map.put(
          normalize(row[0]),
          new WorldPoint(
              Integer.parseInt(row[1]), Integer.parseInt(row[2]), Integer.parseInt(row[3])));
    }
    return Collections.unmodifiableMap(map);
  }

  private static Map<String, WorldPoint> loadMonster() {
    Map<String, WorldPoint> map = new HashMap<>();
    for (String[] row : ResourceTable.rows("slayer-task-monster-waypoints.tsv", 5)) {
      map.put(
          singular(normalize(row[0])) + "|" + normalize(row[1]),
          new WorldPoint(
              Integer.parseInt(row[2]), Integer.parseInt(row[3]), Integer.parseInt(row[4])));
    }
    return Collections.unmodifiableMap(map);
  }

  private static Map<String, List<int[]>> loadPaths() {
    Map<String, List<int[]>> map = new HashMap<>();
    for (String[] row : ResourceTable.rows("slayer-task-monster-waypoint-paths.tsv", 7)) {
      String key = singular(normalize(row[0])) + "|" + normalize(row[1]);
      map.computeIfAbsent(key, unused -> new ArrayList<>())
          .add(
              new int[] {
                Integer.parseInt(row[2]),
                Integer.parseInt(row[3]),
                Integer.parseInt(row[4]),
                Integer.parseInt(row[5]),
                Integer.parseInt(row[6])
              });
    }
    for (Map.Entry<String, List<int[]>> entry : map.entrySet()) {
      entry.setValue(Collections.unmodifiableList(entry.getValue()));
    }
    return Collections.unmodifiableMap(map);
  }

  private static Map<String, List<int[]>> loadAgilityShortcuts() {
    return loadTieredCoordinates("slayer-task-agility-shortcuts.tsv");
  }

  private static Map<String, List<int[]>> loadCombatTiers() {
    return loadTieredCoordinates("slayer-task-monster-waypoint-tiers.tsv");
  }

  private static Map<String, List<int[]>> loadTieredCoordinates(String resource) {
    Map<String, List<int[]>> map = new HashMap<>();
    for (String[] row : ResourceTable.rows(resource, 6)) {
      String key = singular(normalize(row[0])) + "|" + normalize(row[1]);
      map.computeIfAbsent(key, unused -> new ArrayList<>())
          .add(
              new int[] {
                Integer.parseInt(row[2]),
                Integer.parseInt(row[3]),
                Integer.parseInt(row[4]),
                Integer.parseInt(row[5])
              });
    }
    for (List<int[]> tiers : map.values()) {
      tiers.sort((a, b) -> Integer.compare(b[0], a[0]));
    }
    return Collections.unmodifiableMap(map);
  }

  private static Map<String, WorldPoint> loadPreEntrance() {
    Map<String, WorldPoint> map = new HashMap<>();
    for (String[] row : ResourceTable.rows("slayer-task-pre-entrance.tsv", 5)) {
      String key = singular(normalize(row[0])) + "|" + normalize(row[1]);
      map.put(
          key,
          new WorldPoint(
              Integer.parseInt(row[2]), Integer.parseInt(row[3]), Integer.parseInt(row[4])));
    }
    return Collections.unmodifiableMap(map);
  }
}

package com.slayerplus;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Point2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.awt.image.ConvolveOp;
import java.awt.image.Kernel;
import java.io.IOException;
import java.io.InputStream;
import java.time.LocalTime;
import javax.imageio.ImageIO;
import javax.swing.JPanel;
import javax.swing.Timer;

public class PlayerPortraitPanel extends JPanel {
  private static final int SIZE = 144;
  private static final int PORTRAIT_SIZE = 140;
  private static final int[] SKY_STARTS = {
    0, 120, 240, 330, 420, 570, 720, 870, 1020, 1140, 1260, 1380
  };
  private static final BufferedImage[] SKIES = {
    loadImage("portrait-night.png"),
    loadImage("portrait-night-right.png"),
    loadImage("portrait-predawn.png"),
    loadImage("portrait-dawn.png"),
    loadImage("portrait-morning.png"),
    loadImage("portrait-late-morning.png"),
    loadImage("portrait-day.png"),
    loadImage("portrait-afternoon.png"),
    loadImage("portrait-golden-hour.png"),
    loadImage("portrait-dusk.png"),
    loadImage("portrait-night-left.png"),
    loadImage("portrait-late-evening.png")
  };
  private static final BufferedImage PLACEHOLDER = loadImage("portrait-placeholder.png");
  private static final Shape FRAME = new RoundRectangle2D.Float(1, 1, 141, 141, 11, 11);
  private static final Color BORDER = new Color(79, 102, 133);
  private static final Color INNER_HIGHLIGHT = new Color(255, 255, 255, 38);
  private static final RadialGradientPaint LIGHT_PORTRAIT_GLOW =
      portraitGlow(new Color(2, 7, 13, 40), new Color(4, 10, 18, 12));
  private static final RadialGradientPaint DARK_PORTRAIT_GLOW =
      portraitGlow(new Color(235, 246, 255, 48), new Color(190, 218, 238, 13));
  private static final RadialGradientPaint VIGNETTE =
      new RadialGradientPaint(
          new Point2D.Float(72, 72),
          88,
          new float[] {0.56f, 1.0f},
          new Color[] {new Color(0, 0, 0, 0), new Color(0, 3, 9, 106)});
  private final Timer clockTimer = new Timer(60_000, event -> repaint());
  private final Timer fadeTimer = new Timer(33, event -> advanceFade());
  private BufferedImage portrait;
  private BufferedImage portraitShadow;
  private BufferedImage previousPortrait;
  private BufferedImage previousPortraitShadow;
  private long fadeStartedAtNanos;
  private boolean portraitIsDark;

  public PlayerPortraitPanel() {
    setOpaque(false);
    Dimension size = new Dimension(SIZE, SIZE);
    setPreferredSize(size);
    setMinimumSize(size);
    setMaximumSize(size);
    clockTimer.setRepeats(true);
    fadeTimer.setRepeats(true);
  }

  public void setPortrait(BufferedImage image) {
    fadeTimer.stop();
    previousPortrait = portrait;
    previousPortraitShadow = portraitShadow;
    portrait = image;
    portraitShadow = image == null ? null : createShadow(image);
    portraitIsDark = image != null && isMostlyDark(image);
    if (image != null && previousPortrait != null && isDisplayable()) {
      fadeStartedAtNanos = System.nanoTime();
      fadeTimer.start();
    } else {
      clearPreviousPortrait();
    }
    repaint();
  }

  @Override
  public void addNotify() {
    super.addNotify();
    clockTimer.start();
    if (previousPortrait != null && portrait != null && fadeProgress() < 1.0f) {
      fadeTimer.start();
    }
  }

  @Override
  public void removeNotify() {
    disposeTimers();
    super.removeNotify();
  }

  public void disposeTimers() {
    clockTimer.stop();
    fadeTimer.stop();
  }

  @Override
  protected void paintComponent(Graphics graphics) {
    super.paintComponent(graphics);
    LocalTime now = LocalTime.now();
    Graphics2D g = (Graphics2D) graphics.create();
    g.setClip(FRAME);
    quality(g);
    drawBackdrop(g, now);
    if (portrait != null) {
      g.setPaint(portraitIsDark ? DARK_PORTRAIT_GLOW : LIGHT_PORTRAIT_GLOW);
      g.fillRect(0, 0, SIZE, SIZE);
      int position = (SIZE - PORTRAIT_SIZE) / 2;
      float progress = fadeProgress();
      drawPortrait(g, previousPortrait, previousPortraitShadow, position, 1.0f - progress);
      drawPortrait(g, portrait, portraitShadow, position, progress);
    } else {
      g.drawImage(PLACEHOLDER, 0, 0, null);
    }
    g.setPaint(VIGNETTE);
    g.fillRect(0, 0, SIZE, SIZE);
    g.setClip(null);
    g.setColor(BORDER);
    g.setStroke(new BasicStroke(1.4f));
    g.draw(FRAME);
    g.setColor(INNER_HIGHLIGHT);
    g.setStroke(new BasicStroke());
    g.draw(new RoundRectangle2D.Float(2.5f, 2.5f, 138, 138, 9, 9));
    g.dispose();
  }

  private static void drawBackdrop(Graphics2D graphics, LocalTime time) {
    int minute = time.getHour() * 60 + time.getMinute();
    int index = 0;
    for (index = SKY_STARTS.length - 1; index > 0; index--) {
      if (minute >= SKY_STARTS[index]) {
        break;
      }
    }
    int next = (index + 1) % SKIES.length;
    int nextStart = next == 0 ? 1440 : SKY_STARTS[next];
    graphics.drawImage(SKIES[index], 0, 0, SIZE, SIZE, null);
    int minutesUntilNext = nextStart - minute;
    if (minutesUntilNext > 30) {
      return;
    }
    float blend = 1.0f - minutesUntilNext / 30.0f;
    graphics.setComposite(AlphaComposite.SrcOver.derive(blend));
    graphics.drawImage(SKIES[next], 0, 0, SIZE, SIZE, null);
    graphics.setComposite(AlphaComposite.SrcOver);
  }

  private static BufferedImage loadImage(String name) {
    try (InputStream stream = PlayerPortraitPanel.class.getResourceAsStream(name)) {
      if (stream == null) {
        throw new IllegalStateException("Missing portrait image: " + name);
      }
      BufferedImage image = ImageIO.read(stream);
      if (image == null) {
        throw new IllegalStateException("Invalid portrait image: " + name);
      }
      return image;
    } catch (IOException exception) {
      throw new IllegalStateException("Unable to load portrait image: " + name, exception);
    }
  }

  private void advanceFade() {
    if (fadeProgress() >= 1.0f) {
      fadeTimer.stop();
      clearPreviousPortrait();
    }
    repaint();
  }

  private float fadeProgress() {
    if (previousPortrait == null || portrait == null) {
      return 1.0f;
    }
    return Math.min(1.0f, (System.nanoTime() - fadeStartedAtNanos) / (230 * 1_000_000.0f));
  }

  private void clearPreviousPortrait() {
    previousPortrait = null;
    previousPortraitShadow = null;
  }

  private static void drawPortrait(
      Graphics2D g, BufferedImage image, BufferedImage shadow, int position, float alpha) {
    if (image == null || alpha <= 0) {
      return;
    }
    if (shadow != null) {
      g.setComposite(AlphaComposite.SrcOver.derive(alpha * 0.42f));
      g.drawImage(shadow, position, position + 3, null);
    }
    g.setComposite(AlphaComposite.SrcOver.derive(alpha));
    g.drawImage(image, position, position, null);
    g.setComposite(AlphaComposite.SrcOver);
  }

  private static BufferedImage createShadow(BufferedImage source) {
    BufferedImage silhouette =
        new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);
    for (int y = 0; y < source.getHeight(); y++) {
      for (int x = 0; x < source.getWidth(); x++) {
        int alpha = source.getRGB(x, y) >>> 24;
        silhouette.setRGB(x, y, Math.min(150, alpha) << 24);
      }
    }
    float[] values = {
      1, 2, 3, 2, 1, 2, 4, 6, 4, 2, 3, 6, 9, 6, 3, 2, 4, 6, 4, 2, 1, 2, 3, 2, 1
    };
    for (int index = 0; index < values.length; index++) {
      values[index] /= 81;
    }
    return new ConvolveOp(new Kernel(5, 5, values), ConvolveOp.EDGE_NO_OP, null)
        .filter(silhouette, null);
  }

  private static boolean isMostlyDark(BufferedImage image) {
    long luminance = 0;
    long alphaTotal = 0;
    for (int y = 0; y < image.getHeight(); y += 2) {
      for (int x = 0; x < image.getWidth(); x += 2) {
        int argb = image.getRGB(x, y);
        int alpha = argb >>> 24;
        int light =
            (((argb >>> 16) & 0xFF) * 54
                    + ((argb >>> 8) & 0xFF) * 183
                    + (argb & 0xFF) * 19)
                >> 8;
        luminance += (long) light * alpha;
        alphaTotal += alpha;
      }
    }
    return alphaTotal > 0 && luminance / alphaTotal < 112;
  }

  private static void quality(Graphics2D g) {
    g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
    g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
    g.setRenderingHint(
        RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
  }

  private static RadialGradientPaint portraitGlow(Color center, Color middle) {
    return new RadialGradientPaint(
        new Point2D.Float(SIZE / 2.0f, SIZE * 0.48f),
        58,
        new float[] {0.0f, 0.74f, 1.0f},
        new Color[] {center, middle, new Color(0, 0, 0, 0)});
  }

}

package com.slayerplus;

import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

class SlayerBraceletChargeInfoBox extends InfoBox {
  private static final long DEPLETED_PULSE_PERIOD_MILLIS = 2400L;
  private static final Color DEPLETED_RED = new Color(220, 55, 55);
  private static final Color DEPLETED_GREY = new Color(115, 105, 105);
  private int charges;
  private final String braceletName;

  SlayerBraceletChargeInfoBox(
      BufferedImage image, Plugin plugin, String braceletName, int charges) {
    super(charges == 0 ? dullDepletedImage(image) : image, plugin);
    this.braceletName = braceletName;
    setCharges(charges);
  }

  boolean isDepleted() {
    return charges == 0;
  }

  void setCharges(int charges) {
    this.charges = charges;
    setTooltip(
        braceletName
            + ": "
            + (charges < 0
                ? "right-click Check to learn charges"
                : charges + " charges remaining"));
  }

  @Override
  public String getText() {
    return charges < 0 ? "?" : Integer.toString(charges);
  }

  @Override
  public Color getTextColor() {
    if (charges == 0) {
      return depletedTextColorForTest(System.currentTimeMillis());
    }
    if (charges > 0 && charges <= 2) {
      return Color.RED;
    }
    if (charges <= 5) {
      return Color.YELLOW;
    }
    return Color.WHITE;
  }

  static Color depletedTextColorForTest(long nowMillis) {
    double phase =
        (nowMillis % DEPLETED_PULSE_PERIOD_MILLIS) / (double) DEPLETED_PULSE_PERIOD_MILLIS;
    double blend = (Math.sin(phase * Math.PI * 2.0) + 1.0) / 2.0;
    return blend(DEPLETED_GREY, DEPLETED_RED, blend);
  }

  private static Color blend(Color from, Color to, double amount) {
    return new Color(
        (int) Math.round(from.getRed() + (to.getRed() - from.getRed()) * amount),
        (int) Math.round(from.getGreen() + (to.getGreen() - from.getGreen()) * amount),
        (int) Math.round(from.getBlue() + (to.getBlue() - from.getBlue()) * amount));
  }

  private static BufferedImage dullDepletedImage(BufferedImage source) {
    if (source == null) {
      return null;
    }
    BufferedImage result =
        new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);
    for (int y = 0; y < source.getHeight(); y++) {
      for (int x = 0; x < source.getWidth(); x++) {
        int argb = source.getRGB(x, y);
        int alpha = argb >>> 24;
        int red = argb >>> 16 & 0xff;
        int green = argb >>> 8 & 0xff;
        int blue = argb & 0xff;
        int grey = (red * 30 + green * 59 + blue * 11) / 100;
        int mutedRed = Math.min(255, grey * 3 / 4 + 45);
        int mutedOther = grey * 3 / 5;
        result.setRGB(x, y, alpha << 24 | mutedRed << 16 | mutedOther << 8 | mutedOther);
      }
    }
    return result;
  }
}

