  private static MethodRules.DamageControl resolveDamageControl(TaskStrategy strategy) {
    if (strategy == null) {
      return MethodRules.DamageControl.STRATEGY_DEFINED;
    }
    if (strategy.getDamageProfile() == TaskStrategy.DamageProfile.ZERO_WHILE_PROTECTED) {
      return MethodRules.DamageControl.PRAYER_PROTECTED;
    }
    if (strategy.getDamageProfile() == TaskStrategy.DamageProfile.ZERO_WHILE_SAFESPOTTING) {
      return MethodRules.DamageControl.SAFESPOT;
    }
    if (strategy.hasTag(TaskStrategy.MethodTag.SAFESPOT)) {
      return MethodRules.DamageControl.SAFESPOT;
    }
    if (strategy.isBoss()) {
      return MethodRules.DamageControl.BOSS_MECHANICS;
    }
    return MethodRules.DamageControl.DIRECT_DAMAGE;
  }

  private static MethodRules.LayoutProfile resolveLayoutProfile(
      String location, TaskStrategy strategy, MethodRules.DamageControl control) {
    if (isWilderness(location)) {
      return MethodRules.LayoutProfile.WILDERNESS;
    }
    if (strategy == null) {
      return MethodRules.LayoutProfile.STANDARD;
    }
    if (strategy.isBoss()) {
      return strategy.getStyle() == TaskStrategy.CombatStyle.HYBRID
          ? MethodRules.LayoutProfile.HYBRID_BOSS
          : MethodRules.LayoutProfile.BOSS;
    }
    if (strategy.hasTag(TaskStrategy.MethodTag.BARRAGE)) {
      return MethodRules.LayoutProfile.BARRAGE;
    }
    if (strategy.hasTag(TaskStrategy.MethodTag.CANNON)) {
      return MethodRules.LayoutProfile.CANNON;
    }
    if (control == MethodRules.DamageControl.PRAYER_PROTECTED) {
      return MethodRules.LayoutProfile.PRAYER_TASK;
    }
    return MethodRules.LayoutProfile.STANDARD;
  }

  private static String resolveConciseTaskMethod(String assignment, TaskStrategy strategy) {
    if (strategy != null && strategy.isBoss()) {
      var bossMethod = bossMethod(assignment, strategy);
      if (!bossMethod.isEmpty()) {
        return concise(bossMethod);
      }
    }
    if (strategy != null && !safe(strategy.getMethod()).isEmpty()) {
      return concise(strategy.getMethod());
    }
    return "Use the reviewed setup and follow the encounter's required protection and positioning.";
  }

  private static String bossMethod(String bossName, TaskStrategy strategy) {
    var boss = normalize(bossName);
    var style = strategy == null ? null : strategy.getStyle();
    if (boss.equals("k ril tsutsaroth")) {
      return style == TaskStrategy.CombatStyle.RANGED
          ? "Use the selected Scorching bow setup."
          : "Use the selected demonbane melee setup.";
    }
    if (boss.equals("general graardor")) {
      return style == TaskStrategy.CombatStyle.RANGED
          ? "Use the selected ranged setup."
          : "Use the selected melee setup.";
    }
    return BOSS_METHODS.getOrDefault(boss, "");
  }

  private static Map<String, String> loadBossMethods() {
    Map<String, String> methods = new LinkedHashMap<>();
    for (String[] row : ResourceTable.rows("slayer-boss-method-guidance.tsv", 2)) {
      var previous = methods.put(normalize(row[0]), row[1]);
      if (previous != null) {
        throw new IllegalStateException("Duplicate boss method: " + row[0]);
      }
    }
    return Collections.unmodifiableMap(methods);
  }

  private static String concise(String value) {
    var clean = safe(value).replaceAll("\\s+", " ");
    if (clean.isEmpty()) {
      return clean;
    }
    var secondSentence = clean.indexOf(". ");
    if (secondSentence > 35 && secondSentence + 1 <= MethodRules.MAX_TASK_METHOD_LENGTH) {
      clean = clean.substring(0, secondSentence + 1);
    }
    if (clean.length() > MethodRules.MAX_TASK_METHOD_LENGTH) {
      var cut = clean.lastIndexOf(' ', MethodRules.MAX_TASK_METHOD_LENGTH - 1);
      if (cut < 80) {
        cut = MethodRules.MAX_TASK_METHOD_LENGTH - 1;
      }
      clean = clean.substring(0, cut).trim();
    }
    var last = clean.charAt(clean.length() - 1);
    return last == '.' || last == '!' || last == '?' ? clean : clean + ".";
  }

  private static String buildCoverageKey(
      String assignment, String location, TaskStrategy strategy) {
    return normalize(assignment)
        + "|"
        + normalize(location)
        + "|"
        + (strategy == null ? "none" : strategy.getStyle().name())
        + "|"
        + normalize(strategy == null ? "" : strategy.getMethod());
  }

  private static String wikiSource(String assignment, TaskStrategy strategy) {
    var name = safe(assignment).replaceFirst("(?i)^the\\s+", "");
    return strategy != null && strategy.isBoss()
        ? "OSRS Wiki: " + name + "/Strategies"
        : "OSRS Wiki: Slayer task/" + name;
  }

  private static boolean preventsExpectedDamage(MethodRules.DamageControl value) {
    return value == MethodRules.DamageControl.PRAYER_PROTECTED
        || value == MethodRules.DamageControl.SAFESPOT
        || value == MethodRules.DamageControl.FREEZE_SAFESPOT;
  }

  private static boolean isWilderness(String value) {
    var normalized = normalize(value);
    return normalized.contains("wilderness")
        || normalized.contains("revenant caves")
        || normalized.contains("deep wild");
  }

  private static boolean contains(String text, String part) {
    return safe(text).toLowerCase(Locale.ENGLISH).contains(safe(part).toLowerCase(Locale.ENGLISH));
  }

  private static boolean containsAny(String text, String... fragments) {
    for (String fragment : fragments) {
      if (text.contains(fragment)) {
        return true;
      }
    }
    return false;
  }

  private static String normalize(String value) {
    return SlayerText.encounter(value);
  }

  private static String safe(String value) {
    return value == null ? "" : value.trim();
  }
}

package com.slayerplus;

import java.util.*;

public final class SlayerDisplayText {
  private static final String TEST_PREFIX = "TEST:";
  private static final String REVIEW_PENDING_SUFFIX = " — strategy review pending";
  private static final Map<String, String> CANONICAL_TASK_NAMES = createCanonicalTaskNames();

  private SlayerDisplayText() {}

  public static String assignment(String value) {
    if (value == null || value.trim().isEmpty()) {
      return "Unknown task";
    }
    String task = value.trim();
    boolean simulated = task.regionMatches(true, 0, TEST_PREFIX, 0, TEST_PREFIX.length());
    if (simulated) {
      task = task.substring(TEST_PREFIX.length()).trim();
    }
    String canonical = canonicalTaskName(task);
    return simulated ? TEST_PREFIX + " " + canonical : canonical;
  }

  public static String bankSetupTitle(String value) {
    if (value == null || value.trim().isEmpty()) {
      return "Waiting for Slayer task";
    }
    String title = value.trim();
    if (title.equalsIgnoreCase("Waiting for Slayer task")) {
      return "Waiting for Slayer task";
    }
    if (title.equalsIgnoreCase("Recommended setup")) {
      return "Recommended setup";
    }
    if (title.equalsIgnoreCase("Loadout recommendations disabled")) {
      return "Loadout recommendations disabled";
    }
    if (title
        .toLowerCase(Locale.ENGLISH)
        .endsWith(REVIEW_PENDING_SUFFIX.toLowerCase(Locale.ENGLISH))) {
      String task = title.substring(0, title.length() - REVIEW_PENDING_SUFFIX.length()).trim();
      return assignment(task) + REVIEW_PENDING_SUFFIX;
    }
    return assignment(title);
  }

  private static String canonicalTaskName(String task) {
    String key = normalize(task);
    String canonical = CANONICAL_TASK_NAMES.get(key);
    if (canonical != null) {
      return canonical;
    }
    String lower = task.toLowerCase(Locale.ENGLISH);
    return lower.isEmpty() ? "Unknown task" : titleCaseWords(lower);
  }

  private static Map<String, String> createCanonicalTaskNames() {
    Map<String, String> names = new LinkedHashMap<>();
    for (String reviewedName : TaskResearch.getReviewedTaskNames()) {
      names.put(normalize(reviewedName), titleCaseWords(reviewedName));
    }
    addBossNames(names, VariantCatalog.getBossDefinitions());
    addBossNames(names, VariantCatalog.getDirectBossDefinitions());
    return Collections.unmodifiableMap(names);
  }

  private static void addBossNames(
      Map<String, String> names, Iterable<VariantCatalog.EncounterDefinition> definitions) {
    for (VariantCatalog.EncounterDefinition definition : definitions) {
      String displayName = definition.getDisplayName();
      String canonicalDisplayName = titleCaseWords(displayName);
      names.put(normalize(definition.getEncounter()), canonicalDisplayName);
      names.put(normalize(displayName), canonicalDisplayName);
    }
  }

  private static String titleCaseWords(String value) {
    String[] words = value.trim().split("\\s+");
    StringBuilder result = new StringBuilder();
    for (String word : words) {
      if (word.isEmpty()) {
        continue;
      }
      if (result.length() > 0) {
        result.append(' ');
      }
      result.append(Character.toUpperCase(word.charAt(0)));
      if (word.length() > 1) {
        result.append(word.substring(1));
      }
    }
    return result.toString();
  }

  private static String normalize(String value) {
    return value == null ? "" : value.trim().toLowerCase(Locale.ENGLISH).replaceAll("\\s+", " ");
  }
}

package com.slayerplus;

import java.util.*;
import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;

class SlayerRegularInventoryAuditCatalog {
  private static final Policy DIRECT = new Policy(2, 6, 12, true);
  private static final Policy SAFESPOT = new Policy(0, 0, 24, true);
  private static final Policy PRAYER = new Policy(5, 0, 16, true);
  private static final Map<String, Policy> POLICIES = createPolicies();

  private SlayerRegularInventoryAuditCatalog() {}

  static void apply(String assignment, MethodRules.Builder rules, TaskStrategy strategy) {
    String task = normalize(assignment);
    Policy policy = POLICIES.get(task);
    if (policy != null) {
      policy.apply(rules, strategy);
      applyTaskSpecificSupplies(task, rules, strategy);
      return;
    }
    MethodRules.DamageControl control =
        strategy == null
            ? MethodRules.DamageControl.DIRECT_DAMAGE
            : strategy.getDamageProfile() == TaskStrategy.DamageProfile.ZERO_WHILE_PROTECTED
                ? MethodRules.DamageControl.PRAYER_PROTECTED
                : strategy.getDamageProfile() == TaskStrategy.DamageProfile.ZERO_WHILE_SAFESPOTTING
                    ? MethodRules.DamageControl.SAFESPOT
                    : MethodRules.DamageControl.DIRECT_DAMAGE;
    (control == MethodRules.DamageControl.SAFESPOT
            ? SAFESPOT
            : control == MethodRules.DamageControl.PRAYER_PROTECTED ? PRAYER : DIRECT)
        .apply(rules, strategy);
  }

  static int sizeForTest() {
    return POLICIES.size();
  }

  private static void applyTaskSpecificSupplies(
      String task, MethodRules.Builder rules, TaskStrategy strategy) {
    if (task.equals("bandits") || task.equals("crocodiles") || task.equals("lizards")) {
      rules.require(
          "Desert heat protection",
          1,
          MethodRules.InventoryGroup.PROTECTION,
          "circlet of water",
          "desert amulet 4",
          "waterskin 4",
          "waterskin 3",
          "waterskin 2",
          "waterskin 1");
    }
    if (task.equals("harpie bug swarms")) {
      rules
          .restore("prayer potion", "super restore")
          .restoreSlots(3)
          .food(6)
          .loot(10)
          .require(
              "Poison protection",
              1,
              MethodRules.InventoryGroup.PROTECTION,
              "antidote plus plus",
              "superantipoison",
              "antipoison")
          .require("Nature runes", 200, MethodRules.InventoryGroup.RUNES, "nature rune");
    }
    if (task.equals("spiritual creatures")) {
      rules.require(
          PotionPolicy.EXTENDED_STAMINA_DISPLAY,
          1,
          MethodRules.InventoryGroup.UTILITY,
          PotionPolicy.staminaAlternatives());
    }
    if (task.equals("greater demons")) {
      rules.require("Ash sanctifier", 1, MethodRules.InventoryGroup.UTILITY, "ash sanctifier");
    }
    if (task.equals("basilisks")) {
      boolean ranged = strategy != null && strategy.getStyle() == TaskStrategy.CombatStyle.RANGED;
      rules
          .restore("prayer potion", "super restore")
          .restoreSlots(6)
          .food(ranged ? 0 : 6)
          .loot(ranged ? 16 : 9)
          .spell(MethodRules.Spellbook.STANDARD, "Telekinetic Grab / High Level Alchemy")
          .runePouch(true)
          .pouchRune(net.runelite.api.gameval.ItemID.AIRRUNE, "Air", 500)
          .pouchRune(net.runelite.api.gameval.ItemID.LAWRUNE, "Law", 200)
          .pouchRune(net.runelite.api.gameval.ItemID.NATURERUNE, "Nature", 200);
    }
    if (task.equals("aquanites")) {
      rules
          .restore("prayer potion", "super restore")
          .restoreSlots(5)
          .food(4)
          .loot(10)
          .spell(MethodRules.Spellbook.STANDARD, "High Level Alchemy")
          .runePouch(true)
          .pouchRune(net.runelite.api.gameval.ItemID.FIRERUNE, "Fire", 1000)
          .pouchRune(net.runelite.api.gameval.ItemID.NATURERUNE, "Nature", 250)
          .require(
              "Fast Slash lure-severing weapon",
              1,
              MethodRules.InventoryGroup.SWITCH,
              "saradomin godsword",
              "dragon claws",
              "voidwaker",
              "abyssal whip",
              "blade of saeldor",
              "dragon scimitar",
              "rune scimitar")
          .require("Seed box", 1, MethodRules.InventoryGroup.UTILITY, "seed box");
    }
    if (task.equals("skeletal wyvern") || task.equals("skeletal wyverns")) {
      TaskStrategy.CombatStyle style =
          strategy == null ? TaskStrategy.CombatStyle.MELEE : strategy.getStyle();
      boolean safespot =
          style == TaskStrategy.CombatStyle.RANGED || style == TaskStrategy.CombatStyle.MAGIC;
      rules
          .restore("prayer potion", "super restore")
          .restoreSlots(safespot ? 2 : 4)
          .food(safespot ? 6 : 8)
          .loot(safespot ? 16 : 11);
      if (style == TaskStrategy.CombatStyle.MELEE) {
        rules.require(
            "Special attack weapon",
            1,
            MethodRules.InventoryGroup.SWITCH,
            "voidwaker",
            "dragon claws",
            "burning claws",
            "dragon dagger p plus plus",
            "dragon dagger p plus",
            "dragon dagger p",
            "dragon dagger");
      }
      if (style != TaskStrategy.CombatStyle.MAGIC) {
        rules
            .spell(MethodRules.Spellbook.STANDARD, "High Level Alchemy")
            .runePouch(true)
            .pouchRune(net.runelite.api.gameval.ItemID.FIRERUNE, "Fire", 1000)
            .pouchRune(net.runelite.api.gameval.ItemID.NATURERUNE, "Nature", 250);
      }
    }
    if (task.equals("kalphite") || task.equals("kalphites")) {
      rules
          .restore("prayer potion", "super restore")
          .restoreSlots(5)
          .food(0)
          .loot(9)
          .require(
              "Poison protection",
              1,
              MethodRules.InventoryGroup.PROTECTION,
              "antidote plus plus",
              "sanfew serum",
              "superantipoison",
              "antipoison")
          .require(
              "Special attack weapon",
              1,
              MethodRules.InventoryGroup.SWITCH,
              "dragon dagger p plus plus",
              "dragon dagger p plus",
              "dragon dagger p",
              "dragon dagger");
    }
  }

  private static Map<String, Policy> createPolicies() {
    Map<String, Policy> map = new LinkedHashMap<>();
    for (String[] row : ResourceTable.rows("slayer-regular-inventory.tsv", 5)) {
      put(
          map,
          new Policy(
              Integer.parseInt(row[1]),
              Integer.parseInt(row[2]),
              Integer.parseInt(row[3]),
              Boolean.parseBoolean(row[4])),
          row[0]);
    }
    return Collections.unmodifiableMap(map);
  }

  private static void put(Map<String, Policy> map, Policy policy, String... taskNames) {
    for (String assignment : taskNames) {
      String key = normalize(assignment);
      if (map.put(key, policy) != null) {
        throw new IllegalStateException("Duplicate regular inventory audit: " + assignment);
      }
    }
  }

  private static String normalize(String value) {
    return SlayerText.encounter(value);
  }

  @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
  private static final class Policy {
    private final int restoreSlots;
    private final int food;
    private final int loot;
    private final boolean styleBoost;

    private void apply(MethodRules.Builder rules, TaskStrategy strategy) {
      boolean preventsExpectedDamage =
          strategy != null
              && (strategy.getDamageProfile() == TaskStrategy.DamageProfile.ZERO_WHILE_PROTECTED
                  || strategy.getDamageProfile()
                      == TaskStrategy.DamageProfile.ZERO_WHILE_SAFESPOTTING);
      rules
          .restore("prayer potion", "super restore")
          .restoreSlots(restoreSlots)
          .food(preventsExpectedDamage ? 0 : food)
          .loot(loot)
          .includeStyleBoost(styleBoost);
    }
  }
}

